window.__X_NEWS__ = {"updated_at": "2026-10-21 21:17 Asia/Shanghai", "updated_at_iso": "2026-10-21T13:17:44.000Z", "count": 89, "domains": ["科技", "商业", "中国", "国际", "体育", "娱乐", "科学"], "items": [{"id": "2112386205996245100", "domain": "科技", "title_en": "Sam Altman Outlines Three Paths for Safe Advanced AI Development", "title_zh": "奥特曼勾勒先进 AI 安全发展的三条路径", "hook_en": "Sam Altman gathered OpenAI staff to map out three stark options for handling super-smart AI, right as the Trump administration steps in with its own oversight plans.", "hook_zh": "萨姆·奥特曼召集 OpenAI 员工讨论应对超强 AI 的三条截然不同选项，恰逢特朗普政府推出自有监管计划。", "summary_en": "Last week, Altman described an international body like the IAEA to enforce safety at frontier labs, which he favors; a CERN-style merger of AI labs to share models, known as the 'Demis plan'; and a rejected idea of one lab dominating by disabling rivals' hardware, dubbed the 'Eliezer plan.' He stressed OpenAI must pick a path within a year to avoid falling behind competitors amid safety pressures. The talk coincides with the Trump administration's new Super Intelligence Force, using existing laws to tackle national security and civil liberties risks from advanced AI. Reports from The Information have sparked online talks on AI's future, blending safety concerns with hopes for shared prosperity.", "summary_zh": "上周奥特曼描述了三条路径：他倾向的类似国际原子能机构的国际机构以约束前沿实验室安全；被称为「Demis 方案」的类 CERN 实验室合并以共享模型；以及被否决的「Eliezer 方案」——由单一实验室通过瘫痪对手硬件来主导。他强调 OpenAI 须在一年内选定路径，以免在安全压力下落后于竞争对手。谈话正值特朗普政府成立「超级智能部队」，拟用现有法律应对先进 AI 带来的国家安全与公民自由风险。《The Information》相关报道引发网上对 AI 未来的讨论，交织安全关切与共享繁荣期待。", "body_en": "Sam Altman Outlines Three Paths for Safe Advanced AI Development.\n\nSam Altman gathered OpenAI staff to map out three stark options for handling super-smart AI, right as the Trump administration steps in with its own oversight plans.\n\nLast week, Altman described an international body like the IAEA to enforce safety at frontier labs, which he favors; a CERN-style merger of AI labs to share models, known as the 'Demis plan'; and a rejected idea of one lab dominating by disabling rivals' hardware, dubbed the 'Eliezer plan.' He stressed OpenAI must pick a path within a year to avoid falling behind competitors amid safety pressures.\n\nThe talk coincides with the Trump administration's new Super Intelligence Force, using existing laws to tackle national security and civil liberties risks from advanced AI. Reports from The Information have sparked online talks on AI's future, blending safety concerns with hopes for shared prosperity.", "body_zh": "奥特曼勾勒先进 AI 安全发展的三条路径。\n\n萨姆·奥特曼召集 OpenAI 员工讨论应对超强 AI 的三条截然不同选项，恰逢特朗普政府推出自有监管计划。\n\n上周奥特曼描述了三条路径：他倾向的类似国际原子能机构的国际机构以约束前沿实验室安全；被称为「Demis 方案」的类 CERN 实验室合并以共享模型；以及被否决的「Eliezer 方案」——由单一实验室通过瘫痪对手硬件来主导。他强调 OpenAI 须在一年内选定路径，以免在安全压力下落后于竞争对手。\n\n谈话正值特朗普政府成立「超级智能部队」，拟用现有法律应对先进 AI 带来的国家安全与公民自由风险。《The Information》相关报道引发网上对 AI 未来的讨论，交织安全关切与共享繁荣期待。", "url": "https://x.com/i/trending/2112386205996245100", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T14:10:55.000Z"}, {"id": "2112595601669919101", "domain": "科技", "title_en": "OpenAI Quiets Support for AI Chip Export Limits to China", "title_zh": "OpenAI 对限制对华出口 AI 芯片的立场明显降温", "hook_en": "OpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.", "hook_zh": "OpenAI 曾大力推动美国严格限制先进 AI 芯片输往中国，如今却基本不再发声。", "summary_en": "Last year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion. Critics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "summary_zh": "去年 OpenAI 曾游说限制英伟达处理器流向有北京背景的实验室；知情人士称公司已停止相关倡议。这一转向有利于英伟达，也与其 2025 年一项重大基础设施合作相呼应。", "body_en": "OpenAI Quiets Support for AI Chip Export Limits to China.\n\nOpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.\n\nLast year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion.\n\nCritics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "body_zh": "OpenAI 对限制对华出口 AI 芯片的立场明显降温。\n\nOpenAI 曾大力推动美国严格限制先进 AI 芯片输往中国，如今却基本不再发声。\n\n去年 OpenAI 曾游说限制英伟达处理器流向有北京背景的实验室；知情人士称公司已停止相关倡议。这一转向有利于英伟达，也与其 2025 年一项重大基础设施合作相呼应。\n\n综合以上信息，OpenAI 对限制对华出口 AI 芯片的立场明显降温一事持续引发关注。", "url": "https://x.com/i/trending/2112595601669919101", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:34:14.000Z"}, {"id": "2112540739628630161", "domain": "科技", "title_en": "Amazon Explores Offloading $8 Billion in Nvidia Chips to Investors", "title_zh": "亚马逊探讨向投资者转移约 80 亿美元英伟达芯片", "hook_en": "Amazon has thousands of cutting-edge Nvidia chips ready for its U.S. data centers, but power shortages mean many sit unused in warehouses.", "hook_zh": "大量先进英伟达芯片已备好进美国数据中心，却因电力不足堆在仓库。", "summary_en": "The company is in talks to shift about $8 billion worth of Grace Blackwell chips into a special-purpose vehicle, which would lease them back to Amazon and raise funds through debt and a small equity stake. This comes as internal documents reveal a massive influx of Nvidia GB300 racks—$5 billion in one month alone—piling up due to insufficient power and infrastructure in data centers across Nevada and Virginia. Observers note the timing raises questions about Amazon's AI hardware glut amid its $220 billion capital spending push, though some see the move as smart financing to keep using the chips without owning them outright.", "summary_zh": "公司正洽谈将约 80 亿美元 Grace Blackwell 芯片装入特殊目的载体，再回租给亚马逊，并以债务与少量股权融资。内部文件显示英伟达 GB300 机架大量涌入——单月即约 50 亿美元——因内华达与弗吉尼亚等地电力与基础设施不足而积压。有人质疑其在约 2200 亿美元资本开支背景下的算力过剩，也有人视之为「用而不必全资持有」的融资安排。", "body_en": "Amazon Explores Offloading $8 Billion in Nvidia Chips to Investors.\n\nAmazon has thousands of cutting-edge Nvidia chips ready for its U.S. data centers, but power shortages mean many sit unused in warehouses.\n\nThe company is in talks to shift about $8 billion worth of Grace Blackwell chips into a special-purpose vehicle, which would lease them back to Amazon and raise funds through debt and a small equity stake.\n\nThis comes as internal documents reveal a massive influx of Nvidia GB300 racks—$5 billion in one month alone—piling up due to insufficient power and infrastructure in data centers across Nevada and Virginia. Observers note the timing raises questions about Amazon's AI hardware glut amid its $220 billion capital spending push, though some see the move as smart financing to keep using the chips without owning them outright.", "body_zh": "亚马逊探讨向投资者转移约 80 亿美元英伟达芯片。\n\n大量先进英伟达芯片已备好进美国数据中心，却因电力不足堆在仓库。\n\n公司正洽谈将约 80 亿美元 Grace Blackwell 芯片装入特殊目的载体，再回租给亚马逊，并以债务与少量股权融资。内部文件显示英伟达 GB300 机架大量涌入——单月即约 50 亿美元——因内华达与弗吉尼亚等地电力与基础设施不足而积压。\n\n有人质疑其在约 2200 亿美元资本开支背景下的算力过剩，也有人视之为「用而不必全资持有」的融资安排。", "url": "https://x.com/i/trending/2112540739628630161", "category": "News", "topics": ["Business & Finance", "Stocks", "Technology", "AI"], "updated_at": "2026-10-20T13:52:24.000Z"}, {"id": "2112188369618784335", "domain": "科技", "title_en": "DHS Orders Federal Agencies to Remove DeepSeek AI Products", "title_zh": "美国土安全部要求民事机构清除 DeepSeek 产品", "hook_en": "The U.S. Department of Homeland Security just drew a firm line on Chinese AI tools in government systems, citing risks of data flowing to China and hidden security threats.", "hook_zh": "联邦民事机构接到明确指令：因涉华安全风险，须从系统中移除相关中国 AI 工具。", "summary_en": "Under a new Federal Register notice dated October 20, 2026, DHS directed civilian federal agencies to halt procurement from Hangzhou DeepSeek Artificial Intelligence Co. and remove all its products, including those embedded in third-party services. The order highlights dangers like sensitive data transfers mandated by Chinese law, collection of personal information, and potential malware in the models. DeepSeek, known for efficient open-weight AI models that run well on modest hardware, now faces these restrictions amid broader U.S. limits on Chinese tech, though defense and intelligence systems remain separately regulated.", "summary_zh": "美国国土安全部于 10 月 20 日下令，要求联邦民事机构从 IT 系统中移除所有 DeepSeek 产品、关联方及相关第三方服务，并停止后续采购。关切包括公司总部位于中国、数据可能移交中国当局、收集个人信息，以及对美国人实施恶意软件或情报搜集的风险。此举凸显美中 AI 博弈；DeepSeek 最新 V4.1 因在日常硬件上的速度与效率仍受关注。命令仅适用于民事机构，可有例外。", "body_en": "DHS Orders Federal Agencies to Remove DeepSeek AI Products.\n\nFederal agencies now face a clear directive: pull DeepSeek's Chinese AI tools from their systems to guard against data risks heading to China.\n\nThe U.S. Department of Homeland Security issued an order on October 20 requiring civilian federal agencies to remove DeepSeek products from IT systems and halt future purchases under the Federal Acquisition Supply Chain Security Act. The move addresses threats like sensitive data transfers to China, potential intelligence generation on U.S.\n\npersons, and malware risks in the models. This builds on prior limits by some agencies and states, applying broadly to civilian executive branch systems while sparing defense networks. Reactions split, with supporters praising network protection and critics noting the model's open-source nature could spur local alternatives.", "body_zh": "美国土安全部要求民事机构清除 DeepSeek 产品。\n\n联邦民事机构接到明确指令：因涉华安全风险，须从系统中移除相关中国 AI 工具。\n\n美国国土安全部于 10 月 20 日下令，要求联邦民事机构从 IT 系统中移除所有 DeepSeek 产品、关联方及相关第三方服务，并停止后续采购。关切包括公司总部位于中国、数据可能移交中国当局、收集个人信息，以及对美国人实施恶意软件或情报搜集的风险。\n\n此举凸显美中 AI 博弈；DeepSeek 最新 V4.1 因在日常硬件上的速度与效率仍受关注。命令仅适用于民事机构，可有例外。", "url": "https://x.com/i/trending/2112188369618784335", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T11:44:28.000Z"}, {"id": "2112741574346162483", "domain": "科技", "title_en": "Nvidia in Talks for Hundreds of Millions Investment in Firmus After Scrapped IPO", "title_zh": "Nvidia 洽谈向 Firmus 注资数亿美元，Firmus 已搁置 IPO", "hook_en": "Firmus had its sights set on a massive IPO, but pulled back amid market jitters. Now Nvidia, already a partner, is stepping up with talks of a huge cash infusion.", "hook_zh": "Firmus 本瞄准大型 IPO，却因市场紧张而撤回；已是合作方的 Nvidia，正讨论大规模注资。", "summary_en": "Australian AI cloud provider Firmus abandoned its planned blockbuster IPO on the Australian Securities Exchange earlier this month due to investor concerns over high valuations and its short track record. Nvidia, which already invests in Firmus and partners on a major GPU deployment in Indonesia's Batam campus, is now discussing an equity investment of several hundred million dollars—possibly at least AU$500 million. This move aligns with Nvidia's strategy to back neocloud operators amid surging AI computing demand, as Firmus pivots to private funding up to US$3 billion. No final deal details are confirmed yet.", "summary_zh": "澳大利亚 AI 云服务商 Firmus 本月初因投资者担忧估值过高与业绩记录偏短，放弃在澳大利亚证券交易所的大型 IPO。已投资 Firmus、并在印尼巴淡岛校园合作大规模 GPU 部署的 Nvidia，正讨论数亿美元股权投资，金额可能至少 5 亿澳元。此举契合 Nvidia 在 AI 算力需求飙升背景下支持 neocloud 运营商的策略；Firmus 则转向最高可达约 30 亿美元的私募融资。最终交易细节尚未确认。", "body_en": "Nvidia in Talks for Hundreds of Millions Investment in Firmus After Scrapped IPO.\n\nFirmus had its sights set on a massive IPO, but pulled back amid market jitters. Now Nvidia, already a partner, is stepping up with talks of a huge cash infusion.\n\nAustralian AI cloud provider Firmus abandoned its planned blockbuster IPO on the Australian Securities Exchange earlier this month due to investor concerns over high valuations and its short track record. Nvidia, which already invests in Firmus and partners on a major GPU deployment in Indonesia's Batam campus, is now discussing an equity investment of several hundred million dollars—possibly at least AU$500 million.\n\nThis move aligns with Nvidia's strategy to back neocloud operators amid surging AI computing demand, as Firmus pivots to private funding up to US$3 billion. No final deal details are confirmed yet.", "body_zh": "Nvidia 洽谈向 Firmus 注资数亿美元，Firmus 已搁置 IPO。\n\nFirmus 本瞄准大型 IPO，却因市场紧张而撤回；已是合作方的 Nvidia，正讨论大规模注资。\n\n澳大利亚 AI 云服务商 Firmus 本月初因投资者担忧估值过高与业绩记录偏短，放弃在澳大利亚证券交易所的大型 IPO。已投资 Firmus、并在印尼巴淡岛校园合作大规模 GPU 部署的 Nvidia，正讨论数亿美元股权投资，金额可能至少 5 亿澳元。\n\n此举契合 Nvidia 在 AI 算力需求飙升背景下支持 neocloud 运营商的策略；Firmus 则转向最高可达约 30 亿美元的私募融资。最终交易细节尚未确认。", "url": "https://x.com/i/trending/2112741574346162483", "category": "News", "topics": ["Technology", "AI", "Business & Finance"], "updated_at": "2026-10-21T04:17:50.000Z"}, {"id": "2112496630352281688", "domain": "科技", "title_en": "Microsoft Pulls Out of UK's Largest Planned AI Data Center Over Power Shortage", "title_zh": "电力短缺，微软退出英国最大拟建 AI 数据中心", "hook_en": "Microsoft backed away from a massive AI supercomputer project in Essex after learning grid power won't arrive until the 2030s. The move spotlights Britain's struggle to fuel its AI dreams with reliable electricity.", "hook_zh": "得知电网供电要到 2030 年代才能到位后，微软退出埃塞克斯巨型 AI 超算项目。", "summary_en": "Nscale planned a £2 billion facility in Loughton, the UK's biggest AI data center, with Microsoft as anchor tenant for a setup using 23,000 Nvidia chips and up to 90 megawatts of capacity. UK Power Networks cited decade-long delays, prompting Microsoft to terminate just for this site while keeping ties with Nscale strong. Nscale presses on with alternative power and other locations, amid talk of grid bottlenecks holding back the UK's third-place global AI ranking. Observers debate fixes like faster permits and targeted grid investments to match policy ambition with infrastructure reality.", "summary_zh": "Nscale 原计划在劳顿投资 20 亿英镑建设英国最大 AI 数据中心，微软为锚定租户，拟部署约 2.3 万块英伟达芯片、容量最高约 90 兆瓦。英国电力网络公司称供电延迟可能长达十年，微软因此仅终止该站点合作，与 Nscale 其他合作仍保持。Nscale 正寻求替代电力与其他选址；舆论认为电网瓶颈拖累英国全球 AI 第三的定位，呼吁加快许可与定向电网投资。", "body_en": "Microsoft Pulls Out of UK's Largest Planned AI Data Center Over Power Shortage.\n\nMicrosoft backed away from a massive AI supercomputer project in Essex after learning grid power won't arrive until the 2030s. The move spotlights Britain's struggle to fuel its AI dreams with reliable electricity.\n\nNscale planned a £2 billion facility in Loughton, the UK's biggest AI data center, with Microsoft as anchor tenant for a setup using 23,000 Nvidia chips and up to 90 megawatts of capacity. UK Power Networks cited decade-long delays, prompting Microsoft to terminate just for this site while keeping ties with Nscale strong.\n\nNscale presses on with alternative power and other locations, amid talk of grid bottlenecks holding back the UK's third-place global AI ranking. Observers debate fixes like faster permits and targeted grid investments to match policy ambition with infrastructure reality.", "body_zh": "电力短缺，微软退出英国最大拟建 AI 数据中心。\n\n得知电网供电要到 2030 年代才能到位后，微软退出埃塞克斯巨型 AI 超算项目。\n\nNscale 原计划在劳顿投资 20 亿英镑建设英国最大 AI 数据中心，微软为锚定租户，拟部署约 2.3 万块英伟达芯片、容量最高约 90 兆瓦。英国电力网络公司称供电延迟可能长达十年，微软因此仅终止该站点合作，与 Nscale 其他合作仍保持。\n\nNscale 正寻求替代电力与其他选址；舆论认为电网瓶颈拖累英国全球 AI 第三的定位，呼吁加快许可与定向电网投资。", "url": "https://x.com/i/trending/2112496630352281688", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T10:54:58.000Z"}, {"id": "2112613033243721837", "domain": "科技", "title_en": "OpenAI Acquires Orchestra Bio to Speed Drug Development", "title_zh": "OpenAI 收购 Orchestra Bio，加速药物研发", "hook_en": "OpenAI just brought in a team that's all about wrangling the chaos of drug development, folding their know-how into AI tools that could get treatments to patients faster.", "hook_zh": "创业四周年那天，Ashoka Rajendra 得知 OpenAI 将把团队收入麾下。", "summary_en": "On October 20, 2026, OpenAI announced it acquired Orchestra Bio, a four-year-old startup that helps biopharma teams track studies, timelines, and setbacks like failed manufacturing batches. The deal integrates Orchestra's platform into OpenAI's Rosalind suite, which powers biology and chemistry reasoning for customers including Moderna and Novo Nordisk. Founder Ashoka Rajendra celebrated the milestone on the company's anniversary, excited to scale their mission with OpenAI's AI agents. President Greg Brockman called it a key step in accelerating discoveries into real treatments.", "summary_zh": "OpenAI 收购 Orchestra Bio，将其生物制药协作工具与面向生物、化学的 Rosalind AI 模型结合，推动发现更快转化为疗法。", "body_en": "OpenAI Acquires Orchestra Bio to Speed Drug Development.\n\nImagine AI agents spotting a failed drug batch and instantly suggesting fixes to keep treatments on track for patients.\n\nOpenAI acquired Orchestra Bio, a four-year-old startup founded by Ashoka Rajendra, to integrate its platform with Rosalind AI tools for life sciences. The deal equips biopharma teams with agents that monitor studies, track timelines, flag delays, and coordinate across partners, aiming to turn scientific discoveries into patient treatments faster.\n\nIt builds on OpenAI's work with customers like Moderna and Novo Nordisk, amid a trend of AI labs entering biotech. Investors and leaders like Greg Brockman expressed excitement about accelerating the 10-15 year drug development process.", "body_zh": "OpenAI 收购 Orchestra Bio，加速药物研发。\n\n创业四周年那天，Ashoka Rajendra 得知 OpenAI 将把团队收入麾下。\n\nOpenAI 收购 Orchestra Bio，将其生物制药协作工具与面向生物、化学的 Rosalind AI 模型结合，推动发现更快转化为疗法。\n\n综合以上信息，OpenAI 收购 Orchestra Bio，加速药物研发一事持续引发关注。", "url": "https://x.com/i/trending/2112613033243721837", "category": "News", "topics": ["Technology", "Biotech"], "updated_at": "2026-10-21T12:34:03.000Z"}, {"id": "2112343868393816356", "domain": "科技", "title_en": "Nebius Shines at NVIDIA GTC Berlin with AI Cloud Push", "title_zh": "Nebius 与英伟达加码欧洲 AI 建设者计划，注入千万美元算力", "hook_en": "Jensen Huang called out Nebius from the keynote stage, praising the startup for thriving amid booming AI demand across Europe.", "hook_zh": "欧洲开源 AI 开发者常困于 8GB 显存级算力；如今有望真正把项目做大。", "summary_en": "At NVIDIA GTC Berlin, Nebius CEO Arkady Volozh highlighted strong GPU pricing and demand, while unveiling live spot pricing, reserve auctions, and pay-as-you-go options for preemptible capacity. The company aims for $8 billion in annual recurring revenue by year-end, backed by operations in Finland, France, the UK, Spain, Estonia, and Iceland, with a 5 GW power pipeline. Nebius also expanded its AI Builder Program with $10 million in support, including compute grants and VC connections, to help European developers scale open AI projects.", "summary_zh": "Nebius 与英伟达在欧洲推广 AI Builder Program，提供约 1000 万美元算力资助、投资人对接与社群活动，帮助开源开发者从实验走向融资公司。面向开源模型、编程智能体、后训练与评测，入选者可使用 Nebius 基础设施，并连接 Accel 等风投及 AI Tinkerers 等黑客松。建设者称其直击算力与资金两大瓶颈，有人形容「对已经在写代码的人来说是改变游戏规则」。扩展计划本周在柏林 GTC 启动，意在留住欧洲研究人才。", "body_en": "Nebius and NVIDIA Expand AI Builder Program Across Europe with $10 Million Boost.\n\nEuropean AI builders, often scraping by with limited compute like 8 GB VRAM, now get a real shot at scaling their open-source projects.\n\nNebius and NVIDIA are rolling out their AI Builder Program across Europe with $10 million in compute grants, investor links, and community events to help open AI developers grow from experiments to funded companies. Targeting open models, coding agents, post-training, and evaluations, selected builders gain access to Nebius infrastructure, connections to VCs like Accel, and hackathons with groups such as AI Tinkerers.\n\nBuilders praise it for tackling key hurdles—compute shortages and funding gaps—with one calling it a game changer that rewards those already shipping code. The expansion launches this week at NVIDIA GTC Berlin, building on a global program to keep Europe's strong AI research talent at home.", "body_zh": "Nebius 与英伟达加码欧洲 AI 建设者计划，注入千万美元算力。\n\n欧洲开源 AI 开发者常困于 8GB 显存级算力；如今有望真正把项目做大。\n\nNebius 与英伟达在欧洲推广 AI Builder Program，提供约 1000 万美元算力资助、投资人对接与社群活动，帮助开源开发者从实验走向融资公司。面向开源模型、编程智能体、后训练与评测，入选者可使用 Nebius 基础设施，并连接 Accel 等风投及 AI Tinkerers 等黑客松。\n\n建设者称其直击算力与资金两大瓶颈，有人形容「对已经在写代码的人来说是改变游戏规则」。扩展计划本周在柏林 GTC 启动，意在留住欧洲研究人才。", "url": "https://x.com/i/trending/2112343868393816356", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T12:18:26.000Z"}, {"id": "2112176711844458620", "domain": "科技", "title_en": "Anthropic Commits Shares to Public Benefit Fund", "title_zh": "Anthropic 设立公益基金，承诺拨出股份服务公共目的", "hook_en": "Anthropic's pledge to dedicate 5% of its shares to public good initiatives feels like a direct response to AI's promise of abundance for everyone.", "hook_zh": "Anthropic 宣布把约 5% 股份用于公益，回应“AI 带来普遍丰裕”的期待。", "summary_en": "The AI company behind Claude models announced a Public Benefit Fund starting with 5% of shares, pending stockholder approval, which could grow by up to 2% for every 50% valuation increase above a baseline. Combined with prior pledges, this totals about 20% of shares for purposes like nonprofit donations, aid to affected groups, or addressing AI's job impacts—building on a $200 million labor study commitment, with no funds for lobbying. Elon Musk replied that this is what he will do, later specifying 'universal high income,' fueling talk of AI-driven prosperity shared widely, though some see it as flexible public benefit rather than formal income programs.", "summary_zh": "这家推出 Claude 的公司宣布设立“公益基金”，起步拨出 5% 股份（须经股东批准），估值每高出基准 50% 还可再增拨最多 2%。加上此前承诺，约合 20% 股份可用于非营利捐赠、援助受影响群体或应对就业冲击等，并延续其 2 亿美元劳工研究投入，且不用于游说。埃隆·马斯克回应称自己也会这么做，并提到“普遍高收入”，引发关于如何分享 AI 红利的讨论。", "body_en": "Anthropic Commits Shares to Public Benefit Fund.\n\nAnthropic's pledge to dedicate 5% of its shares to public good initiatives feels like a direct response to AI's promise of abundance for everyone.\n\nThe AI company behind Claude models announced a Public Benefit Fund starting with 5% of shares, pending stockholder approval, which could grow by up to 2% for every 50% valuation increase above a baseline.\n\nCombined with prior pledges, this totals about 20% of shares for purposes like nonprofit donations, aid to affected groups, or addressing AI's job impacts—building on a $200 million labor study commitment, with no funds for lobbying. Elon Musk replied that this is what he will do, later specifying 'universal high income,' fueling talk of AI-driven prosperity shared widely, though some see it as flexible public benefit rather than formal income programs.", "body_zh": "Anthropic 设立公益基金，承诺拨出股份服务公共目的。\n\nAnthropic 宣布把约 5% 股份用于公益，回应“AI 带来普遍丰裕”的期待。\n\n这家推出 Claude 的公司宣布设立“公益基金”，起步拨出 5% 股份（须经股东批准），估值每高出基准 50% 还可再增拨最多 2%。\n\n加上此前承诺，约合 20% 股份可用于非营利捐赠、援助受影响群体或应对就业冲击等，并延续其 2 亿美元劳工研究投入，且不用于游说。埃隆·马斯克回应称自己也会这么做，并提到“普遍高收入”，引发关于如何分享 AI 红利的讨论。", "url": "https://x.com/i/trending/2112176711844458620", "category": "News", "topics": ["Business & Finance", "Technology"], "updated_at": "2026-10-20T21:34:55.000Z"}, {"id": "2112891431543275870", "domain": "科技", "title_en": "NVIDIA's DSX POD Speeds AI Factories to 14 Days", "title_zh": "英伟达 DSX POD：两周内搭起 AI 工厂", "hook_en": "Imagine spinning up a massive AI factory in just two weeks instead of months. NVIDIA's new design makes that real, easing the rush for builders racing to capture billions in revenue.", "hook_zh": "过去数月才能建起的巨型 AI 工厂，英伟达新设计宣称最快约 14 天就能交付。", "summary_en": "At its GTC conference in Berlin, NVIDIA unveiled the DSX POD, a modular system that packages Vera Rubin AI factories into shippable containers built and tested by partners like Dell, HPE, and Lenovo. These units cut deployment time to as little as 14 days once power, cooling, and networking are ready, addressing delays that cost billions in lost revenue for 1-gigawatt facilities. The design also boosts efficiency with closed-loop liquid cooling that slashes water use by up to 100 percent and power needs by 30 percent, helping operators generate output while permanent data centers are built. Partners will deliver the PODs worldwide starting early 2027.", "summary_zh": "在柏林 GTC 上，英伟达发布 DSX POD：把 Vera Rubin AI 工厂做成可由戴尔、HPE、联想等伙伴预装测试的集装箱式模块。在电力、冷却与网络就绪后，部署可压缩到约 14 天，以缓解吉瓦级机房因延期损失的收入。设计还采用闭环液冷，据称可大幅减少用水并降低约 30% 功耗。伙伴计划自 2027 年初起全球交付。", "body_en": "NVIDIA's DSX POD Speeds AI Factories to 14 Days.\n\nImagine spinning up a massive AI factory in just two weeks instead of months. NVIDIA's new design makes that real, easing the rush for builders racing to capture billions in revenue.\n\nAt its GTC conference in Berlin, NVIDIA unveiled the DSX POD, a modular system that packages Vera Rubin AI factories into shippable containers built and tested by partners like Dell, HPE, and Lenovo. These units cut deployment time to as little as 14 days once power, cooling, and networking are ready, addressing delays that cost billions in lost revenue for 1-gigawatt facilities.\n\nThe design also boosts efficiency with closed-loop liquid cooling that slashes water use by up to 100 percent and power needs by 30 percent, helping operators generate output while permanent data centers are built. Partners will deliver the PODs worldwide starting early 2027.", "body_zh": "英伟达 DSX POD：两周内搭起 AI 工厂。\n\n过去数月才能建起的巨型 AI 工厂，英伟达新设计宣称最快约 14 天就能交付。\n\n在柏林 GTC 上，英伟达发布 DSX POD：把 Vera Rubin AI 工厂做成可由戴尔、HPE、联想等伙伴预装测试的集装箱式模块。在电力、冷却与网络就绪后，部署可压缩到约 14 天，以缓解吉瓦级机房因延期损失的收入。\n\n设计还采用闭环液冷，据称可大幅减少用水并降低约 30% 功耗。伙伴计划自 2027 年初起全球交付。", "url": "https://x.com/i/trending/2112891431543275870", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-21T13:03:56.000Z"}, {"id": "2112630070984802593", "domain": "科技", "title_en": "OpenAI Launches Locked Chats for Private ChatGPT Conversations", "title_zh": "OpenAI 推出「锁定对话」，保护私密 ChatGPT 聊天", "hook_en": "Ever had a ChatGPT chat too personal to leave in plain view? OpenAI's new Locked Chats let you tuck it away, protected by a PIN or your fingerprint.", "hook_zh": "把屏幕递给别人前，想先藏起敏感对话？锁定对话用 PIN 或生物识别就能搞定。", "summary_en": "The feature hides selected chats from history, pins, and searches, making them accessible only through a four-digit PIN on all platforms or biometrics on supported phones. It rolled out starting October 20 across Free, Plus, Pro, Business, Enterprise, and Edu plans on web, desktop, and mobile. Locked chats keep new messages in a separate memory section without affecting regular ones, though they lack end-to-end encryption and can't be recovered if the PIN is reset. This adds device-level privacy amid discussions on ChatGPT's memory system, where a study found most entries include psychological insights or personal data created automatically.", "summary_zh": "用户可将聊天移入受保护区域，从历史、置顶与搜索中隐藏，需四位 PIN（全平台）或手机生物识别才能打开。功能自 10 月 20 日起覆盖免费到企业、教育等各档套餐的网页、桌面与移动端。锁定对话的新消息进入独立记忆分区，不影响普通聊天；但不提供端到端加密，重置 PIN 后也无法恢复。此举回应了围绕 ChatGPT 记忆与隐私的讨论。", "body_en": "OpenAI Launches Locked Chats for Private ChatGPT Conversations.\n\nEver had a ChatGPT chat too personal to leave in plain view? OpenAI's new Locked Chats let you tuck it away, protected by a PIN or your fingerprint.\n\nThe feature hides selected chats from history, pins, and searches, making them accessible only through a four-digit PIN on all platforms or biometrics on supported phones. It rolled out starting October 20 across Free, Plus, Pro, Business, Enterprise, and Edu plans on web, desktop, and mobile.\n\nLocked chats keep new messages in a separate memory section without affecting regular ones, though they lack end-to-end encryption and can't be recovered if the PIN is reset. This adds device-level privacy amid discussions on ChatGPT's memory system, where a study found most entries include psychological insights or personal data created automatically.", "body_zh": "OpenAI 推出「锁定对话」，保护私密 ChatGPT 聊天。\n\n把屏幕递给别人前，想先藏起敏感对话？锁定对话用 PIN 或生物识别就能搞定。\n\n用户可将聊天移入受保护区域，从历史、置顶与搜索中隐藏，需四位 PIN（全平台）或手机生物识别才能打开。功能自 10 月 20 日起覆盖免费到企业、教育等各档套餐的网页、桌面与移动端。\n\n锁定对话的新消息进入独立记忆分区，不影响普通聊天；但不提供端到端加密，重置 PIN 后也无法恢复。此举回应了围绕 ChatGPT 记忆与隐私的讨论。", "url": "https://x.com/i/trending/2112630070984802593", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-21T08:41:04.000Z"}, {"id": "2112275132202820043", "domain": "科技", "title_en": "Report Outlines Steps to Double US AI Lead Over China by 2027", "title_zh": "报告：联邦举措或可将美对华前沿 AI 领先扩大到约一倍", "hook_en": "The US currently holds a 6.5-month edge in frontier AI over China. A new report shows how federal actions could nearly double that lead without new laws.", "hook_zh": "美国目前在前沿 AI 上对华约有 6.5 个月优势；新报告称无需新法即可接近翻倍。", "summary_en": "Authors Tim Fist, Georgia Adamson, and Konstantin Pilz analyzed AI compute flows and found China's progress relies heavily on US chips and techniques like adversarial distillation, which halves the US's natural 13-month advantage from superior training compute. They recommend immediate steps, such as blocking remote Chinese access to US AI clusters and allowing companies to coordinate against distillation, potentially extending the lead to 13 months by late 2027. These measures would strengthen US cyber defenses and give firms more time for safety work, with an interactive tool letting users test scenarios.", "summary_zh": "Tim Fist、Georgia Adamson 与 Konstantin Pilz 分析算力流动后认为，中国进展大量依赖美国芯片与对抗蒸馏等手段，后者把美方因训练算力优势本可维持的约 13 个月领先砍半。他们建议立即切断中方对美国 AI 集群的远程访问，并允许企业协调反蒸馏，有望在 2027 年底把领先拉长到约 13 个月，同时加强网络防御、给安全工作留出时间。报告附交互工具供推演情景。", "body_en": "Report Outlines Steps to Double US AI Lead Over China by 2027.\n\nThe US currently holds a 6.5-month edge in frontier AI over China. A new report shows how federal actions could nearly double that lead without new laws.\n\nAuthors Tim Fist, Georgia Adamson, and Konstantin Pilz analyzed AI compute flows and found China's progress relies heavily on US chips and techniques like adversarial distillation, which halves the US's natural 13-month advantage from superior training compute.\n\nThey recommend immediate steps, such as blocking remote Chinese access to US AI clusters and allowing companies to coordinate against distillation, potentially extending the lead to 13 months by late 2027. These measures would strengthen US cyber defenses and give firms more time for safety work, with an interactive tool letting users test scenarios.", "body_zh": "报告：联邦举措或可将美对华前沿 AI 领先扩大到约一倍。\n\n美国目前在前沿 AI 上对华约有 6.5 个月优势；新报告称无需新法即可接近翻倍。\n\nTim Fist、Georgia Adamson 与 Konstantin Pilz 分析算力流动后认为，中国进展大量依赖美国芯片与对抗蒸馏等手段，后者把美方因训练算力优势本可维持的约 13 个月领先砍半。\n\n他们建议立即切断中方对美国 AI 集群的远程访问，并允许企业协调反蒸馏，有望在 2027 年底把领先拉长到约 13 个月，同时加强网络防御、给安全工作留出时间。报告附交互工具供推演情景。", "url": "https://x.com/i/trending/2112275132202820043", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-19T23:11:30.000Z"}, {"id": "2112525486228156479", "domain": "科技", "title_en": "DeepSeek V4.1 Flash Outperforms OpenAI's GPT-6 Sol on Cybersecurity Benchmarks", "title_zh": "DeepSeek V4.1 Flash 在网络安全基准上胜过受限版 GPT-6 Sol", "hook_en": "In simulated corporate networks, DeepSeek V4.1 Flash 1017 completed more multi-step offensive cybersecurity objectives than a restricted version of OpenAI’s GPT-6 Sol. This open-weight model from China delivered results at lower cost, even using more tokens.", "hook_zh": "在模拟企业网络中，DeepSeek V4.1 Flash 完成的多步进攻目标多于受限版 OpenAI GPT-6 Sol，且成本更低。", "summary_en": "Vals AI's benchmarks show DeepSeek V4.1 Flash 1017, released around October 17, excelling in agentic tasks with a 1-million-token context window and open MIT-licensed weights on Hugging Face. It achieved strong scores like 42.7 objectives in its own harness and runs locally on hardware like two NVIDIA DGX Spark systems, with developers calling the speed a potential national security risk. MiniMax M3.1 Flash competes closely, offering lower costs on coding and visual tasks, as reactions blend excitement over affordable frontier performance with caution about dual-use cyber capabilities now openly available.", "summary_zh": "Vals AI 基准显示，约 10 月 17 日发布的 DeepSeek V4.1 Flash 1017 在智能体任务上表现突出，拥有百万 token 上下文，并以 MIT 许可在 Hugging Face 开源权重。其在自有评测中取得约 42.7 个目标等成绩，可在两台英伟达 DGX Spark 等设备本地运行。开发者称速度惊人，也有人担心双用途网络能力公开可得。MiniMax M3.1 Flash 在编程与视觉任务上成本更低，竞争同样激烈。", "body_en": "DeepSeek V4.1 Flash Outperforms OpenAI's GPT-6 Sol on Cybersecurity Benchmarks.\n\nIn simulated corporate networks, DeepSeek V4.1 Flash 1017 completed more multi-step offensive cybersecurity objectives than a restricted version of OpenAI’s GPT-6 Sol. This open-weight model from China delivered results at lower cost, even using more tokens.\n\nVals AI's benchmarks show DeepSeek V4.1 Flash 1017, released around October 17, excelling in agentic tasks with a 1-million-token context window and open MIT-licensed weights on Hugging Face.\n\nIt achieved strong scores like 42.7 objectives in its own harness and runs locally on hardware like two NVIDIA DGX Spark systems, with developers calling the speed a potential national security risk. MiniMax M3.1 Flash competes closely, offering lower costs on coding and visual tasks, as reactions blend excitement over affordable frontier performance with caution about dual-use cyber capabilities now openly available.", "body_zh": "DeepSeek V4.1 Flash 在网络安全基准上胜过受限版 GPT-6 Sol。\n\n在模拟企业网络中，DeepSeek V4.1 Flash 完成的多步进攻目标多于受限版 OpenAI GPT-6 Sol，且成本更低。\n\nVals AI 基准显示，约 10 月 17 日发布的 DeepSeek V4.1 Flash 1017 在智能体任务上表现突出，拥有百万 token 上下文，并以 MIT 许可在 Hugging Face 开源权重。其在自有评测中取得约 42.7 个目标等成绩，可在两台英伟达 DGX Spark 等设备本地运行。\n\n开发者称速度惊人，也有人担心双用途网络能力公开可得。MiniMax M3.1 Flash 在编程与视觉任务上成本更低，竞争同样激烈。", "url": "https://x.com/i/trending/2112525486228156479", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T17:46:45.000Z"}, {"id": "2112796521959985524", "domain": "商业", "title_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals", "title_zh": "美国资本市场连创纪录：巨额IPO与债券齐发", "hook_en": "From SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.", "hook_zh": "从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。", "summary_en": "The Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile. SoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "summary_zh": "《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "body_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals.\n\nFrom SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.\n\nThe Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile.\n\nSoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "body_zh": "美国资本市场连创纪录：巨额IPO与债券齐发。\n\n从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。\n\n《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。\n\n观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "url": "https://x.com/i/trending/2112796521959985524", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T06:46:48.000Z"}, {"id": "2112044241161433358", "domain": "商业", "title_en": "Asia Markets Plunge on AI Spending Worries and Oil Pressures", "title_zh": "亚洲股市因 AI 开支忧虑与油价承压深跌", "hook_en": "Japanese and South Korean stocks have shed hundreds of billions in value over two tense weeks. Investors are pulling back from AI bets amid rising oil prices and global jitters.", "hook_zh": "日韩股市两周蒸发数千亿美元市值。投资者在油价上涨与全球动荡中撤出 AI 押注。", "summary_en": "Japan's Nikkei dropped nearly 10% in recent sessions, wiping out over ¥100 trillion, or about $700 billion, from equities. South Korea's KOSPI fell around 3.5% to 4% on Tuesday, part of a 22% two-week slide that erased ₩1,118 trillion, or $745 billion, with Samsung Electronics and SK Hynix hit hard as key AI chip suppliers. A South Korean AI cloud firm, Elice Inc., saw its shares plunge 30% on its IPO debut despite heavy retail interest, fueled by U.S. tech sell-offs, Middle East oil tensions, and doubts over AI investment returns. Markets now eye earnings reports and oil shifts for signs of recovery.", "summary_zh": "日经近几日累计下跌近 10%，市值蒸发逾 100 万亿日元（约 7000 亿美元）。韩国综指周二再跌约 3.5%–4%，两周累计约 22%、蒸发约 1118 万亿韩元（约 7450 亿美元），三星电子与 SK 海力士等 AI 供应链重镇受创。韩国 AI 云公司 Elice 上市首日暴跌约 30%。市场等待财报与油价信号。", "body_en": "Asia Markets Plunge on AI Spending Worries and Oil Pressures.\n\nJapanese and South Korean stocks have shed hundreds of billions in value over two tense weeks. Investors are pulling back from AI bets amid rising oil prices and global jitters.\n\nJapan's Nikkei dropped nearly 10% in recent sessions, wiping out over ¥100 trillion, or about $700 billion, from equities. South Korea's KOSPI fell around 3.5% to 4% on Tuesday, part of a 22% two-week slide that erased ₩1,118 trillion, or $745 billion, with Samsung Electronics and SK Hynix hit hard as key AI chip suppliers.\n\nA South Korean AI cloud firm, Elice Inc., saw its shares plunge 30% on its IPO debut despite heavy retail interest, fueled by U.S. tech sell-offs, Middle East oil tensions, and doubts over AI investment returns. Markets now eye earnings reports and oil shifts for signs of recovery.", "body_zh": "亚洲股市因 AI 开支忧虑与油价承压深跌。\n\n日韩股市两周蒸发数千亿美元市值。投资者在油价上涨与全球动荡中撤出 AI 押注。\n\n日经近几日累计下跌近 10%，市值蒸发逾 100 万亿日元（约 7000 亿美元）。韩国综指周二再跌约 3.5%–4%，两周累计约 22%、蒸发约 1118 万亿韩元（约 7450 亿美元），三星电子与 SK 海力士等 AI 供应链重镇受创。\n\n韩国 AI 云公司 Elice 上市首日暴跌约 30%。市场等待财报与油价信号。", "url": "https://x.com/i/trending/2112044241161433358", "category": "News", "topics": ["Stocks"], "updated_at": "2026-10-20T12:59:35.000Z"}, {"id": "2112369182595788855", "domain": "商业", "title_en": "Jio Platforms Gears Up for India's Largest IPO with ₹30,000 Crore Raise", "title_zh": "Jio Platforms 冲刺印度史上最大 IPO，募资约 3 万亿卢比", "hook_en": "From making mobile data affordable for millions to powering everyday streaming, Jio's decade-long journey has transformed lives across India.", "hook_zh": "从让亿万人用得起移动流量，到撑起日常流媒体，Jio 十年改变了印度数字生活。", "summary_en": "Jio Platforms, Reliance Industries' digital arm, will launch India's biggest IPO on October 21, offering up to 27 crore shares to raise around ₹30,213 crore at the top price of ₹1,119 each. The funds will mostly repay debt at its telecom subsidiary, which serves 533 million customers and handles 60% of India's wireless data traffic. People fondly remember the shift from cautious video watching to seamless scrolling and calls, crediting Jio's growth under Mukesh and Akash Ambani, while analysts watch if its scale can drive better returns through efficiency and new services like cloud and broadband.", "summary_zh": "信实工业数字臂膀 Jio Platforms 定于 10 月 21 日启动印度最大 IPO，最多发行约 27 亿股，顶格价约 1119 卢比/股，募资约 30213 亿卢比。资金主要用于偿还电信子公司债务；该业务服务约 5.33 亿用户，承载印度约 60% 无线数据流量。公众回忆从「省着用视频」到流畅刷屏通话的转变，归功于穆克什与阿卡什·安巴尼治下的扩张；分析师则关注规模能否靠效率与云、宽带等新业务转化为更好回报。", "body_en": "Jio Platforms Gears Up for India's Largest IPO with ₹30,000 Crore Raise.\n\nFrom making mobile data affordable for millions to powering everyday streaming, Jio's decade-long journey has transformed lives across India.\n\nJio Platforms, Reliance Industries' digital arm, will launch India's biggest IPO on October 21, offering up to 27 crore shares to raise around ₹30,213 crore at the top price of ₹1,119 each.\n\nThe funds will mostly repay debt at its telecom subsidiary, which serves 533 million customers and handles 60% of India's wireless data traffic. People fondly remember the shift from cautious video watching to seamless scrolling and calls, crediting Jio's growth under Mukesh and Akash Ambani, while analysts watch if its scale can drive better returns through efficiency and new services like cloud and broadband.", "body_zh": "Jio Platforms 冲刺印度史上最大 IPO，募资约 3 万亿卢比。\n\n从让亿万人用得起移动流量，到撑起日常流媒体，Jio 十年改变了印度数字生活。\n\n信实工业数字臂膀 Jio Platforms 定于 10 月 21 日启动印度最大 IPO，最多发行约 27 亿股，顶格价约 1119 卢比/股，募资约 30213 亿卢比。\n\n资金主要用于偿还电信子公司债务；该业务服务约 5.33 亿用户，承载印度约 60% 无线数据流量。公众回忆从「省着用视频」到流畅刷屏通话的转变，归功于穆克什与阿卡什·安巴尼治下的扩张；分析师则关注规模能否靠效率与云、宽带等新业务转化为更好回报。", "url": "https://x.com/i/trending/2112369182595788855", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T02:29:15.000Z"}, {"id": "2112431560116826201", "domain": "商业", "title_en": "Former Finance Secretary Sparks Debate on India's GDP in Dollar Terms", "title_zh": "前财秘以美元口径 GDP 数据引发印度增长辩论", "hook_en": "Subhash Chandra Garg, ex-Finance Secretary, shared IMF data showing India's GDP growth in current US dollars at just 3.87%—well below the world average and China's rate—prompting a lively back-and-forth online.", "hook_zh": "前财政秘书苏巴什·钱德拉·加尔格分享 IMF 数据称，印度按现价美元计 GDP 增速仅 3.87%，低于全球均值与中国，引发网上热议。", "summary_en": "Garg contrasted this with India's real GDP growth of around 7% in local terms, arguing the dollar measure gives a fuller picture often missed in domestic talks. Critics say focusing on dollars mixes in currency fluctuations and overlooks actual output, while supporters like Sanjay Jha tie it to investor outflows exceeding Rs 3 lakh crore from Indian stocks in 2026 and job concerns. The IMF's October 2026 outlook projects India's real growth at 7%, but nominal dollar GDP lags partly due to rupee depreciation, highlighting tensions between real output metrics and global investor views.", "summary_zh": "加尔格将其与印度本币实际 GDP 约 7% 的增速对照，认为美元口径更能呈现国内讨论常忽略的全貌。批评者称盯住美元会混入汇率波动、忽视实际产出；支持者如 Sanjay Jha 则将其与 2026 年印度股市外资流出逾 3 万亿卢比及就业担忧挂钩。IMF 2026 年 10 月展望仍预计印度实际增速 7%，但名义美元 GDP 因卢比贬值等因素滞后，凸显产出指标与全球投资者视角之间的张力。", "body_en": "Former Finance Secretary Sparks Debate on India's GDP in Dollar Terms.\n\nSubhash Chandra Garg, ex-Finance Secretary, shared IMF data showing India's GDP growth in current US dollars at just 3.87%—well below the world average and China's rate—prompting a lively back-and-forth online.\n\nGarg contrasted this with India's real GDP growth of around 7% in local terms, arguing the dollar measure gives a fuller picture often missed in domestic talks.\n\nCritics say focusing on dollars mixes in currency fluctuations and overlooks actual output, while supporters like Sanjay Jha tie it to investor outflows exceeding Rs 3 lakh crore from Indian stocks in 2026 and job concerns. The IMF's October 2026 outlook projects India's real growth at 7%, but nominal dollar GDP lags partly due to rupee depreciation, highlighting tensions between real output metrics and global investor views.", "body_zh": "前财秘以美元口径 GDP 数据引发印度增长辩论。\n\n前财政秘书苏巴什·钱德拉·加尔格分享 IMF 数据称，印度按现价美元计 GDP 增速仅 3.87%，低于全球均值与中国，引发网上热议。\n\n加尔格将其与印度本币实际 GDP 约 7% 的增速对照，认为美元口径更能呈现国内讨论常忽略的全貌。批评者称盯住美元会混入汇率波动、忽视实际产出；支持者如 Sanjay Jha 则将其与 2026 年印度股市外资流出逾 3 万亿卢比及就业担忧挂钩。\n\nIMF 2026 年 10 月展望仍预计印度实际增速 7%，但名义美元 GDP 因卢比贬值等因素滞后，凸显产出指标与全球投资者视角之间的张力。", "url": "https://x.com/i/trending/2112431560116826201", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T06:36:16.000Z"}, {"id": "2112771431633502285", "domain": "商业", "title_en": "Nifty Gaps Up Then Faces Selling Pressure on October 21", "title_zh": "节后高开后 Nifty 遭遇抛压", "hook_en": "Nifty started the day with a promising gap-up above 23,000, fueled by IT gains and IPO buzz, but sellers quickly stepped in as charts signaled risks.", "hook_zh": "排灯节后 Nifty 曾乐观跳空高开，但卖方迅速入场，指数在震荡中回落。", "summary_en": "After Monday's 1.11% drop to 22,888.95, the index opened higher on positive GIFT Nifty signals, Jio Platforms IPO excitement, and India-US trade hopes, yet Elliott Wave analysis warned of a downside zone between 23,060-23,175 targeting 22,560-22,478. Analysts like Ashish H Kyal highlighted key levels, with a break above 22,970 eyeing 23,050-23,120 or below 22,830 pressuring 22,728, and morning targets hit before a sharp reversal. Broader factors included global cues and high Brent crude at $110, underscoring the market's focus on precise supports around 22,700-22,800 amid volatility.", "summary_zh": "指数周一收于 22888.95，跌 1.11%；随后开于约 23016，最高 23120.90，再回落至 22700–22800 一带。技术派如 SweeGlu 艾略特波浪使用者在 23060–23175 区间看到抛售，下行关注 22560–22478；Ashish H Kyal 指出关键区间波动，Mahesh Khandelwal 则预期自 22500 一带反转冲向 24000 上方。布伦特原油约每桶 110 美元加重通胀担忧；Jio Platforms IPO 与二季报推动部分 IT 买盘，但整体仍偏获利了结。", "body_en": "Nifty Gaps Up Then Faces Selling Pressure on October 21.\n\nNifty started the day with a promising gap-up above 23,000, fueled by IT gains and IPO buzz, but sellers quickly stepped in as charts signaled risks.\n\nAfter Monday's 1.11% drop to 22,888.95, the index opened higher on positive GIFT Nifty signals, Jio Platforms IPO excitement, and India-US trade hopes, yet Elliott Wave analysis warned of a downside zone between 23,060-23,175 targeting 22,560-22,478.\n\nAnalysts like Ashish H Kyal highlighted key levels, with a break above 22,970 eyeing 23,050-23,120 or below 22,830 pressuring 22,728, and morning targets hit before a sharp reversal. Broader factors included global cues and high Brent crude at $110, underscoring the market's focus on precise supports around 22,700-22,800 amid volatility.", "body_zh": "节后高开后 Nifty 遭遇抛压。\n\n排灯节后 Nifty 曾乐观跳空高开，但卖方迅速入场，指数在震荡中回落。\n\n指数周一收于 22888.95，跌 1.11%；随后开于约 23016，最高 23120.90，再回落至 22700–22800 一带。技术派如 SweeGlu 艾略特波浪使用者在 23060–23175 区间看到抛售，下行关注 22560–22478；Ashish H Kyal 指出关键区间波动，Mahesh Khandelwal 则预期自 22500 一带反转冲向 24000 上方。\n\n布伦特原油约每桶 110 美元加重通胀担忧；Jio Platforms IPO 与二季报推动部分 IT 买盘，但整体仍偏获利了结。", "url": "https://x.com/i/trending/2112771431633502285", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T08:16:34.000Z"}, {"id": "2112266057628913774", "domain": "商业", "title_en": "Hedge Funds Dump Tech Stocks at Fastest Pace in Decade", "title_zh": "对冲基金十年最快速度抛售科技股", "hook_en": "Hedge funds hit the sell button on tech stocks harder than they have in at least a decade, unloading positions amid sharp market drops.", "hook_zh": "对冲基金对科技股的抛售力度至少创下十年来最快，正值市场大跌。", "summary_en": "Through October 15, hedge funds cut technology exposure at the quickest rate since at least 2016, reversing all net buying of AI stocks since early 2025 in just one week. Semiconductors bore the brunt, making up 57% of U.S. tech sales, as the Nasdaq 100 fell 5.5%—its worst week since April 2025—and the SOX index hit its lowest ratio to the S&P 500 since April. Investors also rushed into credit default swaps on AI-linked firms like Nvidia and Meta, with spreads hitting records and trading volumes surging, while funds shifted toward U.S. Treasurys amid a negative risk-appetite signal.", "summary_zh": "截至 10 月 15 日，对冲基金削减科技敞口的速度为至少 2016 年以来最快，一周内就逆转了自 2025 年初以来对 AI 股的净买入。半导体占美国科技卖出的 57%；纳斯达克 100 当周跌 5.5%，为 2025 年 4 月以来最差。投资者还大量买入英伟达、Meta 等 AI 相关信用违约互换，利差与成交量创新高，同时资金转向美债。", "body_en": "Hedge Funds Dump Tech Stocks at Fastest Pace in Decade.\n\nHedge funds hit the sell button on tech stocks harder than they have in at least a decade, unloading positions amid sharp market drops.\n\nThrough October 15, hedge funds cut technology exposure at the quickest rate since at least 2016, reversing all net buying of AI stocks since early 2025 in just one week. Semiconductors bore the brunt, making up 57% of U.S.\n\ntech sales, as the Nasdaq 100 fell 5.5%—its worst week since April 2025—and the SOX index hit its lowest ratio to the S&P 500 since April. Investors also rushed into credit default swaps on AI-linked firms like Nvidia and Meta, with spreads hitting records and trading volumes surging, while funds shifted toward U.S. Treasurys amid a negative risk-appetite signal.", "body_zh": "对冲基金十年最快速度抛售科技股。\n\n对冲基金对科技股的抛售力度至少创下十年来最快，正值市场大跌。\n\n截至 10 月 15 日，对冲基金削减科技敞口的速度为至少 2016 年以来最快，一周内就逆转了自 2025 年初以来对 AI 股的净买入。半导体占美国科技卖出的 57%；纳斯达克 100 当周跌 5.5%，为 2025 年 4 月以来最差。\n\n投资者还大量买入英伟达、Meta 等 AI 相关信用违约互换，利差与成交量创新高，同时资金转向美债。", "url": "https://x.com/i/trending/2112266057628913774", "category": "News", "topics": ["Business & Finance", "Technology"], "updated_at": "2026-10-20T21:07:55.000Z"}, {"id": "2112795003680342391", "domain": "商业", "title_en": "S&P 500's Top 15 Stocks Hit Record 46.7% Share", "title_zh": "标普 500 前 15 大股权重创纪录达 46.7%", "hook_en": "A handful of tech giants now steer the entire S&P 500, with Nvidia alone claiming 7.5% of the index's value. Everyday investors in broad funds might not realize how much they're riding on these leaders.", "hook_zh": "少数科技巨头主导整个标普 500，仅英伟达就占指数市值约 7.5%。买宽基基金的普通投资者未必意识到自己有多依赖这些龙头。", "summary_en": "The 15 largest S&P 500 stocks account for a record 46.7% of the index's total market value, far exceeding the 27.2% seen at the 2000 dot-com peak. Nvidia tops the list at 7.5%, followed by Apple at 7.1%, Alphabet at 5.9%, and Microsoft at 5.6%, with these four alone making up 26.1%. The top five equal the market cap of the bottom 434 companies, prompting market watchers to question diversification in popular index funds and ETFs. While some highlight the leaders' strong cash flows, others note that any slowdown could hit passive portfolios hard.", "summary_zh": "标普 500 最大的 15 只股票合计占指数总市值创纪录的 46.7%，远超 2000 年互联网泡沫顶峰时的 27.2%。英伟达以 7.5% 居首，苹果 7.1%、Alphabet 5.9%、微软 5.6%，四家合计 26.1%。前五名市值相当于后 434 家之和，引发对热门指数基金与 ETF「分散」成色的质疑。有人强调龙头现金流强劲，也有人警告一旦放缓，被动组合将承压。", "body_en": "S&P 500's Top 15 Stocks Hit Record 46.7% Share.\n\nA handful of tech giants now steer the entire S&P 500, with Nvidia alone claiming 7.5% of the index's value. Everyday investors in broad funds might not realize how much they're riding on these leaders.\n\nThe 15 largest S&P 500 stocks account for a record 46.7% of the index's total market value, far exceeding the 27.2% seen at the 2000 dot-com peak. Nvidia tops the list at 7.5%, followed by Apple at 7.1%, Alphabet at 5.9%, and Microsoft at 5.6%, with these four alone making up 26.1%.\n\nThe top five equal the market cap of the bottom 434 companies, prompting market watchers to question diversification in popular index funds and ETFs. While some highlight the leaders' strong cash flows, others note that any slowdown could hit passive portfolios hard.", "body_zh": "标普 500 前 15 大股权重创纪录达 46.7%。\n\n少数科技巨头主导整个标普 500，仅英伟达就占指数市值约 7.5%。买宽基基金的普通投资者未必意识到自己有多依赖这些龙头。\n\n标普 500 最大的 15 只股票合计占指数总市值创纪录的 46.7%，远超 2000 年互联网泡沫顶峰时的 27.2%。英伟达以 7.5% 居首，苹果 7.1%、Alphabet 5.9%、微软 5.6%，四家合计 26.1%。\n\n前五名市值相当于后 434 家之和，引发对热门指数基金与 ETF「分散」成色的质疑。有人强调龙头现金流强劲，也有人警告一旦放缓，被动组合将承压。", "url": "https://x.com/i/trending/2112795003680342391", "category": "News", "topics": ["Stocks"], "updated_at": "2026-10-21T06:39:54.000Z"}, {"id": "2112795002845704467", "domain": "商业", "title_en": "UK Government Invests Sh1.94 Billion in QuickMart IPO for 6.5% Stake", "title_zh": "英国政府拟投约 19.4 亿先令认购 QuickMart IPO 约 6.5% 股份", "hook_en": "QuickMart, Kenya's second-largest supermarket chain, just launched a massive Sh15 billion IPO on the Nairobi Securities Exchange. The UK government stepped in big with a Sh1.94 billion commitment through its MOBILIST program.", "hook_zh": "肯尼亚第二大连锁超市 QuickMart 在内罗毕证交所启动约 150 亿先令 IPO，英国政府参与认购。", "summary_en": "QuickMart is offering 2 billion shares at Sh7.50 each, valuing the company at Sh30 billion and representing 50% of the retailer. The IPO opened earlier this month and closes on October 30, 2026, with trading set to start November 12; proceeds will go to existing shareholders. CEO Peter Kang’iri highlighted the goals of broadening ownership, creating jobs, and expanding affordable shopping access across its 72 stores in 16 counties. Retail investors can join with a minimum of 500 shares for Sh3,750 via stockbrokers, M-PESA, or USSD, while the International Finance Corporation eyes a similar Sh1.94 billion commitment.", "summary_zh": "QuickMart 拟以每股 7.50 先令发行 20 亿股，公司估值约 300 亿先令，约占股本 50%。IPO 本月开售、10 月 30 日截止，预计 11 月 12 日上市，所得归现有股东。英国方面投资约 19.4 亿先令，对应约 6.5% 股权。管理层称募资将支持扩张；市场关注东非零售与外资布局。", "body_en": "UK Government Invests Sh1.94 Billion in QuickMart IPO for 6.5% Stake.\n\nQuickMart, Kenya's second-largest supermarket chain, just launched a massive Sh15 billion IPO on the Nairobi Securities Exchange. The UK government stepped in big with a Sh1.94 billion commitment through its MOBILIST program.\n\nQuickMart is offering 2 billion shares at Sh7.50 each, valuing the company at Sh30 billion and representing 50% of the retailer. The IPO opened earlier this month and closes on October 30, 2026, with trading set to start November 12; proceeds will go to existing shareholders.\n\nCEO Peter Kang’iri highlighted the goals of broadening ownership, creating jobs, and expanding affordable shopping access across its 72 stores in 16 counties. Retail investors can join with a minimum of 500 shares for Sh3,750 via stockbrokers, M-PESA, or USSD, while the International Finance Corporation eyes a similar Sh1.94 billion commitment.", "body_zh": "英国政府拟投约 19.4 亿先令认购 QuickMart IPO 约 6.5% 股份。\n\n肯尼亚第二大连锁超市 QuickMart 在内罗毕证交所启动约 150 亿先令 IPO，英国政府参与认购。\n\nQuickMart 拟以每股 7.50 先令发行 20 亿股，公司估值约 300 亿先令，约占股本 50%。IPO 本月开售、10 月 30 日截止，预计 11 月 12 日上市，所得归现有股东。\n\n英国方面投资约 19.4 亿先令，对应约 6.5% 股权。管理层称募资将支持扩张；市场关注东非零售与外资布局。", "url": "https://x.com/i/trending/2112795002845704467", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T06:40:05.000Z"}, {"id": "2112413052469481717", "domain": "商业", "title_en": "IREN Shares Drop to $26.62 Near 52-Week Low Amid Funding Worries", "title_zh": "IREN 股价跌至约 26.62 美元，逼近年内低点", "hook_en": "IREN's stock closed at $26.62 on October 20 after a 4% plunge on heavy volume, leaving traders split on whether it's primed for a rebound or more pain ahead.", "hook_zh": "10 月 20 日 IREN 收跌约 4% 至 26.62 美元，成交放大，多空对后市分歧明显。", "summary_en": "The company, once a Bitcoin miner now focused on AI cloud data centers, holds over 5 GW of power capacity and NVIDIA infrastructure powered by renewables, but shares have fallen 65% from their November 2025 peak near $77 due to concerns over $25-30 billion in planned 2027 spending and rising borrowing costs. Traders highlight stretched technical patterns that could snap back up, potential support at Fibonacci levels and the 200-week average, yet some warn of drops to $15-18 if those fail. Wall Street targets stay around $77-81, with early November earnings expected to shed light on demand and funding.", "summary_zh": "这家由比特币矿企转向 AI 云数据中心的公司拥有逾 5GW 电力与英伟达算力基础设施，但相对 2025 年 11 月约 77 美元高点已跌约 65%，市场担忧其 2027 年计划开支达 250–300 亿美元及借贷成本上升。交易者看到技术超卖反弹可能，也有人警示若跌破支撑或探向 15–18 美元。华尔街目标价仍多在 77–81 美元一带，11 月初财报或澄清需求与融资。", "body_en": "IREN Shares Drop to $26.62 Near 52-Week Low Amid Funding Worries.\n\nIREN's stock closed at $26.62 on October 20 after a 4% plunge on heavy volume, leaving traders split on whether it's primed for a rebound or more pain ahead.\n\nThe company, once a Bitcoin miner now focused on AI cloud data centers, holds over 5 GW of power capacity and NVIDIA infrastructure powered by renewables, but shares have fallen 65% from their November 2025 peak near $77 due to concerns over $25-30 billion in planned 2027 spending and rising borrowing costs.\n\nTraders highlight stretched technical patterns that could snap back up, potential support at Fibonacci levels and the 200-week average, yet some warn of drops to $15-18 if those fail. Wall Street targets stay around $77-81, with early November earnings expected to shed light on demand and funding.", "body_zh": "IREN 股价跌至约 26.62 美元，逼近年内低点。\n\n10 月 20 日 IREN 收跌约 4% 至 26.62 美元，成交放大，多空对后市分歧明显。\n\n这家由比特币矿企转向 AI 云数据中心的公司拥有逾 5GW 电力与英伟达算力基础设施，但相对 2025 年 11 月约 77 美元高点已跌约 65%，市场担忧其 2027 年计划开支达 250–300 亿美元及借贷成本上升。\n\n交易者看到技术超卖反弹可能，也有人警示若跌破支撑或探向 15–18 美元。华尔街目标价仍多在 77–81 美元一带，11 月初财报或澄清需求与融资。", "url": "https://x.com/i/trending/2112413052469481717", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T00:39:55.000Z"}, {"id": "2112213035615990082", "domain": "商业", "title_en": "NYSE and Cboe Launch Extended Options Trading Hours", "title_zh": "纽交所与 Cboe 延长热门股票期权交易时段", "hook_en": "Imagine adjusting your trades before breakfast or right after dinner. Major exchanges are now making that possible for options on top stocks like Nvidia and Apple.", "hook_zh": "早餐前或晚饭后也能调仓：主要交易所为英伟达、苹果等热门期权开放盘前盘后交易。", "summary_en": "Cboe and the New York Stock Exchange began offering pre-market options trading from 7:30 a.m. to 9:25 a.m. ET and post-market sessions starting October 19, covering high-volume names like Nvidia, Apple, Amazon, and key ETFs such as SPY and IWM. These changes meet growing demand from retail and institutional investors for more flexibility in managing positions outside regular hours, with the included options representing 53% of daily U.S. volume. Traders have mixed views—some appreciate the access, while others worry about risks like lower liquidity; NYSE plans 23-hour trading by December 6.", "summary_zh": "自 10 月 19 日起，Cboe 与纽交所提供美东时间 7:30–9:25 盘前及盘后期权交易，覆盖英伟达、苹果、亚马逊及 SPY、IWM 等成交活跃品种，约占美股期权日成交约 53%。此举回应散户与机构对非常规时段风险管理的需求。有人欢迎更灵活，也有人担心流动性偏弱带来风险；纽交所还计划 12 月 6 日起进一步迈向近 23 小时交易。", "body_en": "NYSE and Cboe Launch Extended Options Trading Hours.\n\nImagine adjusting your trades before breakfast or right after dinner. Major exchanges are now making that possible for options on top stocks like Nvidia and Apple.\n\nCboe and the New York Stock Exchange began offering pre-market options trading from 7:30 a.m. to 9:25 a.m. ET and post-market sessions starting October 19, covering high-volume names like Nvidia, Apple, Amazon, and key ETFs such as SPY and IWM.\n\nThese changes meet growing demand from retail and institutional investors for more flexibility in managing positions outside regular hours, with the included options representing 53% of daily U.S. volume. Traders have mixed views—some appreciate the access, while others worry about risks like lower liquidity; NYSE plans 23-hour trading by December 6.", "body_zh": "纽交所与 Cboe 延长热门股票期权交易时段。\n\n早餐前或晚饭后也能调仓：主要交易所为英伟达、苹果等热门期权开放盘前盘后交易。\n\n自 10 月 19 日起，Cboe 与纽交所提供美东时间 7:30–9:25 盘前及盘后期权交易，覆盖英伟达、苹果、亚马逊及 SPY、IWM 等成交活跃品种，约占美股期权日成交约 53%。\n\n此举回应散户与机构对非常规时段风险管理的需求。有人欢迎更灵活，也有人担心流动性偏弱带来风险；纽交所还计划 12 月 6 日起进一步迈向近 23 小时交易。", "url": "https://x.com/i/trending/2112213035615990082", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-20T05:34:56.000Z"}, {"id": "2112569366479048900", "domain": "商业", "title_en": "Bob McGrew Launches $1.5B AI Startup Arda to Accelerate U.S. Manufacturing", "title_zh": "前 OpenAI 研究负责人推出估值 15 亿美元制造 AI 创业公司 Arda", "hook_en": "Bob McGrew, fresh from leading research at OpenAI, stepped onto CNBC this week to unveil Arda—a startup building AI agents that slash factory setup times from days to minutes.", "hook_zh": "刚离开 OpenAI 研究负责人岗位的 Bob McGrew 登上 CNBC，介绍能把工厂筹备从“天”压到“分钟”的 AI 智能体创业公司 Arda。", "summary_en": "Founded in 2025, Arda raised $160 million in a Series A round co-led by Altimeter Capital, Accel, and Khosla Ventures, pushing total funding to $230 million and valuing the company at $1.5 billion. The platform turns product designs into assembly instructions, already deployed across Anduril's divisions to cut engineering workflows from 30 hours to 2.5 hours or even 10 hours to 15 minutes. Co-founder Augustus Odena envisions AI that designs and runs entire factories, starting with manual lines and advancing to adaptable robotic systems amid pushes to bring production back to the U.S.", "summary_zh": "Arda 成立于 2025 年，本轮 A 轮融资 1.6 亿美元，由 Altimeter、Accel 与 Khosla 等领投，累计融资约 2.3 亿美元，估值约 15 亿美元。平台可将产品设计转为装配指令，已在 Anduril 多部门落地，把部分工程流程从约 30 小时压到 2.5 小时，甚至 10 小时到 15 分钟。联合创始人设想 AI 逐步设计并运行整座工厂，从人工线走向可适应的机器人系统，契合制造业回流美国的讨论。", "body_en": "Bob McGrew Launches $1.5B AI Startup Arda to Accelerate U.S. Manufacturing.\n\nBob McGrew, fresh from leading research at OpenAI, stepped onto CNBC this week to unveil Arda—a startup building AI agents that slash factory setup times from days to minutes.\n\nFounded in 2025, Arda raised $160 million in a Series A round co-led by Altimeter Capital, Accel, and Khosla Ventures, pushing total funding to $230 million and valuing the company at $1.5 billion.\n\nThe platform turns product designs into assembly instructions, already deployed across Anduril's divisions to cut engineering workflows from 30 hours to 2.5 hours or even 10 hours to 15 minutes. Co-founder Augustus Odena envisions AI that designs and runs entire factories, starting with manual lines and advancing to adaptable robotic systems amid pushes to bring production back to the U.S.", "body_zh": "前 OpenAI 研究负责人推出估值 15 亿美元制造 AI 创业公司 Arda。\n\n刚离开 OpenAI 研究负责人岗位的 Bob McGrew 登上 CNBC，介绍能把工厂筹备从“天”压到“分钟”的 AI 智能体创业公司 Arda。\n\nArda 成立于 2025 年，本轮 A 轮融资 1.6 亿美元，由 Altimeter、Accel 与 Khosla 等领投，累计融资约 2.3 亿美元，估值约 15 亿美元。\n\n平台可将产品设计转为装配指令，已在 Anduril 多部门落地，把部分工程流程从约 30 小时压到 2.5 小时，甚至 10 小时到 15 分钟。联合创始人设想 AI 逐步设计并运行整座工厂，从人工线走向可适应的机器人系统，契合制造业回流美国的讨论。", "url": "https://x.com/i/trending/2112569366479048900", "category": "News", "topics": ["Technology", "Business & Finance"], "updated_at": "2026-10-21T00:10:14.000Z"}, {"id": "2112613027359216016", "domain": "商业", "title_en": "Goldman Sachs, Microsoft, McDonald's Object to Tokenized Shares on OKXICE Platform", "title_zh": "高盛、微软、麦当劳等反对 OKXICE 平台上的代币化正股", "hook_en": "Major companies like Goldman Sachs, Microsoft, and McDonald's are drawing a line against tokenized versions of their shares on a new blockchain trading venue.", "hook_zh": "高盛、微软、麦当劳等大型公司明确反对在新区块链交易场所上架其股份的代币化版本。", "summary_en": "The OKXICE platform, backed by OKX and Intercontinental Exchange, aims to offer 24/7 trading of share-backed tokens settled in stablecoins under an SEC innovation exemption. Sixteen firms, including recent opt-outs from Alphabet, Qualcomm, and Caterpillar, have now objected, leaving 47 from the original 62 without disclosed pushback. Andrew Cuomo called the responses natural, noting the model allows companies to watch from the sidelines in this controlled sandbox. The objections test how traditional stocks move onchain amid questions on market structure and investor protections.", "summary_zh": "OKX 与洲际交易所支持的 OKXICE 平台，拟在 SEC 创新豁免框架下提供由稳定币结算、可 24/7 交易的股份代币。包括近日表态的 Alphabet、高通、卡特彼勒在内，已有约 16 家公司提出反对，使可上架标的承压。支持者强调合规创新与流动性，反对方则担忧品牌、股东权益与监管边界。事态仍随监管沟通演进。", "body_en": "Goldman Sachs, Microsoft, McDonald's Object to Tokenized Shares on OKXICE Platform.\n\nMajor companies like Goldman Sachs, Microsoft, and McDonald's are drawing a line against tokenized versions of their shares on a new blockchain trading venue.\n\nThe OKXICE platform, backed by OKX and Intercontinental Exchange, aims to offer 24/7 trading of share-backed tokens settled in stablecoins under an SEC innovation exemption. Sixteen firms, including recent opt-outs from Alphabet, Qualcomm, and Caterpillar, have now objected, leaving 47 from the original 62 without disclosed pushback.\n\nAndrew Cuomo called the responses natural, noting the model allows companies to watch from the sidelines in this controlled sandbox. The objections test how traditional stocks move onchain amid questions on market structure and investor protections.", "body_zh": "高盛、微软、麦当劳等反对 OKXICE 平台上的代币化正股。\n\n高盛、微软、麦当劳等大型公司明确反对在新区块链交易场所上架其股份的代币化版本。\n\nOKX 与洲际交易所支持的 OKXICE 平台，拟在 SEC 创新豁免框架下提供由稳定币结算、可 24/7 交易的股份代币。包括近日表态的 Alphabet、高通、卡特彼勒在内，已有约 16 家公司提出反对，使可上架标的承压。\n\n支持者强调合规创新与流动性，反对方则担忧品牌、股东权益与监管边界。事态仍随监管沟通演进。", "url": "https://x.com/i/trending/2112613027359216016", "category": "News", "topics": ["Cryptocurrency"], "updated_at": "2026-10-20T22:01:24.000Z"}, {"id": "2112566578415849780", "domain": "商业", "title_en": "Copper Supply Shortfall Looms from 2028 Amid Surging Demand", "title_zh": "报告预警：2028 年起铜供应或现巨大缺口", "hook_en": "Copper powers electric vehicles, grids, and AI data centers, but a new report warns of massive shortages starting in 2028 as supply struggles to keep up.", "hook_zh": "铜支撑电动车、电网与 AI 数据中心，新报告警告自 2028 年起供应恐严重跟不上需求。", "summary_en": "BloombergNEF projects copper demand jumping 61% to 46 million tonnes by 2050, driven by electric transport needing 11.4 million tonnes, while supply deficits could hit 20 million tonnes without new investments. Chile, the top producer with 180 million tonnes in reserves, faces slumping output from aging mines, low ore grades, weather, and accidents—potentially dropping to 5 million tonnes by 2026, the lowest in over 20 years. Prices have surged to $14,500 per tonne, with banks forecasting further rises, though closing the gap requires $332 billion and 17 years per new mine.", "summary_zh": "BloombergNEF 预计到 2050 年铜需求增约 61% 至 4600 万吨，其中电动交通约需 1140 万吨；若无足够新投资，供应缺口或达 2000 万吨。头号产国智利储量约 1.8 亿吨，但老龄矿、品位下降、天气与事故或使产量跌向二十多年来低位。铜价已升至约每吨 1.45 万美元，银行看好续涨；新矿山从投建到投产常需约 17 年与巨额资本。", "body_en": "Copper Supply Shortfall Looms from 2028 Amid Surging Demand.\n\nCopper powers electric vehicles, grids, and AI data centers, but a new report warns of massive shortages starting in 2028 as supply struggles to keep up.\n\nBloombergNEF projects copper demand jumping 61% to 46 million tonnes by 2050, driven by electric transport needing 11.4 million tonnes, while supply deficits could hit 20 million tonnes without new investments.\n\nChile, the top producer with 180 million tonnes in reserves, faces slumping output from aging mines, low ore grades, weather, and accidents—potentially dropping to 5 million tonnes by 2026, the lowest in over 20 years. Prices have surged to $14,500 per tonne, with banks forecasting further rises, though closing the gap requires $332 billion and 17 years per new mine.", "body_zh": "报告预警：2028 年起铜供应或现巨大缺口。\n\n铜支撑电动车、电网与 AI 数据中心，新报告警告自 2028 年起供应恐严重跟不上需求。\n\nBloombergNEF 预计到 2050 年铜需求增约 61% 至 4600 万吨，其中电动交通约需 1140 万吨；若无足够新投资，供应缺口或达 2000 万吨。\n\n头号产国智利储量约 1.8 亿吨，但老龄矿、品位下降、天气与事故或使产量跌向二十多年来低位。铜价已升至约每吨 1.45 万美元，银行看好续涨；新矿山从投建到投产常需约 17 年与巨额资本。", "url": "https://x.com/i/trending/2112566578415849780", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T15:35:06.000Z"}, {"id": "2112486884211650655", "domain": "中国", "title_en": "Sindh CM Secures 34 China Deals at Shanghai Conference", "title_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作", "hook_en": "Sindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.", "hook_zh": "信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。", "summary_en": "At the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province. The event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "summary_zh": "2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。支持者称这延续巴中建交 75 年的合作传统。", "body_en": "Sindh CM Secures 34 China Deals at Shanghai Conference.\n\nSindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.\n\nAt the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province.\n\nThe event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "body_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作。\n\n信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。\n\n2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。\n\n支持者称这延续巴中建交 75 年的合作传统。", "url": "https://x.com/i/trending/2112486884211650655", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T13:25:56.000Z"}, {"id": "2112022699237310708", "domain": "中国", "title_en": "Liangzhu Forum Opens Marking 90th Anniversary of Ancient Ruins Discovery", "title_zh": "良渚论坛开幕：纪念遗址发现 90 周年", "hook_en": "Experts from nearly 60 countries gathered in Hangzhou to celebrate 5,000-year-old Liangzhu ruins, blending ancient history with modern tech and global chats.", "hook_zh": "近 60 国专家齐聚杭州，围绕约五千年历史的良渚遗址，把古代文明、现代技术与国际交流放在同一舞台。", "summary_en": "The fourth Liangzhu Forum, held October 18-20 in Zhejiang province, honors the 90th anniversary of discovering the UNESCO-listed Liangzhu ruins, evidence of an early advanced society with rice farming. Under the theme 'Bridging the Past and the Future,' it features forums, an artists' exhibition, a cultural market with Belt and Road products, and AI glasses at the museum that guide visitors using real archives. An American archaeologist on his first China trip praised the scenery and hopes to study sites, while an Australian curator noted the link between ancient Liangzhu and today's Hangzhou; young volunteers provide bilingual support amid calls for global heritage cooperation.", "summary_zh": "第四届良渚论坛于 10 月 18–20 日在浙江举行，纪念列入联合国教科文组织名录的良渚遗址发现 90 周年——遗址见证早期发达社会与稻作农业。主题为「连接过去与未来」，活动包括论坛、艺术家展览、「一带一路」相关文创市集，以及博物馆用真实档案导览的 AI 眼镜。首次访华的美国考古学家称赞景色并希望研究遗址；澳大利亚策展人谈到古代良渚与今日杭州的关联；青年志愿者提供双语服务，各方呼吁加强全球遗产合作。", "body_en": "Liangzhu Forum Opens Marking 90th Anniversary of Ancient Ruins Discovery.\n\nExperts from nearly 60 countries gathered in Hangzhou to celebrate 5,000-year-old Liangzhu ruins, blending ancient history with modern tech and global chats.\n\nThe fourth Liangzhu Forum, held October 18-20 in Zhejiang province, honors the 90th anniversary of discovering the UNESCO-listed Liangzhu ruins, evidence of an early advanced society with rice farming.\n\nUnder the theme 'Bridging the Past and the Future,' it features forums, an artists' exhibition, a cultural market with Belt and Road products, and AI glasses at the museum that guide visitors using real archives. An American archaeologist on his first China trip praised the scenery and hopes to study sites, while an Australian curator noted the link between ancient Liangzhu and today's Hangzhou; young volunteers provide bilingual support amid calls for global heritage cooperation.", "body_zh": "良渚论坛开幕：纪念遗址发现 90 周年。\n\n近 60 国专家齐聚杭州，围绕约五千年历史的良渚遗址，把古代文明、现代技术与国际交流放在同一舞台。\n\n第四届良渚论坛于 10 月 18–20 日在浙江举行，纪念列入联合国教科文组织名录的良渚遗址发现 90 周年——遗址见证早期发达社会与稻作农业。主题为「连接过去与未来」，活动包括论坛、艺术家展览、「一带一路」相关文创市集，以及博物馆用真实档案导览的 AI 眼镜。\n\n首次访华的美国考古学家称赞景色并希望研究遗址；澳大利亚策展人谈到古代良渚与今日杭州的关联；青年志愿者提供双语服务，各方呼吁加强全球遗产合作。", "url": "https://x.com/i/trending/2112022699237310708", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T03:21:48.000Z"}, {"id": "2112572571275370804", "domain": "中国", "title_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs", "title_zh": "日本钇供应告急，寻求美方协助应对中国出口限制", "hook_en": "Japan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.", "hook_zh": "用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。", "summary_en": "Yttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored. Japan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "summary_zh": "2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "body_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs.\n\nJapan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.\n\nYttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored.\n\nJapan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "body_zh": "日本钇供应告急，寻求美方协助应对中国出口限制。\n\n用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。\n\n2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。\n\n日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "url": "https://x.com/i/trending/2112572571275370804", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T19:24:35.000Z"}, {"id": "2112810342728323293", "domain": "中国", "title_en": "China Replaces Billboards with Scientists' Portraits in Major Cities", "title_zh": "中国多地用科学家肖像替换地铁商业广告", "hook_en": "Rocket scientist Qian Xuesen's giant portrait now greets shoppers in a Heze mall, replacing flashy ads with faces of national heroes.", "hook_zh": "走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。", "summary_en": "Since August 2026, cities like Heze, Zhengzhou, and Chongqing have filled public screens in malls, metros, and plazas with portraits of scientists such as Qian Xuesen, Yuan Longping, and Tu Youyou, complete with notes on their breakthroughs in rockets, rice, and malaria drugs. Local venues made these voluntary changes, often timed for holidays to highlight achievements in science and defense. The shift has sparked online talk about honoring innovators over celebrities and what public spaces say about a society's values.", "summary_zh": "中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "body_en": "China Replaces Metro Ads with Portraits of Scientists.\n\nImagine stepping into a metro station where giant screens honor scientists like hybrid rice pioneer Yuan Longping instead of flashy ads. It's a simple swap that's getting people talking about role models.\n\nChina has started replacing advertisements on large public screens in metro stations, malls, and other spaces with portraits of renowned scientists such as agronomist Yuan Longping, Nobel winner Tu Youyou for malaria treatment, rocket expert Qian Xuesen, and nuclear physicist Deng Jiaxian.\n\nThe initiative began in Shandong province in August 2026 and spread to cities like Zhengzhou and Chongqing, especially around national holidays, with businesses voluntarily dedicating the space to celebrate scientific achievements and inspire the next generation. Videos of these displays have sparked online conversations in places like India, where some contrast it with local public messaging and call for emulating the focus on innovation over commercial noise.", "body_zh": "中国多地用科学家肖像替换地铁商业广告。\n\n走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。\n\n中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。\n\n相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "url": "https://x.com/i/trending/2112810342728323293", "category": "News", "topics": ["News"], "updated_at": "2026-10-21T10:44:04.000Z"}, {"id": "2112405151768100963", "domain": "中国", "title_en": "Philippine Senators Push to Expel Chinese Ambassador Over Sea Threat", "title_zh": "菲律宾参议员推动驱逐中国大使", "hook_en": "Chinese Ambassador Jing Quan's words hung heavy: China could 'easily win' with force in the West Philippine Sea, though it prefers peace. Philippine senators fired back, demanding he be sent home.", "hook_zh": "中国大使景泉称中国可「轻松打赢」与菲冲突，引发参议员要求将其驱逐。", "summary_en": "Senators Risa Hontiveros and Erwin Tulfo filed resolutions urging President Marcos to declare Ambassador Jing persona non grata after his remarks, seen as a veiled threat amid China's vessel harassment and illegal fishing in Philippine waters. The Department of Foreign Affairs summoned Jing to protest, while Senator Kiko Pangilinan sharply challenged Marcos to act decisively. The Chinese Embassy hit back by listing critical lawmakers online, but Malacañang favors diplomatic channels over expulsion to avoid escalation.", "summary_zh": "参议员洪蒂维罗斯与图尔福于 10 月 20 日前后提交决议，敦促马科斯总统宣布大使为不受欢迎人士或要求北京召回。言论回应菲防长称中国为地区麻烦制造者，中国使馆随后在社媒发出「你已上榜」等嘲讽帖。外交部 10 月 19 日召见景泉，称其言论具挑衅性；马科斯更倾向外交沟通而非驱逐。", "body_en": "Philippine Senators Push to Expel Chinese Ambassador Over Threatening Remarks.\n\nChinese Ambassador Jing Quan boasted that China could 'easily win' any conflict with the Philippines, igniting calls from senators to send him packing.\n\nSenators Risa Hontiveros and Erwin Tulfo filed resolutions on October 20 and the day before, urging President Marcos to declare Ambassador Jing persona non grata or request his recall from Beijing. The remarks responded to Defense Secretary Gilberto Teodoro Jr.\n\nlabeling China a regional troublemaker, prompting the Chinese Embassy's taunting social media posts like 'You are now on the list' targeting critics. The Department of Foreign Affairs summoned Jing on October 19, calling his words a provocative threat amid ongoing West Philippine Sea tensions, though Marcos prefers diplomatic talks over expulsion.", "body_zh": "菲律宾参议员推动驱逐中国大使。\n\n中国大使景泉称中国可「轻松打赢」与菲冲突，引发参议员要求将其驱逐。\n\n参议员洪蒂维罗斯与图尔福于 10 月 20 日前后提交决议，敦促马科斯总统宣布大使为不受欢迎人士或要求北京召回。言论回应菲防长称中国为地区麻烦制造者，中国使馆随后在社媒发出「你已上榜」等嘲讽帖。\n\n外交部 10 月 19 日召见景泉，称其言论具挑衅性；马科斯更倾向外交沟通而非驱逐。", "url": "https://x.com/i/trending/2112405151768100963", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T10:24:16.000Z"}, {"id": "2112161836116132305", "domain": "中国", "title_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects", "title_zh": "中国限制全断面掘进机出口，印度基建承压", "hook_en": "India's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.", "hook_zh": "印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。", "summary_en": "China's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks. The controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "summary_zh": "中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "body_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects.\n\nIndia's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.\n\nChina's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks.\n\nThe controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "body_zh": "中国限制全断面掘进机出口，印度基建承压。\n\n印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。\n\n中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。\n\n印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "url": "https://x.com/i/trending/2112161836116132305", "category": "News", "topics": ["News", "Business & Finance"], "updated_at": "2026-10-20T19:24:59.000Z"}, {"id": "2112437946263474495", "domain": "中国", "title_en": "China Tracks U.S. Warship Near Disputed South China Sea Shoal", "title_zh": "中国跟踪靠近争议南沙礁盘的美舰", "hook_en": "Early Tuesday, a U.S. littoral combat ship sailed into waters China calls its own near Xianbin Jiao, prompting Beijing to send forces for close monitoring.", "hook_zh": "周二早间，一艘美军濒海战斗舰驶入中方所称仙宾礁附近水域，北京派出力量抵近监控。", "summary_en": "China's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability. The Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.", "summary_zh": "中国人民解放军海军指责美舰「查尔斯顿」号于 10 月 20 日非法进入南沙群岛仙宾礁邻近水域，称其威胁主权与地区稳定。菲律宾反驳称该舰处于国际水域、无需许可，并援引 2016 年仲裁裁决否定中方主张。事件发生在同礁附近近期船只擦碰之后，正值多国在南海存在重叠领土主张。", "body_en": "China Tracks U.S. Warship Near Disputed South China Sea Shoal.\n\nEarly Tuesday, a U.S. littoral combat ship sailed into waters China calls its own near Xianbin Jiao, prompting Beijing to send forces for close monitoring.\n\nChina's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability.\n\nThe Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.", "body_zh": "中国跟踪靠近争议南沙礁盘的美舰。\n\n周二早间，一艘美军濒海战斗舰驶入中方所称仙宾礁附近水域，北京派出力量抵近监控。\n\n中国人民解放军海军指责美舰「查尔斯顿」号于 10 月 20 日非法进入南沙群岛仙宾礁邻近水域，称其威胁主权与地区稳定。菲律宾反驳称该舰处于国际水域、无需许可，并援引 2016 年仲裁裁决否定中方主张。\n\n事件发生在同礁附近近期船只擦碰之后，正值多国在南海存在重叠领土主张。", "url": "https://x.com/i/trending/2112437946263474495", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T15:35:04.000Z"}, {"id": "2112529713906200727", "domain": "中国", "title_en": "Lincolnshire Mayor Signs Taiwan Partnership Amid Authority Questions", "title_zh": "林肯郡市长与台湾台南签署伙伴协议引权限争议", "hook_en": "Dame Andrea Jenkyns beamed from a video call, pen in hand, announcing a new deal with Taiwan's Tainan to boost trade and innovation. Online replies quickly pointed out mayors don't handle international agreements.", "hook_zh": "这位市长在视频连线中高调宣布与台南达成协议，网友很快指出市长无权签署国际条约。", "summary_en": "Greater Lincolnshire's mayor shared images of signing what she called a landmark trade agreement with Tainan, highlighting opportunities in agriculture, tech, and culture. Critics, including a former council leader, labeled it deluded and beyond her powers, clarifying it's actually a sister-city partnership for local exchanges. Taiwanese media confirmed the first such UK-Taiwan link, while users stressed precise wording to avoid misleading the public on formal trade deals.", "summary_zh": "大林肯郡市长分享与台南签署“里程碑贸易协议”的画面，强调农业、科技与文化机会。包括前议会领袖在内的批评者称其越权，澄清实为姐妹城市式地方交流。台湾媒体确认此为英台此类联系的首例，舆论呼吁措辞准确，避免被误解为正式贸易协定。", "body_en": "Lincolnshire Mayor Signs Taiwan Partnership Amid Authority Questions.\n\nDame Andrea Jenkyns beamed from a video call, pen in hand, announcing a new deal with Taiwan's Tainan to boost trade and innovation. Online replies quickly pointed out mayors don't handle international agreements.\n\nGreater Lincolnshire's mayor shared images of signing what she called a landmark trade agreement with Tainan, highlighting opportunities in agriculture, tech, and culture.\n\nCritics, including a former council leader, labeled it deluded and beyond her powers, clarifying it's actually a sister-city partnership for local exchanges. Taiwanese media confirmed the first such UK-Taiwan link, while users stressed precise wording to avoid misleading the public on formal trade deals.", "body_zh": "林肯郡市长与台湾台南签署伙伴协议引权限争议。\n\n这位市长在视频连线中高调宣布与台南达成协议，网友很快指出市长无权签署国际条约。\n\n大林肯郡市长分享与台南签署“里程碑贸易协议”的画面，强调农业、科技与文化机会。\n\n包括前议会领袖在内的批评者称其越权，澄清实为姐妹城市式地方交流。台湾媒体确认此为英台此类联系的首例，舆论呼吁措辞准确，避免被误解为正式贸易协定。", "url": "https://x.com/i/trending/2112529713906200727", "category": "News", "topics": ["News"], "updated_at": "2026-10-20T13:07:49.000Z"}, {"id": "2112272182730801541", "domain": "中国", "title_en": "Super Typhoon Champi Hits 185 mph, Strongest Storm of 2026", "title_zh": "超强台风“灿琵”风速约 185 英里/时，并列 2026 年最强", "hook_en": "Super Typhoon Champi roared to life in the western Pacific, tying for the year's fiercest with 185 mph winds and a massive, well-defined eye visible from space.", "hook_zh": "西太平洋超强台风“灿琵”生成后迅速增强，风速约 185 英里/时，卫星云图可见巨大清晰风眼。", "summary_en": "The storm brushed just 10 miles from Guam's southern tip as a Category 4, causing some power outages but sparing the island major damage before intensifying further. In the Philippines, named Rosal there, PAGASA raised wind signals up to No. 1 in northern Luzon areas like Batanes, with No. 2 or 3 possible, though it should stay over the Philippine Sea without hitting main islands. Forecasters predict gradual weakening as it heads northwest toward east of Taiwan, potentially bringing heavy rain, strong winds, and rough seas while drawing awe for its striking satellite views.", "summary_zh": "风暴以四级强度擦过关岛南端约 10 英里处，造成部分停电但未酿重大破坏，随后继续增强。菲律宾命名为“罗莎”（Rosal），气象局对吕宋北部巴丹等地发布一号风信号，不排除升至二、三号，但主体预计仍在菲律宾海活动、不正面袭击主要岛屿。预报称其将向台湾以东西北行并逐渐减弱，可能带来强风雨与大浪。", "body_en": "Super Typhoon Champi Hits 185 mph, Strongest Storm of 2026.\n\nSuper Typhoon Champi roared to life in the western Pacific, tying for the year's fiercest with 185 mph winds and a massive, well-defined eye visible from space.\n\nThe storm brushed just 10 miles from Guam's southern tip as a Category 4, causing some power outages but sparing the island major damage before intensifying further. In the Philippines, named Rosal there, PAGASA raised wind signals up to No.\n\n1 in northern Luzon areas like Batanes, with No. 2 or 3 possible, though it should stay over the Philippine Sea without hitting main islands. Forecasters predict gradual weakening as it heads northwest toward east of Taiwan, potentially bringing heavy rain, strong winds, and rough seas while drawing awe for its striking satellite views.", "body_zh": "超强台风“灿琵”风速约 185 英里/时，并列 2026 年最强。\n\n西太平洋超强台风“灿琵”生成后迅速增强，风速约 185 英里/时，卫星云图可见巨大清晰风眼。\n\n风暴以四级强度擦过关岛南端约 10 英里处，造成部分停电但未酿重大破坏，随后继续增强。\n\n菲律宾命名为“罗莎”（Rosal），气象局对吕宋北部巴丹等地发布一号风信号，不排除升至二、三号，但主体预计仍在菲律宾海活动、不正面袭击主要岛屿。预报称其将向台湾以东西北行并逐渐减弱，可能带来强风雨与大浪。", "url": "https://x.com/i/trending/2112272182730801541", "category": "News", "topics": ["Natural Disasters"], "updated_at": "2026-10-21T12:48:38.000Z"}, {"id": "2112653366941950015", "domain": "中国", "title_en": "China's 'Fake Commuting' Hides Unemployment from Families", "title_zh": "中国出现“假装上班”：失业者用作息瞒住家人", "hook_en": "A jobless worker waves goodbye each morning, 'Bye, I'm off to work,' then heads straight to the bar. This daily pretense is spreading amid China's tough job market.", "hook_zh": "有人每天挥手说“我去上班了”，却径直去酒吧——在就业承压背景下，这类掩饰正被更多讨论。", "summary_en": "Unemployed people in China are leaving home on work-like schedules to keep families from knowing they're jobless, driven by a weak hiring environment, property crisis, automation, and AI adoption. Social platforms buzz with tips on filling the day in cafes, parks, or libraries, echoing the shame in the 2008 Japanese film Tokyo Sonata and similar habits elsewhere. The trend underscores cultural stigma around unemployment and efforts to preserve family harmony despite economic pressures.", "summary_zh": "部分失业者按上班时间出门，以免家人知晓，背后是招聘偏弱、房地产调整、自动化与 AI 应用等因素。社交平台流传在咖啡馆、公园、图书馆消磨白天的经验，令人联想到日本电影《东京奏鸣曲》中的耻辱感。现象折射失业污名与家庭体面压力，也引发对就业与社会保障的讨论。", "body_en": "China's 'Fake Commuting' Hides Unemployment from Families.\n\nA jobless worker waves goodbye each morning, 'Bye, I'm off to work,' then heads straight to the bar. This daily pretense is spreading amid China's tough job market.\n\nUnemployed people in China are leaving home on work-like schedules to keep families from knowing they're jobless, driven by a weak hiring environment, property crisis, automation, and AI adoption.\n\nSocial platforms buzz with tips on filling the day in cafes, parks, or libraries, echoing the shame in the 2008 Japanese film Tokyo Sonata and similar habits elsewhere. The trend underscores cultural stigma around unemployment and efforts to preserve family harmony despite economic pressures.", "body_zh": "中国出现“假装上班”：失业者用作息瞒住家人。\n\n有人每天挥手说“我去上班了”，却径直去酒吧——在就业承压背景下，这类掩饰正被更多讨论。\n\n部分失业者按上班时间出门，以免家人知晓，背后是招聘偏弱、房地产调整、自动化与 AI 应用等因素。\n\n社交平台流传在咖啡馆、公园、图书馆消磨白天的经验，令人联想到日本电影《东京奏鸣曲》中的耻辱感。现象折射失业污名与家庭体面压力，也引发对就业与社会保障的讨论。", "url": "https://x.com/i/trending/2112653366941950015", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T21:21:21.000Z"}, {"id": "2112579117904535807", "domain": "中国", "title_en": "Micron Funds New York Minerals Processing for AI Chip Supplies", "title_zh": "美光资助纽约关键矿物加工，保障 AI 存储芯片原料", "hook_en": "Micron is stepping up to secure vital materials for its AI memory chips right at home in New York. The move aims to cut reliance on overseas sources amid surging demand.", "hook_zh": "美光加码在纽约本地保障 AI 内存芯片关键材料，以降低对海外供应的依赖。", "summary_en": "Micron Technology announced strategic funding for Indium Corporation to expand refining of critical minerals like indium at its Rome, New York facility, paired with a long-term supply agreement. This supports Micron's $3 billion U.S. semiconductor supply chain investment and addresses China's dominance in key materials production. Despite the positive step for national security and AI growth, shares dipped 2-3% that day amid concerns over AI spending, Taiwan strikes, and competition.", "summary_zh": "美光宣布战略资助 Indium Corporation，扩大其纽约罗马工厂对铟等关键矿物的精炼，并签订长期供应协议。此举支撑美光约 30 亿美元的美国半导体供应链投入，意在应对中国在关键材料领域的优势地位。消息公布当日美光股价仍下跌约 2%–3%，市场同时消化 AI 开支、台海相关扰动与竞争等担忧。", "body_en": "Micron Funds New York Minerals Processing for AI Chip Supplies.\n\nMicron is stepping up to secure vital materials for its AI memory chips right at home in New York. The move aims to cut reliance on overseas sources amid surging demand.\n\nMicron Technology announced strategic funding for Indium Corporation to expand refining of critical minerals like indium at its Rome, New York facility, paired with a long-term supply agreement. This supports Micron's $3 billion U.S.\n\nsemiconductor supply chain investment and addresses China's dominance in key materials production. Despite the positive step for national security and AI growth, shares dipped 2-3% that day amid concerns over AI spending, Taiwan strikes, and competition.", "body_zh": "美光资助纽约关键矿物加工，保障 AI 存储芯片原料。\n\n美光加码在纽约本地保障 AI 内存芯片关键材料，以降低对海外供应的依赖。\n\n美光宣布战略资助 Indium Corporation，扩大其纽约罗马工厂对铟等关键矿物的精炼，并签订长期供应协议。\n\n此举支撑美光约 30 亿美元的美国半导体供应链投入，意在应对中国在关键材料领域的优势地位。消息公布当日美光股价仍下跌约 2%–3%，市场同时消化 AI 开支、台海相关扰动与竞争等担忧。", "url": "https://x.com/i/trending/2112579117904535807", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-20T16:26:46.000Z"}, {"id": "2112296384745631848", "domain": "国际", "title_en": "France Protests Spark Debate on Russian Interference Claims", "title_zh": "法国抗议潮引发「俄方干涉」说法之争", "hook_en": "Hundreds of thousands marched in France on October 17 over soaring living costs and cuts to education, only for the unrest to fuel sharp online arguments about hidden foreign hands.", "hook_zh": "10 月 17 日法国数十万人抗议生活成本飙升与教育削减，骚乱随后在网上激起「是否有外部黑手」的激烈争论。", "summary_en": "Demonstrations drew around 550,000 people nationwide, including 110,000 in Paris, starting with student demands before expanding to unions and turning violent with looting, arson, and over 1,200 arrests. Estonian MP Marko Mihkelson claimed Russia benefits from the chaos in France and Italy as part of a shadow war, while a satirical post by Wolfgang Richter mocked the idea of Putin paying protesters and called for speech curbs. Officials insist the unrest stems from domestic economic woes, with no evidence of Russian or Iranian organization, though both nations have amplified the violence in propaganda; online views split between those seeing Moscow's gain and critics dismissing it as scapegoating real policy failures.", "summary_zh": "全国约 55 万人上街，巴黎约 11 万，由学生诉求扩至工会，并演变为抢劫、纵火与逾 1200 人被捕。爱沙尼亚议员 Marko Mihkelson 称俄从法、意乱局获益，属影子战争；Wolfgang Richter 的讽刺帖则嘲讽「普京出钱抗议」说法并呼吁限制言论。官方坚持动因是国内经济困境，并无俄、伊组织证据，尽管两国宣传放大了暴力画面；网上有人强调莫斯科受益，也有人批评这是在替真正的政策失败找替罪羊。", "body_en": "France Protests Spark Debate on Russian Interference Claims.\n\nHundreds of thousands marched in France on October 17 over soaring living costs and cuts to education, only for the unrest to fuel sharp online arguments about hidden foreign hands.\n\nDemonstrations drew around 550,000 people nationwide, including 110,000 in Paris, starting with student demands before expanding to unions and turning violent with looting, arson, and over 1,200 arrests.\n\nEstonian MP Marko Mihkelson claimed Russia benefits from the chaos in France and Italy as part of a shadow war, while a satirical post by Wolfgang Richter mocked the idea of Putin paying protesters and called for speech curbs. Officials insist the unrest stems from domestic economic woes, with no evidence of Russian or Iranian organization, though both nations have amplified the violence in propaganda; online views split between those seeing Moscow's gain and critics dismissing it as scapegoating real policy failures.", "body_zh": "法国抗议潮引发「俄方干涉」说法之争。\n\n10 月 17 日法国数十万人抗议生活成本飙升与教育削减，骚乱随后在网上激起「是否有外部黑手」的激烈争论。\n\n全国约 55 万人上街，巴黎约 11 万，由学生诉求扩至工会，并演变为抢劫、纵火与逾 1200 人被捕。爱沙尼亚议员 Marko Mihkelson 称俄从法、意乱局获益，属影子战争；Wolfgang Richter 的讽刺帖则嘲讽「普京出钱抗议」说法并呼吁限制言论。\n\n官方坚持动因是国内经济困境，并无俄、伊组织证据，尽管两国宣传放大了暴力画面；网上有人强调莫斯科受益，也有人批评这是在替真正的政策失败找替罪羊。", "url": "https://x.com/i/trending/2112296384745631848", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T14:03:55.000Z"}, {"id": "2112460842902151394", "domain": "国际", "title_en": "Lawmakers Back Ukraine Aid Amid Online Backlash from Trump Supporters", "title_zh": "两党议员力挺援乌，遭特朗普支持者网上猛烈抨击", "hook_en": "U.S. lawmakers from both parties rallied behind Zelensky on calls about sanctions waivers and restricted weapons access, only to face fierce online accusations of treason from Trump backers pushing for peace talks with Russia.", "hook_zh": "美国两党议员就制裁豁免与武器受限与泽连斯基通话力挺，却遭主张对俄和谈的特朗普支持者网上痛批为「叛国」。", "summary_en": "Rep. Brad Schneider, a Democrat, joined a bipartisan call where Zelensky raised alarms over waived U.S. sanctions on Russia and limits on Starlink and Patriot missiles, urging steady defense support. Rep. Brian Fitzpatrick, a Republican, plans his own talk with Zelensky on Starshield, sanctions, and aid, promising probes into any restrictions. Critics online branded the lawmakers traitors for prioritizing Ukraine over Trump's negotiation push, calling the country corrupt and demanding an America First end to involvement. The clash highlights deep divides over U.S. policy shifts like energy deals with Russia and Starlink curbs.", "summary_zh": "民主党众议员布拉德·施奈德参加两党通话，泽连斯基对美豁免对俄制裁及限制星链、爱国者导弹表示警惕，敦促稳定防务支持。共和党众议员布赖恩·菲茨帕特里克计划另与泽连斯基谈星盾、制裁与援助，并承诺调查任何限制。网上批评者称议员「叛国」、优先乌克兰而非特朗普谈判路线，指乌腐败并要求「美国优先」结束介入。争执凸显能源交易、星链限制等政策转向下的深刻分裂。", "body_en": "Lawmakers Back Ukraine Aid Amid Online Backlash from Trump Supporters.\n\nU.S. lawmakers from both parties rallied behind Zelensky on calls about sanctions waivers and restricted weapons access, only to face fierce online accusations of treason from Trump backers pushing for peace talks with Russia.\n\nRep. Brad Schneider, a Democrat, joined a bipartisan call where Zelensky raised alarms over waived U.S. sanctions on Russia and limits on Starlink and Patriot missiles, urging steady defense support. Rep.\n\nBrian Fitzpatrick, a Republican, plans his own talk with Zelensky on Starshield, sanctions, and aid, promising probes into any restrictions. Critics online branded the lawmakers traitors for prioritizing Ukraine over Trump's negotiation push, calling the country corrupt and demanding an America First end to involvement. The clash highlights deep divides over U.S. policy shifts like energy deals with Russia and Starlink curbs.", "body_zh": "两党议员力挺援乌，遭特朗普支持者网上猛烈抨击。\n\n美国两党议员就制裁豁免与武器受限与泽连斯基通话力挺，却遭主张对俄和谈的特朗普支持者网上痛批为「叛国」。\n\n民主党众议员布拉德·施奈德参加两党通话，泽连斯基对美豁免对俄制裁及限制星链、爱国者导弹表示警惕，敦促稳定防务支持。共和党众议员布赖恩·菲茨帕特里克计划另与泽连斯基谈星盾、制裁与援助，并承诺调查任何限制。\n\n网上批评者称议员「叛国」、优先乌克兰而非特朗普谈判路线，指乌腐败并要求「美国优先」结束介入。争执凸显能源交易、星链限制等政策转向下的深刻分裂。", "url": "https://x.com/i/trending/2112460842902151394", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T08:32:59.000Z"}, {"id": "2112558002708648142", "domain": "国际", "title_en": "Zelensky's 2025 Warning on Russia Resurfaces Amid Skepticism", "title_zh": "泽连斯基 2025 年警告美若退出北约俄将占欧洲，言论再被热议", "hook_en": "A 2025 clip of Ukrainian President Volodymyr Zelensky warning that a U.S. NATO exit means certain Russian occupation of Europe has people online pushing back hard.", "hook_zh": "一段 2025 年采访片段再度流传：泽连斯基称美国退出北约则俄占欧洲「板上钉钉」，网上质疑声强烈。", "summary_en": "In a February 16, 2025, NBC Meet the Press interview, Zelensky told host Kristen Welker that European NATO forces lack enough brigades to match Russia's military, predicting a 100 percent risk of occupation starting with smaller ex-Soviet NATO states if the U.S. withdraws. The resurfaced excerpt drew skeptical reactions, with comments calling it 'bullshit,' pointing to supposed contradictions about Russia's struggles in Ukraine, and labeling it hyperbolic or a plea for more aid. The discussion highlights ongoing divides over Russian threats, NATO roles, and Western support for Ukraine as debates on assistance levels persist.", "summary_zh": "在 2025 年 2 月 16 日 NBC《Meet the Press》采访中，泽连斯基对主持人称欧洲北约兵力不足以匹敌俄军，若美国撤出，从前苏联加盟的较小北约国家起被占领的风险是「百分之百」。片段重火后评论两极，有人称「胡扯」，指出俄军在乌克兰受挫的矛盾，也有人视其为夸张或求援话术。讨论折射对俄威胁、北约角色与对乌援助力度的持续分歧。", "body_en": "Zelensky's 2025 Warning on Russia Resurfaces Amid Skepticism.\n\nA 2025 clip of Ukrainian President Volodymyr Zelensky warning that a U.S. NATO exit means certain Russian occupation of Europe has people online pushing back hard.\n\nIn a February 16, 2025, NBC Meet the Press interview, Zelensky told host Kristen Welker that European NATO forces lack enough brigades to match Russia's military, predicting a 100 percent risk of occupation starting with smaller ex-Soviet NATO states if the U.S. withdraws.\n\nThe resurfaced excerpt drew skeptical reactions, with comments calling it 'bullshit,' pointing to supposed contradictions about Russia's struggles in Ukraine, and labeling it hyperbolic or a plea for more aid. The discussion highlights ongoing divides over Russian threats, NATO roles, and Western support for Ukraine as debates on assistance levels persist.", "body_zh": "泽连斯基 2025 年警告美若退出北约俄将占欧洲，言论再被热议。\n\n一段 2025 年采访片段再度流传：泽连斯基称美国退出北约则俄占欧洲「板上钉钉」，网上质疑声强烈。\n\n在 2025 年 2 月 16 日 NBC《Meet the Press》采访中，泽连斯基对主持人称欧洲北约兵力不足以匹敌俄军，若美国撤出，从前苏联加盟的较小北约国家起被占领的风险是「百分之百」。\n\n片段重火后评论两极，有人称「胡扯」，指出俄军在乌克兰受挫的矛盾，也有人视其为夸张或求援话术。讨论折射对俄威胁、北约角色与对乌援助力度的持续分歧。", "url": "https://x.com/i/trending/2112558002708648142", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:59:26.000Z"}, {"id": "2112442700796690870", "domain": "国际", "title_en": "Online Debate Heats Up Over Ukraine's Status as U.S. Ally", "title_zh": "乌克兰是否算美国「盟友」引网络激辩", "hook_en": "Congresswoman Madeleine Dean called Ukraine a key ally amid Washington's cooling ties with Kyiv. Conservative voices fired back, questioning any formal bond.", "hook_zh": "众议员玛德琳·迪恩称乌克兰是关键盟友，恰逢华盛顿与基辅关系降温；保守派则追问有无正式同盟关系。", "summary_en": "The argument centers on whether Ukraine counts as a U.S. ally, with no mutual defense treaty, NATO membership, or Major Non-NATO Ally designation. Posts clash over history too: Ukraine inherited Soviet nukes in 1991, gave them up under the 1994 Budapest Memorandum for security promises from the U.S., U.K., and Russia—but those pledges didn't stop invasions in 2014 or 2022. Recent tensions spiked in mid-October 2026 when President Trump criticized Zelenskyy, eased Russia sanctions, and pushed for peace, cooling U.S.-Ukraine relations and fueling views of Ukraine as either a vital partner or a non-ally in a pricey proxy war.", "summary_zh": "争论核心在于乌克兰是否算美国盟友：双方并无共同防御条约、北约成员身份或「主要非北约盟友」认定。历史也成焦点：乌克兰 1991 年继承苏联核武，却依 1994 年《布达佩斯备忘录》放弃核武，换取美英俄安全承诺，但未能阻止 2014 与 2022 年入侵。2026 年 10 月中旬特朗普批评泽连斯基、放松对俄制裁并推动和谈，美乌关系降温，网络上「关键伙伴」与「昂贵代理人战争中的非盟友」两种叙事激烈对撞。", "body_en": "Online Debate Heats Up Over Ukraine's Status as U.S. Ally.\n\nCongresswoman Madeleine Dean called Ukraine a key ally amid Washington's cooling ties with Kyiv. Conservative voices fired back, questioning any formal bond.\n\nThe argument centers on whether Ukraine counts as a U.S. ally, with no mutual defense treaty, NATO membership, or Major Non-NATO Ally designation.\n\nPosts clash over history too: Ukraine inherited Soviet nukes in 1991, gave them up under the 1994 Budapest Memorandum for security promises from the U.S., U.K., and Russia—but those pledges didn't stop invasions in 2014 or 2022. Recent tensions spiked in mid-October 2026 when President Trump criticized Zelenskyy, eased Russia sanctions, and pushed for peace, cooling U.S.-Ukraine relations and fueling views of Ukraine as either a vital partner or a non-ally in a pricey proxy war.", "body_zh": "乌克兰是否算美国「盟友」引网络激辩。\n\n众议员玛德琳·迪恩称乌克兰是关键盟友，恰逢华盛顿与基辅关系降温；保守派则追问有无正式同盟关系。\n\n争论核心在于乌克兰是否算美国盟友：双方并无共同防御条约、北约成员身份或「主要非北约盟友」认定。\n\n历史也成焦点：乌克兰 1991 年继承苏联核武，却依 1994 年《布达佩斯备忘录》放弃核武，换取美英俄安全承诺，但未能阻止 2014 与 2022 年入侵。2026 年 10 月中旬特朗普批评泽连斯基、放松对俄制裁并推动和谈，美乌关系降温，网络上「关键伙伴」与「昂贵代理人战争中的非盟友」两种叙事激烈对撞。", "url": "https://x.com/i/trending/2112442700796690870", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T20:56:58.000Z"}, {"id": "2112533926879125584", "domain": "国际", "title_en": "Zelenskyy Warns of Russia's Propaganda Push Across Europe", "title_zh": "泽连斯基警告俄罗斯在欧洲的宣传攻势", "hook_en": "In a candid interview, Ukraine's president laid out Russia's quiet strategy to sway opinions through media and social platforms.", "hook_zh": "乌克兰总统在采访中勾勒俄罗斯通过媒体与社交平台悄然影响舆论的策略。", "summary_en": "Volodymyr Zelenskyy described Russia's decades-long hybrid war as heavily funded efforts targeting media, internet, and social platforms in countries like Italy, France, Britain, and Germany. He highlighted exploitation of issues such as migration, religion, far-right movements, and gender to influence public opinion. Social media responses pointed to Britain's £25 billion in aid to Ukraine—including £16 billion in weapons—and framed dissent as legitimate debate over spending rather than manipulation. The exchange underscores tensions between hybrid threat warnings and fatigue over war aid costs.", "summary_zh": "泽连斯基称俄罗斯数十年混合战投入大量资金，针对意大利、法国、英国、德国等国的媒体、互联网与社交平台，并利用移民、宗教、极右与性别等议题影响民意。社交平台回应中有人指出英国对乌援助约 250 亿英镑（含约 160 亿武器），并将异议视为对开支的正当辩论而非被操纵。交流凸显混合威胁警示与战争援助疲劳之间的张力。", "body_en": "Zelenskyy Warns of Russia's Propaganda Push Across Europe.\n\nIn a candid interview, Ukraine's president laid out Russia's quiet strategy to sway opinions through media and social platforms.\n\nVolodymyr Zelenskyy described Russia's decades-long hybrid war as heavily funded efforts targeting media, internet, and social platforms in countries like Italy, France, Britain, and Germany. He highlighted exploitation of issues such as migration, religion, far-right movements, and gender to influence public opinion.\n\nSocial media responses pointed to Britain's £25 billion in aid to Ukraine—including £16 billion in weapons—and framed dissent as legitimate debate over spending rather than manipulation. The exchange underscores tensions between hybrid threat warnings and fatigue over war aid costs.", "body_zh": "泽连斯基警告俄罗斯在欧洲的宣传攻势。\n\n乌克兰总统在采访中勾勒俄罗斯通过媒体与社交平台悄然影响舆论的策略。\n\n泽连斯基称俄罗斯数十年混合战投入大量资金，针对意大利、法国、英国、德国等国的媒体、互联网与社交平台，并利用移民、宗教、极右与性别等议题影响民意。\n\n社交平台回应中有人指出英国对乌援助约 250 亿英镑（含约 160 亿武器），并将异议视为对开支的正当辩论而非被操纵。交流凸显混合威胁警示与战争援助疲劳之间的张力。", "url": "https://x.com/i/trending/2112533926879125584", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T13:26:36.000Z"}, {"id": "2112540743277719599", "domain": "国际", "title_en": "Scaramucci Accuses Trump of Being Putin's Agent", "title_zh": "斯卡拉穆奇指责特朗普是「普京代理人」", "hook_en": "Anthony Scaramucci, Trump's former communications director, didn't hold back on a podcast. He listed policy decisions he says show Trump serves Putin's interests.", "hook_zh": "特朗普前通讯主管斯卡拉穆奇在播客上列出多项政策，称其服务于普京利益。", "summary_en": "On the Newsweek podcast The 1600, Scaramucci called Trump an 'agent of Putin' and shared a checklist on X, citing moves like weakening NATO alliances, threats over Greenland, exiting the nuclear forces treaty, troop pullouts from Europe, and a quiet response to Russian intel aiding attacks on U.S. forces. He described Trump's election as Russia's biggest foreign policy win since the Czars. Reactions online ranged from amplifying old Russian asset claims and memes to questions about the accusations' timing, amid recent U.S. waivers on Russian diesel exports that critics tie to the pattern.", "summary_zh": "在 Newsweek 播客《The 1600》中，斯卡拉穆奇称特朗普是「普京的代理人」，并在 X 上晒出清单，列举削弱北约、格陵兰威胁、退出核力量条约、从欧洲撤军，以及对俄情报协助袭击美军反应冷淡等。他称特朗普当选是自沙皇时代以来俄方最大外交胜利。网上反应从旧「俄资产」论与梗图，到质疑指控时机不等；近期美方对俄柴油出口豁免也被批评者纳入同一叙事。", "body_en": "Scaramucci Accuses Trump of Being Putin's Agent.\n\nAnthony Scaramucci, Trump's former communications director, didn't hold back on a podcast. He listed policy decisions he says show Trump serves Putin's interests.\n\nOn the Newsweek podcast The 1600, Scaramucci called Trump an 'agent of Putin' and shared a checklist on X, citing moves like weakening NATO alliances, threats over Greenland, exiting the nuclear forces treaty, troop pullouts from Europe, and a quiet response to Russian intel aiding attacks on U.S. forces.\n\nHe described Trump's election as Russia's biggest foreign policy win since the Czars. Reactions online ranged from amplifying old Russian asset claims and memes to questions about the accusations' timing, amid recent U.S. waivers on Russian diesel exports that critics tie to the pattern.", "body_zh": "斯卡拉穆奇指责特朗普是「普京代理人」。\n\n特朗普前通讯主管斯卡拉穆奇在播客上列出多项政策，称其服务于普京利益。\n\n在 Newsweek 播客《The 1600》中，斯卡拉穆奇称特朗普是「普京的代理人」，并在 X 上晒出清单，列举削弱北约、格陵兰威胁、退出核力量条约、从欧洲撤军，以及对俄情报协助袭击美军反应冷淡等。\n\n他称特朗普当选是自沙皇时代以来俄方最大外交胜利。网上反应从旧「俄资产」论与梗图，到质疑指控时机不等；近期美方对俄柴油出口豁免也被批评者纳入同一叙事。", "url": "https://x.com/i/trending/2112540743277719599", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T07:40:46.000Z"}, {"id": "2112290595213554074", "domain": "国际", "title_en": "Irish Parliament Clashes Over Triple Lock Military Reform", "title_zh": "爱尔兰辩论改革维和「三重锁」部署机制", "hook_en": "Protesters waved 'KEEP THE TRIPLE LOCK' banners outside while TDs inside the Dáil held 'Save Neutrality' signs during heated exchanges.", "hook_zh": "总理马丁在议会回击：「你凭什么教训我爱尔兰中立？俄罗斯不该对爱尔兰参与维和拥有否决权。」现场气氛火药味十足。", "summary_en": "Ireland's government seeks to reform the triple lock, which currently requires UN Security Council approval for major overseas military deployments, by replacing it with alignment to the UN Charter. Taoiseach Micheál Martin argues the change safeguards Ireland's peacekeeping tradition against vetoes from powers like Russia or China, backed by his party's 2024 election mandate. Opposition parties unite against it, demanding a referendum and warning it erodes neutrality toward EU-led missions, amid street protests and limited Dáil debate time.", "summary_zh": "爱尔兰政府推进《国防（修正）法案》，拟废除「三重锁」中的联合国授权要求——目前向海外部署超过 12 名国防军须经政府批准、议会表决与联合国背书。马丁等支持者称可防止俄中等大国否决，保障如黎巴嫩维和等任务，尤其在 2014 年以来联合国僵局下。反对派包括玛丽·卢·麦克唐纳与 Peadar Tóibín 指责此举偏离维和、倒向欧盟军事行动，要求公投；议员挥舞「保卫中立」标语，民间亦有抗议。", "body_en": "Ireland Debates Reforming Triple Lock on Peacekeeping Deployments.\n\nTaoiseach Micheál Martin fired back in the Dáil: 'How dare you lecture me about Irish neutrality? Russia should not have a veto on Irish participation in peacekeeping.' The exchange captured the chamber's raw tension over neutrality's future.\n\nThe Irish government is advancing the Defence (Amendment) Bill to scrap the UN mandate requirement in the Triple Lock, which currently needs government approval, a Dáil vote, and UN backing for deploying over 12 Defence Forces members abroad.\n\nProponents like Martin argue it prevents vetoes by powers like Russia or China, safeguarding missions such as Ireland's in Lebanon amid UN gridlock since 2014. Opposition leaders, including Mary Lou McDonald and Peadar Tóibín, decry it as a drift from peacekeeping to EU-aligned military action and demand a referendum, with TDs waving 'Save Neutrality' signs amid public protests.", "body_zh": "爱尔兰辩论改革维和「三重锁」部署机制。\n\n总理马丁在议会回击：「你凭什么教训我爱尔兰中立？俄罗斯不该对爱尔兰参与维和拥有否决权。」现场气氛火药味十足。\n\n爱尔兰政府推进《国防（修正）法案》，拟废除「三重锁」中的联合国授权要求——目前向海外部署超过 12 名国防军须经政府批准、议会表决与联合国背书。\n\n马丁等支持者称可防止俄中等大国否决，保障如黎巴嫩维和等任务，尤其在 2014 年以来联合国僵局下。反对派包括玛丽·卢·麦克唐纳与 Peadar Tóibín 指责此举偏离维和、倒向欧盟军事行动，要求公投；议员挥舞「保卫中立」标语，民间亦有抗议。", "url": "https://x.com/i/trending/2112290595213554074", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T12:58:53.000Z"}, {"id": "2112275134098608198", "domain": "国际", "title_en": "JD Vance Urges Voters to Back Gas Price Solutions at NC Rally", "title_zh": "万斯北卡造势：呼吁投票给能降低油价的人", "hook_en": "At a packed rally in Hendersonville, JD Vance told the crowd to vote for candidates with real fixes for $4.26-a-gallon gas—and the line quickly became election fodder.", "hook_zh": "万斯在亨德森维尔集会上说，要投票给真正有办法把汽油降下来的人——这句话迅速变成选战梗。", "summary_en": "Vice President JD Vance spoke Monday at a North Carolina campaign event for Republican candidates Michael Whatley and Jennifer Balkcom, saying to 'vote for the people who have solutions to lower the cost of gas, don’t vote for the people who made the problem.' With national gas prices near $4.26 per gallon amid Middle East tensions, some online took it as Vance criticizing his own party, leading to posts claiming he endorsed Democrats and memes turning the quote into a punchline. Supporters saw it as a contrast to past policies, while critics highlighted the irony with Republicans holding the White House. The moment underscores economic frustrations shaping the midterms.", "summary_zh": "副总统 JD Vance 周一在北卡为共和党候选人站台，称“投票给有办法降低油价的人，别投给制造问题的人”。全美油价约每加仑 4.26 美元，中东局势推高能源成本。有人把这句话解读成打脸本党，网上出现“他在帮民主党拉票”的段子；支持者则视为对比过往政策。话题折射中期选举中的生活成本焦虑。", "body_en": "JD Vance Urges Voters to Back Gas Price Solutions at NC Rally.\n\nAt a packed rally in Hendersonville, JD Vance told the crowd to vote for candidates with real fixes for $4.26-a-gallon gas—and the line quickly became election fodder.\n\nVice President JD Vance spoke Monday at a North Carolina campaign event for Republican candidates Michael Whatley and Jennifer Balkcom, saying to 'vote for the people who have solutions to lower the cost of gas, don’t vote for the people who made the problem.' With national gas prices near $4.26 per gallon amid Middle East tensions, some online took it as Vance criticizing his own party, leading to posts claiming he endorsed Democrats and memes turning the quote into a punchline.\n\nSupporters saw it as a contrast to past policies, while critics highlighted the irony with Republicans holding the White House. The moment underscores economic frustrations shaping the midterms.", "body_zh": "万斯北卡造势：呼吁投票给能降低油价的人。\n\n万斯在亨德森维尔集会上说，要投票给真正有办法把汽油降下来的人——这句话迅速变成选战梗。\n\n副总统 JD Vance 周一在北卡为共和党候选人站台，称“投票给有办法降低油价的人，别投给制造问题的人”。全美油价约每加仑 4.26 美元，中东局势推高能源成本。\n\n有人把这句话解读成打脸本党，网上出现“他在帮民主党拉票”的段子；支持者则视为对比过往政策。话题折射中期选举中的生活成本焦虑。", "url": "https://x.com/i/trending/2112275134098608198", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T12:12:55.000Z"}, {"id": "2112592169139855608", "domain": "国际", "title_en": "Hungary Blocks Ukraine and Moldova EU Accession Steps", "title_zh": "匈牙利阻断乌克兰与摩尔多瓦入盟下一阶段谈判", "hook_en": "Just days after Ukraine passed a law protecting its Hungarian-speaking minority, Hungary halted the next phase of EU talks for both Ukraine and Moldova, leaving diplomats puzzled by the silence.", "hook_zh": "乌克兰刚通过保护匈牙利语少数族裔相关法律数日，匈牙利却叫停乌、摩入盟谈判下一阶段，令各方错愕。", "summary_en": "At a meeting of EU technical experts on October 20, Hungary objected to advancing the final two negotiating clusters on green agenda, sustainable connectivity, resources, agriculture, and cohesion, while the other 26 member states supported the move. This follows recent progress, including Ukraine's minority protections law on October 12 and a meeting between Prime Minister Péter Magyar and President Volodymyr Zelenskyy to reset ties, which allowed earlier clusters to open. The block revives questions about Hungary's stance on EU enlargement, as unanimity is required, and observers note frustration over the unexplained decision despite outreach efforts.", "summary_zh": "10 月 20 日欧盟技术专家会上，匈牙利反对推进绿色议程、可持续互联、资源、农业与凝聚等最后两个谈判集群，其余 26 国支持。此前入盟程序本有进展。布达佩斯强调少数族裔权益与能源等关切；基辅与伙伴批评政治化拖延。摩尔多瓦同步受阻，凸显扩大进程中的一票否决张力。", "body_en": "Hungary Blocks Ukraine and Moldova EU Accession Steps.\n\nJust days after Ukraine passed a law protecting its Hungarian-speaking minority, Hungary halted the next phase of EU talks for both Ukraine and Moldova, leaving diplomats puzzled by the silence.\n\nAt a meeting of EU technical experts on October 20, Hungary objected to advancing the final two negotiating clusters on green agenda, sustainable connectivity, resources, agriculture, and cohesion, while the other 26 member states supported the move.\n\nThis follows recent progress, including Ukraine's minority protections law on October 12 and a meeting between Prime Minister Péter Magyar and President Volodymyr Zelenskyy to reset ties, which allowed earlier clusters to open. The block revives questions about Hungary's stance on EU enlargement, as unanimity is required, and observers note frustration over the unexplained decision despite outreach efforts.", "body_zh": "匈牙利阻断乌克兰与摩尔多瓦入盟下一阶段谈判。\n\n乌克兰刚通过保护匈牙利语少数族裔相关法律数日，匈牙利却叫停乌、摩入盟谈判下一阶段，令各方错愕。\n\n10 月 20 日欧盟技术专家会上，匈牙利反对推进绿色议程、可持续互联、资源、农业与凝聚等最后两个谈判集群，其余 26 国支持。此前入盟程序本有进展。\n\n布达佩斯强调少数族裔权益与能源等关切；基辅与伙伴批评政治化拖延。摩尔多瓦同步受阻，凸显扩大进程中的一票否决张力。", "url": "https://x.com/i/trending/2112592169139855608", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:18:54.000Z"}, {"id": "2112713662490194099", "domain": "国际", "title_en": "Debate Erupts Over Ukraine's History and US Role in Conflict", "title_zh": "乌克兰历史定位与美国角色再引激辩", "hook_en": "A bold claim that Ukraine is historically Russian land and should be returned to end US involvement hit a nerve, drawing sharp replies rooted in Kyiv's ancient legacy.", "hook_zh": "有人声称乌克兰历来属俄、应交即可结束美方卷入，随即遭到以基辅罗斯传统为依据的反击。", "summary_en": "User @provemewrong411 argued handing Ukraine back to Russia would let America focus on domestic issues instead of foreign aid. Critics countered by noting Kyivan Rus originated in modern Ukraine's territory as the first East Slavic state, shared by Ukraine, Russia, and Belarus, with its capital in Kyiv during its 11th-century peak. Others referenced the 1994 Budapest Memorandum, where Ukraine gave up its nuclear arsenal for sovereignty pledges from the US, UK, and Russia—pledges Russia later violated. The exchange highlights clashing historical views fueling debates on US policy, alliances, and priorities amid reduced aid post-administration change.", "summary_zh": "有用户主张把乌克兰“还给”俄罗斯以便美国聚焦内政。批评者指出，基辅罗斯起源于今乌克兰一带，是东斯拉夫最早国家形态之一，鼎盛时都城在基辅，历史为乌、俄、白俄所共享。也有人援引 1994 年布达佩斯备忘录：乌克兰放弃核武器换取美、英、俄等对主权的保障，而俄方后来违约。争论折射援助政策与历史叙事的撕裂。", "body_en": "Debate Erupts Over Ukraine's History and US Role in Conflict.\n\nA bold claim that Ukraine is historically Russian land and should be returned to end US involvement hit a nerve, drawing sharp replies rooted in Kyiv's ancient legacy.\n\nUser @provemewrong411 argued handing Ukraine back to Russia would let America focus on domestic issues instead of foreign aid. Critics countered by noting Kyivan Rus originated in modern Ukraine's territory as the first East Slavic state, shared by Ukraine, Russia, and Belarus, with its capital in Kyiv during its 11th-century peak.\n\nOthers referenced the 1994 Budapest Memorandum, where Ukraine gave up its nuclear arsenal for sovereignty pledges from the US, UK, and Russia—pledges Russia later violated. The exchange highlights clashing historical views fueling debates on US policy, alliances, and priorities amid reduced aid post-administration change.", "body_zh": "乌克兰历史定位与美国角色再引激辩。\n\n有人声称乌克兰历来属俄、应交即可结束美方卷入，随即遭到以基辅罗斯传统为依据的反击。\n\n有用户主张把乌克兰“还给”俄罗斯以便美国聚焦内政。批评者指出，基辅罗斯起源于今乌克兰一带，是东斯拉夫最早国家形态之一，鼎盛时都城在基辅，历史为乌、俄、白俄所共享。\n\n也有人援引 1994 年布达佩斯备忘录：乌克兰放弃核武器换取美、英、俄等对主权的保障，而俄方后来违约。争论折射援助政策与历史叙事的撕裂。", "url": "https://x.com/i/trending/2112713662490194099", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T01:18:02.000Z"}, {"id": "2112501506905710732", "domain": "国际", "title_en": "UK and Poland Rebuke US Defense Secretary Over Afghanistan Ally Claims", "title_zh": "英波就美防长阿富汗盟友言论提出严正回应", "hook_en": "Pete Hegseth recalled seeing dozens of flags in Kabul but claimed only a handful of nations truly fought alongside Americans. British and Polish leaders quickly pushed back, honoring the lives lost by their troops.", "hook_zh": "赫格塞思称喀布尔可见多国旗帜，但真正并肩作战者寥寥；英国与波兰领导人迅速反驳并缅怀本国阵亡者。", "summary_en": "During a speech at the University of Tennessee, US Defense Secretary Pete Hegseth said few NATO allies contributed meaningfully to combat in Afghanistan, joking that the ISAF patch meant 'I Saw Americans Fighting.' Downing Street responded firmly, noting 457 British deaths—the second-highest after the US—and thousands of families who sacrificed for collective security after the 2001 attacks. Poland's Foreign Minister Radosław Sikorski highlighted 44 Polish soldiers killed in Ghazni province, while records show over 1,100 non-US coalition deaths overall, underscoring the broad sacrifices in the 20-year conflict.", "summary_zh": "美防长 Pete Hegseth 在田纳西大学演讲称，鲜有北约盟友在阿富汗真正投入战斗，并调侃 ISAF 补丁意为“我看见美国人在打仗”。唐宁街强调英军阵亡 457 人，仅次于美国；波兰外长指出 44 名波军在加兹尼省牺牲。数据显示非美联军阵亡逾 1100 人。言论引发对盟友牺牲被低估的强烈不满。", "body_en": "UK and Poland Rebuke US Defense Secretary Over Afghanistan Ally Claims.\n\nPete Hegseth recalled seeing dozens of flags in Kabul but claimed only a handful of nations truly fought alongside Americans. British and Polish leaders quickly pushed back, honoring the lives lost by their troops.\n\nDuring a speech at the University of Tennessee, US Defense Secretary Pete Hegseth said few NATO allies contributed meaningfully to combat in Afghanistan, joking that the ISAF patch meant 'I Saw Americans Fighting.' Downing Street responded firmly, noting 457 British deaths—the second-highest after the US—and thousands of families who sacrificed for collective security after the 2001 attacks. Poland's Foreign Minister Radosław Sikorski highlighted 44 Polish soldiers killed in Ghazni province, while records show over 1,100 non-US coalition deaths overall, underscoring the broad sacrifices in the 20-year conflict.", "body_zh": "英波就美防长阿富汗盟友言论提出严正回应。\n\n赫格塞思称喀布尔可见多国旗帜，但真正并肩作战者寥寥；英国与波兰领导人迅速反驳并缅怀本国阵亡者。\n\n美防长 Pete Hegseth 在田纳西大学演讲称，鲜有北约盟友在阿富汗真正投入战斗，并调侃 ISAF 补丁意为“我看见美国人在打仗”。唐宁街强调英军阵亡 457 人，仅次于美国；波兰外长指出 44 名波军在加兹尼省牺牲。\n\n数据显示非美联军阵亡逾 1100 人。言论引发对盟友牺牲被低估的强烈不满。", "url": "https://x.com/i/trending/2112501506905710732", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T14:10:22.000Z"}, {"id": "2112887415408832774", "domain": "国际", "title_en": "UAE's Lana Nusseibeh Enters Race for Next UN Secretary-General", "title_zh": "阿联酋外交官 Lana Nusseibeh 加入下任联合国秘书长角逐", "hook_en": "As the search for António Guterres' successor stalls, a seasoned UAE diplomat steps into the spotlight, bringing sharp divides in opinions.", "hook_zh": "古特雷斯继任人选僵持之际，资深阿联酋外交官进入视野，舆论褒贬不一。", "summary_en": "Lana Nusseibeh, UAE's former permanent representative to the UN and current minister of state, is set to join the contest to replace Guterres, whose term ends December 31, 2026. Supporters praise her Cambridge education, diplomatic experience, and leadership as the first woman in her prior UN role, while critics link her to UAE policies with harsh labels like anti-Palestinian. Recent Security Council polls show no frontrunner amid a deadlock, with Latin American candidates pushing back and veto powers potentially deciding the outcome through a required nine-vote recommendation without permanent-member blocks.", "summary_zh": "曾任阿联酋常驻联合国代表、现任国务部长的 Lana Nusseibeh 拟参选，接替任期至 2026 年 12 月 31 日的古特雷斯。支持者称赞其剑桥教育背景、外交资历及曾为该职位首位女性代表；批评者则将其与阿联酋政策挂钩。安理会近期非正式投票尚无领跑者，拉美人选亦在角力，最终需九票推荐且常任理事国不行使否决。", "body_en": "UAE's Lana Nusseibeh Enters Race for Next UN Secretary-General.\n\nAs the search for António Guterres' successor stalls, a seasoned UAE diplomat steps into the spotlight, bringing sharp divides in opinions.\n\nLana Nusseibeh, UAE's former permanent representative to the UN and current minister of state, is set to join the contest to replace Guterres, whose term ends December 31, 2026.\n\nSupporters praise her Cambridge education, diplomatic experience, and leadership as the first woman in her prior UN role, while critics link her to UAE policies with harsh labels like anti-Palestinian. Recent Security Council polls show no frontrunner amid a deadlock, with Latin American candidates pushing back and veto powers potentially deciding the outcome through a required nine-vote recommendation without permanent-member blocks.", "body_zh": "阿联酋外交官 Lana Nusseibeh 加入下任联合国秘书长角逐。\n\n古特雷斯继任人选僵持之际，资深阿联酋外交官进入视野，舆论褒贬不一。\n\n曾任阿联酋常驻联合国代表、现任国务部长的 Lana Nusseibeh 拟参选，接替任期至 2026 年 12 月 31 日的古特雷斯。\n\n支持者称赞其剑桥教育背景、外交资历及曾为该职位首位女性代表；批评者则将其与阿联酋政策挂钩。安理会近期非正式投票尚无领跑者，拉美人选亦在角力，最终需九票推荐且常任理事国不行使否决。", "url": "https://x.com/i/trending/2112887415408832774", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T12:48:51.000Z"}, {"id": "2112773061082767722", "domain": "国际", "title_en": "Putin Orders Escalation of Russian Sabotage in NATO Europe", "title_zh": "美情报称普京下令加大对北约欧洲的破坏行动", "hook_en": "A drone packed with explosives struck a Ukrainian cargo plane at Germany's Leipzig-Halle Airport in August, but mercifully failed to detonate amid a broader covert campaign.", "hook_zh": "今年 8 月一架装有爆炸物的无人机袭击德国莱比锡机场一架乌克兰货机但未起爆，被指属于更广泛隐蔽行动的一部分。", "summary_en": "U.S. intelligence reports that Vladimir Putin directly ordered a major increase in Russian sabotage operations across NATO countries in Europe, frustrated by stalled Ukraine talks and Kyiv's deep strikes. The Leipzig incident, traced to a GRU unit with explosives via Serbia, targeted military aid; a Kremlin backchannel later warned Germany of more attacks to come. Germany raised its military sabotage threat to 'significant' and considered NATO's Article 5 if casualties had mounted, while the campaign now hits suppliers, infrastructure, and shipping. Russia denies involvement as NATO weighs a response.", "summary_zh": "美方情报称，因乌克兰和谈停滞及基辅深远打击，普京直接下令显著加强对欧洲北约国家的破坏活动。莱比锡事件被指向经塞尔维亚运送爆炸物的俄军情报单位，目标涉及军援；克里姆林宫后据称通过后门警告德国还将有更多袭击。德国已将军事破坏威胁调至“显著”，并讨论若造成伤亡是否触及北约第五条。俄方否认，北约仍在评估应对。", "body_en": "Putin Orders Escalation of Russian Sabotage in NATO Europe.\n\nA drone packed with explosives struck a Ukrainian cargo plane at Germany's Leipzig-Halle Airport in August, but mercifully failed to detonate amid a broader covert campaign.\n\nU.S. intelligence reports that Vladimir Putin directly ordered a major increase in Russian sabotage operations across NATO countries in Europe, frustrated by stalled Ukraine talks and Kyiv's deep strikes.\n\nThe Leipzig incident, traced to a GRU unit with explosives via Serbia, targeted military aid; a Kremlin backchannel later warned Germany of more attacks to come. Germany raised its military sabotage threat to 'significant' and considered NATO's Article 5 if casualties had mounted, while the campaign now hits suppliers, infrastructure, and shipping. Russia denies involvement as NATO weighs a response.", "body_zh": "美情报称普京下令加大对北约欧洲的破坏行动。\n\n今年 8 月一架装有爆炸物的无人机袭击德国莱比锡机场一架乌克兰货机但未起爆，被指属于更广泛隐蔽行动的一部分。\n\n美方情报称，因乌克兰和谈停滞及基辅深远打击，普京直接下令显著加强对欧洲北约国家的破坏活动。莱比锡事件被指向经塞尔维亚运送爆炸物的俄军情报单位，目标涉及军援；克里姆林宫后据称通过后门警告德国还将有更多袭击。\n\n德国已将军事破坏威胁调至“显著”，并讨论若造成伤亡是否触及北约第五条。俄方否认，北约仍在评估应对。", "url": "https://x.com/i/trending/2112773061082767722", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T12:07:41.000Z"}, {"id": "2112588449140355241", "domain": "体育", "title_en": "LA Bar Group Hedges Dodgers Loss with $60K Bet, Doubles Money", "title_zh": "洛杉矶酒吧联盟赌道奇出局对冲，6 万美元翻倍", "hook_en": "When the Dodgers fell to the Brewers in the NLCS, a group of 25 bars near the stadium didn't sweat the empty seats—their clever $60,000 bet paid out $120,000 to cover the shortfall.", "hook_zh": "道奇在联盟冠军赛出局后，球场附近 25 家酒吧并不慌——他们在预测市场下的 6 万美元对冲赔出 12 万。", "summary_en": "The Los Angeles hospitality group bet on Kalshi that the Dodgers wouldn't reach the World Series, creating a perfect hedge against lost revenue from an early playoff exit. The wager doubled their money when the team lost, matching the extra business they expected from more games. This smart move highlights how prediction markets let businesses manage sports risks like custom insurance, with observers calling it 'pretty damn clever' and a win-win for crowd-dependent spots.", "summary_zh": "洛杉矶餐饮集团在 Kalshi 上下注道奇无法进世界系列赛，以对冲季后赛早早出局带来的客流损失。球队出局后赌注翻倍，约等于他们本指望多打几场多赚的营业额。观察者称这是预测市场充当“定制保险”的聪明案例，让依赖赛事人流的商家对冲体育风险。", "body_en": "LA Bar Group Hedges Dodgers Loss with $60K Bet, Doubles Money.\n\nWhen the Dodgers fell to the Brewers in the NLCS, a group of 25 bars near the stadium didn't sweat the empty seats—their clever $60,000 bet paid out $120,000 to cover the shortfall.\n\nThe Los Angeles hospitality group bet on Kalshi that the Dodgers wouldn't reach the World Series, creating a perfect hedge against lost revenue from an early playoff exit.\n\nThe wager doubled their money when the team lost, matching the extra business they expected from more games. This smart move highlights how prediction markets let businesses manage sports risks like custom insurance, with observers calling it 'pretty damn clever' and a win-win for crowd-dependent spots.", "body_zh": "洛杉矶酒吧联盟赌道奇出局对冲，6 万美元翻倍。\n\n道奇在联盟冠军赛出局后，球场附近 25 家酒吧并不慌——他们在预测市场下的 6 万美元对冲赔出 12 万。\n\n洛杉矶餐饮集团在 Kalshi 上下注道奇无法进世界系列赛，以对冲季后赛早早出局带来的客流损失。\n\n球队出局后赌注翻倍，约等于他们本指望多打几场多赚的营业额。观察者称这是预测市场充当“定制保险”的聪明案例，让依赖赛事人流的商家对冲体育风险。", "url": "https://x.com/i/trending/2112588449140355241", "category": "News", "topics": ["Baseball"], "updated_at": "2026-10-21T01:55:22.000Z"}, {"id": "2112637280108335380", "domain": "体育", "title_en": "NFL Umpire Larry Smith Tears Quadriceps in Rare Non-Contact Injury at Wembley", "title_zh": "NFL 裁判拉里·史密斯温布利湿草滑倒撕裂股四头肌", "hook_en": "Larry Smith slipped on wet grass between plays, stood briefly, then collapsed clutching his leg—a shocking moment that sidelined the umpire for good this season.", "hook_zh": "拉里·史密斯在死球间隙湿草上滑倒，短暂站起后又捂腿倒下——这一幕令他本赛季提前告别。", "summary_en": "During the Houston Texans-Jacksonville Jaguars game at Wembley Stadium, second-year NFL umpire Larry Smith tore his right quadriceps in a non-contact slip early in the first quarter. Trainers from both teams helped him off the field on a cart, and his crew finished with six officials while splitting his duties. A middle school principal from Kansas City, Kansas, in his full-time job, Smith won't return until 2027, prompting the NFL to seek a replacement like swing official Tab Slaughter or Ian Malepeai for referee Shawn Hochuli’s crew. Veteran line judge Carl Johnson knelt by his side, hat off in what looked like a prayer, as fans shared surprised laughs about refs joining the injury list.", "summary_zh": "休斯顿德州人队对阵杰克逊维尔美洲虎队的温布利比赛中，入行第二年的 NFL 裁判拉里·史密斯在第一节早段非对抗滑倒，右股四头肌撕裂。双方训练人员用球车将其抬离，执法组以六人完赛并分摊其职责。史密斯全职是堪萨斯城一名中学校长，预计要到 2027 年才能复出；联盟将为裁判肖恩·霍楚利组寻找替补，如轮换裁判 Tab Slaughter 或 Ian Malepeai。资深边线裁判卡尔·约翰逊跪其身旁、脱帽似在祈祷；球迷则半开玩笑「连裁判也进伤病名单了」。", "body_en": "NFL Umpire Larry Smith Tears Quadriceps in Rare Non-Contact Injury at Wembley.\n\nLarry Smith slipped on wet grass between plays, stood briefly, then collapsed clutching his leg—a shocking moment that sidelined the umpire for good this season.\n\nDuring the Houston Texans-Jacksonville Jaguars game at Wembley Stadium, second-year NFL umpire Larry Smith tore his right quadriceps in a non-contact slip early in the first quarter. Trainers from both teams helped him off the field on a cart, and his crew finished with six officials while splitting his duties.\n\nA middle school principal from Kansas City, Kansas, in his full-time job, Smith won't return until 2027, prompting the NFL to seek a replacement like swing official Tab Slaughter or Ian Malepeai for referee Shawn Hochuli’s crew. Veteran line judge Carl Johnson knelt by his side, hat off in what looked like a prayer, as fans shared surprised laughs about refs joining the injury list.", "body_zh": "NFL 裁判拉里·史密斯温布利湿草滑倒撕裂股四头肌。\n\n拉里·史密斯在死球间隙湿草上滑倒，短暂站起后又捂腿倒下——这一幕令他本赛季提前告别。\n\n休斯顿德州人队对阵杰克逊维尔美洲虎队的温布利比赛中，入行第二年的 NFL 裁判拉里·史密斯在第一节早段非对抗滑倒，右股四头肌撕裂。双方训练人员用球车将其抬离，执法组以六人完赛并分摊其职责。\n\n史密斯全职是堪萨斯城一名中学校长，预计要到 2027 年才能复出；联盟将为裁判肖恩·霍楚利组寻找替补，如轮换裁判 Tab Slaughter 或 Ian Malepeai。资深边线裁判卡尔·约翰逊跪其身旁、脱帽似在祈祷；球迷则半开玩笑「连裁判也进伤病名单了」。", "url": "https://x.com/i/trending/2112637280108335380", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-20T20:16:29.000Z"}, {"id": "2112363184577191956", "domain": "体育", "title_en": "NFL Pushes Ahead with First France Game Amid Paris Unrest", "title_zh": "巴黎动荡中 NFL 仍推进法国首场常规赛", "hook_en": "As riots rage in Paris over rising costs and public services, the NFL stands firm on its historic game at Stade de France. Steelers star T.J. Watt's wife posted a headline questioning the decision with 'Tell me how this one make sense???'.", "hook_zh": "巴黎因生活成本与公共服务爆发骚乱，NFL 仍坚持法兰西体育场历史性比赛。钢人球星 T.J. 瓦特妻子发帖质问「这怎么说得通」。", "summary_en": "The Pittsburgh Steelers and New Orleans Saints are set to play the NFL's first regular-season game in France on October 25 at Stade de France in Saint-Denis, despite violent protests that erupted October 17-18, leading to arrests, fires, and curfews. League officials, including Roger Goodell, call the unrest 'mostly peaceful' and have ramped up security with local police, national authorities, and the U.S. State Department, confirming no plans to postpone. The Saints have arrived, Steelers are en route, and executives like Peter O’Reilly stress safety as the top priority, even as some players' families voice concerns.", "summary_zh": "匹兹堡钢人与新奥尔良圣徒定于 10 月 25 日在圣但尼法兰西体育场进行 NFL 法国首场常规赛，尽管 10 月 17–18 日暴力抗议导致逮捕、纵火与宵禁。包括罗杰·古德尔在内的联盟官员称动荡「大体和平」，并与地方警察、国家当局及美国国务院加强安保，暂无延期计划。圣徒已抵达、钢人在途，高管强调安全优先，部分球员家属仍表担忧。", "body_en": "NFL Pushes Ahead with First France Game Amid Paris Unrest.\n\nAs riots rage in Paris over rising costs and public services, the NFL stands firm on its historic game at Stade de France. Steelers star T.J. Watt's wife posted a headline questioning the decision with 'Tell me how this one make sense???'.\n\nThe Pittsburgh Steelers and New Orleans Saints are set to play the NFL's first regular-season game in France on October 25 at Stade de France in Saint-Denis, despite violent protests that erupted October 17-18, leading to arrests, fires, and curfews. League officials, including Roger Goodell, call the unrest 'mostly peaceful' and have ramped up security with local police, national authorities, and the U.S.\n\nState Department, confirming no plans to postpone. The Saints have arrived, Steelers are en route, and executives like Peter O’Reilly stress safety as the top priority, even as some players' families voice concerns.", "body_zh": "巴黎动荡中 NFL 仍推进法国首场常规赛。\n\n巴黎因生活成本与公共服务爆发骚乱，NFL 仍坚持法兰西体育场历史性比赛。钢人球星 T.J. 瓦特妻子发帖质问「这怎么说得通」。\n\n匹兹堡钢人与新奥尔良圣徒定于 10 月 25 日在圣但尼法兰西体育场进行 NFL 法国首场常规赛，尽管 10 月 17–18 日暴力抗议导致逮捕、纵火与宵禁。包括罗杰·古德尔在内的联盟官员称动荡「大体和平」，并与地方警察、国家当局及美国国务院加强安保，暂无延期计划。\n\n圣徒已抵达、钢人在途，高管强调安全优先，部分球员家属仍表担忧。", "url": "https://x.com/i/trending/2112363184577191956", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-21T05:34:34.000Z"}, {"id": "2112527510105919970", "domain": "体育", "title_en": "Ex-NFL Player Accuses Refs of Rigging Games for Chiefs", "title_zh": "前 NFL 球员指控裁判偏袒酋长，争议再起", "hook_en": "Breiden Fehoko leaned into the mic on a podcast and called out what he saw as late-game favoritism for the Chiefs. His words tapped into frustrations many rival fans have felt for years.", "hook_zh": "Breiden Fehoko 在播客上称第四节有「幽灵判罚」帮堪萨斯城赢球，戳中多年对手球迷的怒点。", "summary_en": "Former Chargers defensive tackle Breiden Fehoko claimed on Jason Whitlock's podcast that officials give Kansas City 'ghost calls' in the fourth quarter to swing tight games. He pointed to a pattern where penalties bail out the Chiefs when trailing, calling it a 'mockery,' and challenged refs to stay impartial in the playoffs. Critics noted his limited experience—just one game against Kansas City and 19 career appearances—while fans referenced moments like the 2022 AFC Championship as supposed proof. The debate highlights ongoing gripes about NFL officiating but lacks hard evidence of rigging.", "summary_zh": "前闪电防守截锋 Fehoko 在 Jason Whitlock 播客上声称，官员会在第四节用「幽灵判罚」扭转胶着比赛，落后时点球「救」酋长，称之为「嘲弄」，并要求季后赛保持公正。批评指出他仅打过一场对阵堪萨斯城、生涯出场约 19 次；球迷则搬出 2022 年 AFC 冠军赛等片段作「证据」。争论凸显对 NFL 执法的积怨，但缺乏操纵确证。", "body_en": "Ex-NFL Player Accuses Refs of Rigging Games for Chiefs.\n\nBreiden Fehoko leaned into the mic on a podcast and called out what he saw as late-game favoritism for the Chiefs. His words tapped into frustrations many rival fans have felt for years.\n\nFormer Chargers defensive tackle Breiden Fehoko claimed on Jason Whitlock's podcast that officials give Kansas City 'ghost calls' in the fourth quarter to swing tight games. He pointed to a pattern where penalties bail out the Chiefs when trailing, calling it a 'mockery,' and challenged refs to stay impartial in the playoffs.\n\nCritics noted his limited experience—just one game against Kansas City and 19 career appearances—while fans referenced moments like the 2022 AFC Championship as supposed proof. The debate highlights ongoing gripes about NFL officiating but lacks hard evidence of rigging.", "body_zh": "前 NFL 球员指控裁判偏袒酋长，争议再起。\n\nBreiden Fehoko 在播客上称第四节有「幽灵判罚」帮堪萨斯城赢球，戳中多年对手球迷的怒点。\n\n前闪电防守截锋 Fehoko 在 Jason Whitlock 播客上声称，官员会在第四节用「幽灵判罚」扭转胶着比赛，落后时点球「救」酋长，称之为「嘲弄」，并要求季后赛保持公正。\n\n批评指出他仅打过一场对阵堪萨斯城、生涯出场约 19 次；球迷则搬出 2022 年 AFC 冠军赛等片段作「证据」。争论凸显对 NFL 执法的积怨，但缺乏操纵确证。", "url": "https://x.com/i/trending/2112527510105919970", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-21T02:52:40.000Z"}, {"id": "2112281281501528167", "domain": "体育", "title_en": "Kyrie Irving Doubts Playing into His Early 40s as NBA Evolves", "title_zh": "凯里·欧文质疑自己能否像勒布朗一样打到四十出头", "hook_en": "Kyrie Irving paused during media day to reflect on a league that's changed since his childhood dreams. At 34, he loves the game but sees modern pressures making a long career like LeBron's unlikely for him.", "hook_zh": "凯里·欧文在媒体日反思：联盟已非儿时梦想中的模样。34 岁的他仍爱篮球，但觉现代压力让勒布朗式超长生涯对己不太可能。", "summary_en": "The Mavericks guard shared honest thoughts after practice Monday, saying he can't envision suiting up at 42 or 43 amid social media, gambling, and a more 'robotic' NBA far from the one he fell in love with as a kid. Irving praised LeBron James, Stephen Curry, and Kevin Durant for their longevity while noting shifts like mental health talks and tipping meetings that weren't around when he entered as the 2011 No. 1 pick. Preparing for his 2026-27 return after missing last season with a torn ACL, he's focused on enjoying competition and personal growth as Dallas opens Wednesday against Houston.", "summary_zh": "这名独行侠后卫周一训练后坦诚，在社交媒体、博彩与更「机械」的 NBA 中，难以想象自己 42、43 岁还穿球衣——那与儿时爱上的篮球相去甚远。他称赞勒布朗、库里与杜兰特的长寿，同时提到心理健康讨论、赛前提示会等入行时（2011 年状元秀）尚不存在的变化。在因 ACL 撕裂缺席上赛季后，他备战 2026–27 回归，专注享受竞争与成长，达拉斯周三对休斯敦揭幕。", "body_en": "Kyrie Irving Doubts Playing into His Early 40s as NBA Evolves.\n\nKyrie Irving paused during media day to reflect on a league that's changed since his childhood dreams. At 34, he loves the game but sees modern pressures making a long career like LeBron's unlikely for him.\n\nThe Mavericks guard shared honest thoughts after practice Monday, saying he can't envision suiting up at 42 or 43 amid social media, gambling, and a more 'robotic' NBA far from the one he fell in love with as a kid. Irving praised LeBron James, Stephen Curry, and Kevin Durant for their longevity while noting shifts like mental health talks and tipping meetings that weren't around when he entered as the 2011 No.\n\n1 pick. Preparing for his 2026-27 return after missing last season with a torn ACL, he's focused on enjoying competition and personal growth as Dallas opens Wednesday against Houston.", "body_zh": "凯里·欧文质疑自己能否像勒布朗一样打到四十出头。\n\n凯里·欧文在媒体日反思：联盟已非儿时梦想中的模样。34 岁的他仍爱篮球，但觉现代压力让勒布朗式超长生涯对己不太可能。\n\n这名独行侠后卫周一训练后坦诚，在社交媒体、博彩与更「机械」的 NBA 中，难以想象自己 42、43 岁还穿球衣——那与儿时爱上的篮球相去甚远。他称赞勒布朗、库里与杜兰特的长寿，同时提到心理健康讨论、赛前提示会等入行时（2011 年状元秀）尚不存在的变化。\n\n在因 ACL 撕裂缺席上赛季后，他备战 2026–27 回归，专注享受竞争与成长，达拉斯周三对休斯敦揭幕。", "url": "https://x.com/i/trending/2112281281501528167", "category": "Sports", "topics": [], "updated_at": "2026-10-20T15:54:00.000Z"}, {"id": "2112804232634187907", "domain": "体育", "title_en": "NBA Season Tips Off with Thunder Victory and Fan Joy", "title_zh": "NBA 新季揭幕：雷霆取胜，球迷欢腾", "hook_en": "Fans lit up with pure excitement as the 2026-27 NBA season returned, comparing it to Christmas and loving the team rivalries packed with popcorn drama.", "hook_zh": "2026–27 赛季回归，球迷兴奋如过圣诞，津津乐道火药味十足的对档戏码。", "summary_en": "The season kicked off on October 20 with a tripleheader, highlighted by the Oklahoma City Thunder beating the San Antonio Spurs 116-104 in a Western Conference Finals rematch. Shai Gilgeous-Alexander scored 32 points to lead OKC, fueling the tension between teams with physical histories and stars like Chet Holmgren and Victor Wembanyama. Other games saw the Knicks drop their banner night to the 76ers, while the Pistons rallied past the Celtics. Supporters shared heartfelt posts calling it the best time of year, with real hate between teams making every matchup thrilling.", "summary_zh": "赛季 10 月 20 日以三场连赛揭幕，焦点之一是西决重演：俄克拉荷马城雷霆 116–104 击败圣安东尼奥马刺。谢伊·吉尔杰斯-亚历山大砍下 32 分领军，两队身体对抗史与霍姆格伦、文班亚马等球星令火药味十足。另场尼克斯主场横幅夜不敌 76 人，活塞逆转凯尔特人。球迷发帖称一年中最美好时光，真实「恨意」让每场都刺激。", "body_en": "NBA Season Tips Off with Thunder Victory and Fan Joy.\n\nFans lit up with pure excitement as the 2026-27 NBA season returned, comparing it to Christmas and loving the team rivalries packed with popcorn drama.\n\nThe season kicked off on October 20 with a tripleheader, highlighted by the Oklahoma City Thunder beating the San Antonio Spurs 116-104 in a Western Conference Finals rematch. Shai Gilgeous-Alexander scored 32 points to lead OKC, fueling the tension between teams with physical histories and stars like Chet Holmgren and Victor Wembanyama.\n\nOther games saw the Knicks drop their banner night to the 76ers, while the Pistons rallied past the Celtics. Supporters shared heartfelt posts calling it the best time of year, with real hate between teams making every matchup thrilling.", "body_zh": "NBA 新季揭幕：雷霆取胜，球迷欢腾。\n\n2026–27 赛季回归，球迷兴奋如过圣诞，津津乐道火药味十足的对档戏码。\n\n赛季 10 月 20 日以三场连赛揭幕，焦点之一是西决重演：俄克拉荷马城雷霆 116–104 击败圣安东尼奥马刺。谢伊·吉尔杰斯-亚历山大砍下 32 分领军，两队身体对抗史与霍姆格伦、文班亚马等球星令火药味十足。\n\n另场尼克斯主场横幅夜不敌 76 人，活塞逆转凯尔特人。球迷发帖称一年中最美好时光，真实「恨意」让每场都刺激。", "url": "https://x.com/i/trending/2112804232634187907", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T07:17:07.000Z"}, {"id": "2112801176995467757", "domain": "体育", "title_en": "Sixers Upset Knicks on Ring Night with LeBron and Brown Debuts", "title_zh": "76 人队揭幕战客场击败尼克斯，詹姆斯与布朗亮相", "hook_en": "LeBron James stepped onto Madison Square Garden's floor for his Sixers debut, and the team quickly turned a pre-game doubter's tweet into prime ammo for fans.", "hook_zh": "勒布朗·詹姆斯身披 76 人队服登陆麦迪逊广场花园，揭幕战即成粉丝话题。", "summary_en": "The Philadelphia 76ers kicked off the 2026-27 NBA season with a 106-100 road win over the defending champion New York Knicks, spoiling their ring night celebration. Tyrese Maxey led with 28 points in the second-half rally, while new additions LeBron James tallied 14 points, nine rebounds, and seven assists, and Jaylen Brown added 19 points, eight rebounds, and six assists alongside Joel Embiid and Maxey. Fans immediately called out a pre-game tweet dismissing the Sixers as non-contenders, though many noted it's just the first of 82 games and true tests lie ahead.", "summary_zh": "费城 76 人队以 106-100 客场击败卫冕冠军纽约尼克斯，扫了对方戒指之夜的兴。马克西砍下 28 分带领下半场逆转；新援詹姆斯得到 14 分 9 篮板 7 助攻，杰伦·布朗贡献 19 分 8 篮板 6 助攻，恩比德亦在阵中。赛前有人发帖否认 76 人争冠资格，赛后被粉丝翻出调侃；不过多数人提醒赛季漫长，真正考验还在后头。", "body_en": "Sixers Upset Knicks on Ring Night with LeBron and Brown Debuts.\n\nLeBron James stepped onto Madison Square Garden's floor for his Sixers debut, and the team quickly turned a pre-game doubter's tweet into prime ammo for fans.\n\nThe Philadelphia 76ers kicked off the 2026-27 NBA season with a 106-100 road win over the defending champion New York Knicks, spoiling their ring night celebration.\n\nTyrese Maxey led with 28 points in the second-half rally, while new additions LeBron James tallied 14 points, nine rebounds, and seven assists, and Jaylen Brown added 19 points, eight rebounds, and six assists alongside Joel Embiid and Maxey. Fans immediately called out a pre-game tweet dismissing the Sixers as non-contenders, though many noted it's just the first of 82 games and true tests lie ahead.", "body_zh": "76 人队揭幕战客场击败尼克斯，詹姆斯与布朗亮相。\n\n勒布朗·詹姆斯身披 76 人队服登陆麦迪逊广场花园，揭幕战即成粉丝话题。\n\n费城 76 人队以 106-100 客场击败卫冕冠军纽约尼克斯，扫了对方戒指之夜的兴。马克西砍下 28 分带领下半场逆转；新援詹姆斯得到 14 分 9 篮板 7 助攻，杰伦·布朗贡献 19 分 8 篮板 6 助攻，恩比德亦在阵中。\n\n赛前有人发帖否认 76 人争冠资格，赛后被粉丝翻出调侃；不过多数人提醒赛季漫长，真正考验还在后头。", "url": "https://x.com/i/trending/2112801176995467757", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T07:06:29.000Z"}, {"id": "2112718297158332458", "domain": "体育", "title_en": "Pistons Upset Celtics in NBA's Rare Afternoon Opener", "title_zh": "活塞下午赛爆冷击败凯尔特人，NBA 试水日间开赛", "hook_en": "On a Tuesday afternoon, the Detroit Pistons stunned the Boston Celtics 121-113 in the NBA's bold 3 p.m. tip-off experiment. Fans lit up with cheers and questions about daytime hoops during work hours.", "hook_zh": "底特律活塞 121–113 击败波士顿凯尔特人，NBA 罕见的下午 3 点揭幕战引发热议。", "summary_en": "The league kicked off its 2026-27 season with a tripleheader on NBC and Peacock, starting with Detroit's win over Boston to dodge overlap with the Knicks' banner ceremony in New York. Officials pitched the early slot as a test to mimic MLB's big opening days and catch European prime time viewers. While some fans loved the fresh vibe and called for more weekday matinees, others puzzled over the timing and griped about games often starting late anyway. Detroit grabbed its first opening-night win in years, spotlighting Boston's new-look team with Paul George.", "summary_zh": "2026–27 赛季在 NBC 与 Peacock 以三场连播揭幕，活塞战胜凯尔特人，以避免与尼克斯横幅仪式撞车。联盟称早场旨在对标大联盟开幕氛围并覆盖欧洲黄金时段。部分球迷呼吁更多工作日日场，也有人质疑时机。活塞取得多年来首场揭幕战胜利，凯尔特人新阵容（含保罗·乔治）亦受关注。", "body_en": "Pistons Upset Celtics in NBA's Rare Afternoon Opener.\n\nOn a Tuesday afternoon, the Detroit Pistons stunned the Boston Celtics 121-113 in the NBA's bold 3 p.m. tip-off experiment. Fans lit up with cheers and questions about daytime hoops during work hours.\n\nThe league kicked off its 2026-27 season with a tripleheader on NBC and Peacock, starting with Detroit's win over Boston to dodge overlap with the Knicks' banner ceremony in New York. Officials pitched the early slot as a test to mimic MLB's big opening days and catch European prime time viewers.\n\nWhile some fans loved the fresh vibe and called for more weekday matinees, others puzzled over the timing and griped about games often starting late anyway. Detroit grabbed its first opening-night win in years, spotlighting Boston's new-look team with Paul George.", "body_zh": "活塞下午赛爆冷击败凯尔特人，NBA 试水日间开赛。\n\n底特律活塞 121–113 击败波士顿凯尔特人，NBA 罕见的下午 3 点揭幕战引发热议。\n\n2026–27 赛季在 NBC 与 Peacock 以三场连播揭幕，活塞战胜凯尔特人，以避免与尼克斯横幅仪式撞车。联盟称早场旨在对标大联盟开幕氛围并覆盖欧洲黄金时段。\n\n部分球迷呼吁更多工作日日场，也有人质疑时机。活塞取得多年来首场揭幕战胜利，凯尔特人新阵容（含保罗·乔治）亦受关注。", "url": "https://x.com/i/trending/2112718297158332458", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T01:36:46.000Z"}, {"id": "2112355020591046930", "domain": "体育", "title_en": "WNBA Faces Backlash Over Anthem Absences and Eligibility Stance", "title_zh": "WNBA 因国歌缺席与参赛资格表态遭遇反弹", "hook_en": "Players from the Atlanta Dream and Golden State Valkyries walked off the court before the national anthem in the Finals' opening games, prompting quick backlash from fans and commentators.", "hook_zh": "总决赛开场，亚特兰大梦想与金州女武神部分球员在国歌前离场，引发球迷与评论员批评。", "summary_en": "The absences followed long-standing pregame routines for both teams, with the WNBA having suspended stricter anthem protocols years ago, yet critics like Sage Steele called it ignorant and disrespectful amid the league's lowest-ever Game 1 viewership. Tensions rose when Commissioner Cathy Engelbert told Congress that former NBA players Enes Kanter Freedom and Royce White are ineligible as 'both men,' without defining 'women' as requested. Players now earn record salaries—up to $1.4 million maximum—while some label them entitled for skipping the anthem despite league rules calling for a dignified posture, leaving fans divided on whether it's routine or a snub.", "summary_zh": "两队称沿用多年来的赛前惯例，联盟亦早已放宽国歌纪律；但在总决赛第一场收视创新低背景下，有评论指责其“无知、不敬”。专员 Cathy Engelbert 在国会称前 NBA 球员 Enes Kanter Freedom 与 Royce White“都是男性”故无资格，却未按要求定义“女性”，争议升温。球员顶薪可达约 140 万美元，球迷对“缺席国歌是否失礼”意见分裂。", "body_en": "WNBA Faces Backlash Over Anthem Absences and Eligibility Stance.\n\nPlayers from the Atlanta Dream and Golden State Valkyries walked off the court before the national anthem in the Finals' opening games, prompting quick backlash from fans and commentators.\n\nThe absences followed long-standing pregame routines for both teams, with the WNBA having suspended stricter anthem protocols years ago, yet critics like Sage Steele called it ignorant and disrespectful amid the league's lowest-ever Game 1 viewership.\n\nTensions rose when Commissioner Cathy Engelbert told Congress that former NBA players Enes Kanter Freedom and Royce White are ineligible as 'both men,' without defining 'women' as requested. Players now earn record salaries—up to $1.4 million maximum—while some label them entitled for skipping the anthem despite league rules calling for a dignified posture, leaving fans divided on whether it's routine or a snub.", "body_zh": "WNBA 因国歌缺席与参赛资格表态遭遇反弹。\n\n总决赛开场，亚特兰大梦想与金州女武神部分球员在国歌前离场，引发球迷与评论员批评。\n\n两队称沿用多年来的赛前惯例，联盟亦早已放宽国歌纪律；但在总决赛第一场收视创新低背景下，有评论指责其“无知、不敬”。\n\n专员 Cathy Engelbert 在国会称前 NBA 球员 Enes Kanter Freedom 与 Royce White“都是男性”故无资格，却未按要求定义“女性”，争议升温。球员顶薪可达约 140 万美元，球迷对“缺席国歌是否失礼”意见分裂。", "url": "https://x.com/i/trending/2112355020591046930", "category": "Sports", "topics": ["WNBA"], "updated_at": "2026-10-21T11:50:20.000Z"}, {"id": "2112889351361139036", "domain": "体育", "title_en": "EA Sports FC 27 FUT Gallery Adds MLS, NWSL, and Saudi League Sets", "title_zh": "EA FC 27 FUT 画廊将加入 MLS、NWSL 与沙特联主题套装", "hook_en": "Screenshots of upcoming MLS, NWSL, and Saudi League sets in the FUT Gallery have collectors eyeing their clubs with fresh excitement.", "hook_zh": "FUT 画廊即将上线 MLS、NWSL 与沙特联主题套装截图流出，收藏玩家开始盘算俱乐部阵容。", "summary_en": "Fans spotted new themed sets coming soon to the FUT Gallery in EA Sports FC 27, covering Major League Soccer, the National Women’s Soccer League, and the ROSHN Saudi League. These additions let players collect player items from the leagues to raise their overall Gallery Level and grab rewards like customizations and tokens—even past items in a player's history count toward the sets. Traders are planning moves, like completing MLS Future Stars picks now, while wondering if old packs will auto-contribute and how prices might shift. The periodic updates keep the pace relaxed, building toward milestones like Level 15 without rush.", "summary_zh": "玩家发现《EA Sports FC 27》FUT 画廊将新增北美男足、女足与沙特联主题套装。收集相应球员卡可提升画廊等级并兑换装扮、代币等奖励，历史拥有物品也计入。交易者已在规划，例如先完成 MLS 未来之星挑卡，并讨论旧包是否自动计入及价格波动。更新节奏偏缓，向更高等级推进不必赶工。", "body_en": "EA Sports FC 27 FUT Gallery Adds MLS, NWSL, and Saudi League Sets.\n\nScreenshots of upcoming MLS, NWSL, and Saudi League sets in the FUT Gallery have collectors eyeing their clubs with fresh excitement.\n\nFans spotted new themed sets coming soon to the FUT Gallery in EA Sports FC 27, covering Major League Soccer, the National Women’s Soccer League, and the ROSHN Saudi League. These additions let players collect player items from the leagues to raise their overall Gallery Level and grab rewards like customizations and tokens—even past items in a player's history count toward the sets.\n\nTraders are planning moves, like completing MLS Future Stars picks now, while wondering if old packs will auto-contribute and how prices might shift. The periodic updates keep the pace relaxed, building toward milestones like Level 15 without rush.", "body_zh": "EA FC 27 FUT 画廊将加入 MLS、NWSL 与沙特联主题套装。\n\nFUT 画廊即将上线 MLS、NWSL 与沙特联主题套装截图流出，收藏玩家开始盘算俱乐部阵容。\n\n玩家发现《EA Sports FC 27》FUT 画廊将新增北美男足、女足与沙特联主题套装。收集相应球员卡可提升画廊等级并兑换装扮、代币等奖励，历史拥有物品也计入。\n\n交易者已在规划，例如先完成 MLS 未来之星挑卡，并讨论旧包是否自动计入及价格波动。更新节奏偏缓，向更高等级推进不必赶工。", "url": "https://x.com/i/trending/2112889351361139036", "category": "Sports", "topics": ["Soccer"], "updated_at": "2026-10-21T12:58:51.000Z"}, {"id": "2112334183800676737", "domain": "体育", "title_en": "European Clubs Finalize Champions League Matchday 3 Preparations", "title_zh": "欧冠第三轮：各大俱乐部完成赛前备战", "hook_en": "FC Barcelona touched down in Paris amid fog delays, then hit the Parc des Princes pitch with a simple 'Focus.' message, gearing up for their big clash with PSG.", "hook_zh": "巴萨因大雾延误后飞抵巴黎，在王子公园草坪留下一句“专注”，备战对阵巴黎圣日耳曼。", "summary_en": "Barcelona arrived on October 19 for the October 20 showdown against PSG, completing recovery and training sessions after a delayed flight, with coach Hansi Flick and Pedri set for a press conference. Liverpool signaled 'Turning attentions to tomorrow night,' Manchester City posted 'Putting in the work' ahead of AEK Athens, and Real Madrid featured Vinicius Jr. in a motivational update. Across the continent, teams like Aston Villa and Manchester United huddled in training kits, emphasizing recovery and tactics as high-stakes Matchday 3 games, including Liverpool vs. Villarreal, loomed.", "summary_zh": "巴萨 10 月 19 日抵达，完成恢复与训练，主帅弗里克与佩德里将出席发布会，20 日对阵巴黎。利物浦称“注意力转向明晚”，曼城晒出对阵 AEK 雅典前的训练，皇马则用维尼修斯海报鼓劲。维拉、曼联等也在备战。欧冠第三轮还包括利物浦对黄潜等焦点战，各队强调恢复与战术执行。", "body_en": "European Clubs Finalize Champions League Matchday 3 Preparations.\n\nFC Barcelona touched down in Paris amid fog delays, then hit the Parc des Princes pitch with a simple 'Focus.' message, gearing up for their big clash with PSG.\n\nBarcelona arrived on October 19 for the October 20 showdown against PSG, completing recovery and training sessions after a delayed flight, with coach Hansi Flick and Pedri set for a press conference. Liverpool signaled 'Turning attentions to tomorrow night,' Manchester City posted 'Putting in the work' ahead of AEK Athens, and Real Madrid featured Vinicius Jr.\n\nin a motivational update. Across the continent, teams like Aston Villa and Manchester United huddled in training kits, emphasizing recovery and tactics as high-stakes Matchday 3 games, including Liverpool vs. Villarreal, loomed.", "body_zh": "欧冠第三轮：各大俱乐部完成赛前备战。\n\n巴萨因大雾延误后飞抵巴黎，在王子公园草坪留下一句“专注”，备战对阵巴黎圣日耳曼。\n\n巴萨 10 月 19 日抵达，完成恢复与训练，主帅弗里克与佩德里将出席发布会，20 日对阵巴黎。利物浦称“注意力转向明晚”，曼城晒出对阵 AEK 雅典前的训练，皇马则用维尼修斯海报鼓劲。\n\n维拉、曼联等也在备战。欧冠第三轮还包括利物浦对黄潜等焦点战，各队强调恢复与战术执行。", "url": "https://x.com/i/trending/2112334183800676737", "category": "Sports", "topics": ["Soccer"], "updated_at": "2026-10-20T03:49:32.000Z"}, {"id": "2112326602743050735", "domain": "体育", "title_en": "MLB Fans Debate Salary Cap as Small-Market Teams Reach World Series", "title_zh": "两支小市场球队进世界大赛，MLB 薪资帽争议再起", "hook_en": "The Milwaukee Brewers swept the Dodgers in the NLCS, sending two low-spending teams to the World Series and fueling fresh talk about whether MLB needs a salary cap.", "hook_zh": "酿酒人横扫道奇进世界大赛，两支开支靠后的球队会师，引爆“职棒是否该设硬顶”的讨论。", "summary_en": "Brewers, with the 19th-ranked payroll, beat the high-spending Dodgers in four games, drawing 7.53 million viewers—the best LCS audience since 2015—and now face the Rays for a first-time champion. Owners propose a $245.3 million hard cap and $171.2 million floor starting 2027 to boost balance, but players reject it as a wage suppressor. Small-market fans like Pirates supporters cheer the idea to limit talent hoarding, while critics say location and culture still sway stars, and Brewers' run proves smart spending works amid wide payroll gaps like the Dodgers' $433 million projection.", "summary_zh": "薪资排名约第 19 的酿酒人四场淘汰高薪道奇，联盟冠军赛收视约 753 万，为 2015 年来最佳，并将对阵光芒争夺两队队史首冠。资方提议 2027 年起设约 2.453 亿美元硬顶与 1.712 亿地板以促平衡，球员工会反对，认为压制工资。小市场球迷欢迎限制囤积球星；批评者称地理位置与文化仍影响自由球员，酿酒人证明精明花钱也能赢。", "body_en": "MLB Fans Debate Salary Cap as Small-Market Teams Reach World Series.\n\nThe Milwaukee Brewers swept the Dodgers in the NLCS, sending two low-spending teams to the World Series and fueling fresh talk about whether MLB needs a salary cap.\n\nBrewers, with the 19th-ranked payroll, beat the high-spending Dodgers in four games, drawing 7.53 million viewers—the best LCS audience since 2015—and now face the Rays for a first-time champion.\n\nOwners propose a $245.3 million hard cap and $171.2 million floor starting 2027 to boost balance, but players reject it as a wage suppressor. Small-market fans like Pirates supporters cheer the idea to limit talent hoarding, while critics say location and culture still sway stars, and Brewers' run proves smart spending works amid wide payroll gaps like the Dodgers' $433 million projection.", "body_zh": "两支小市场球队进世界大赛，MLB 薪资帽争议再起。\n\n酿酒人横扫道奇进世界大赛，两支开支靠后的球队会师，引爆“职棒是否该设硬顶”的讨论。\n\n薪资排名约第 19 的酿酒人四场淘汰高薪道奇，联盟冠军赛收视约 753 万，为 2015 年来最佳，并将对阵光芒争夺两队队史首冠。\n\n资方提议 2027 年起设约 2.453 亿美元硬顶与 1.712 亿地板以促平衡，球员工会反对，认为压制工资。小市场球迷欢迎限制囤积球星；批评者称地理位置与文化仍影响自由球员，酿酒人证明精明花钱也能赢。", "url": "https://x.com/i/trending/2112326602743050735", "category": "Sports", "topics": ["MLB"], "updated_at": "2026-10-21T05:20:54.000Z"}, {"id": "2112780082767130940", "domain": "体育", "title_en": "Caminero's Homer and Trot Send Rays to First World Series", "title_zh": "卡米内罗全垒打助光芒队史第三次进世界大赛", "hook_en": "Junior Caminero crushed a two-run homer off the foul pole, then took a 38.66-second trot, beating his chest and pointing to ex-teammate Randy Arozarena amid 40,000 roaring fans.", "hook_zh": "小将卡米内罗打出两分炮打中杆，再花约 38.66 秒绕垒庆祝，胸部击打并指向旧队友阿罗萨雷纳。", "summary_en": "The 23-year-old Rays third baseman's seventh-inning blast off Guardians closer Cade Smith clinched a 7-3 win in ALCS Game 6, marking his first playoff homer and the franchise's third pennant. His drawn-out celebration drew mixed reactions—some called it classless, while others celebrated the joy for a young star and a hurricane-hit community still rebuilding after storms Helene and Milton tore the Tropicana Field roof. Now the low-payroll Rays face the Milwaukee Brewers in the World Series starting Friday, both chasing their first title through smart scouting and development.", "summary_zh": "23 岁三垒手在美联冠军赛第六场七局从守护者终结者 Cade Smith 手上轰出季后赛首轰，光芒 7–3 取胜，拿下队史第三座联盟冠军。超长庆祝引来“缺乏风度”与“年轻人该尽兴”的两极评价；对饱受飓风损毁球场顶棚之苦的社区而言，晋级也被视为振奋。低薪光芒将对阵酿酒人，争夺双方首冠。", "body_en": "Caminero's Homer and Trot Send Rays to First World Series.\n\nJunior Caminero crushed a two-run homer off the foul pole, then took a 38.66-second trot, beating his chest and pointing to ex-teammate Randy Arozarena amid 40,000 roaring fans.\n\nThe 23-year-old Rays third baseman's seventh-inning blast off Guardians closer Cade Smith clinched a 7-3 win in ALCS Game 6, marking his first playoff homer and the franchise's third pennant.\n\nHis drawn-out celebration drew mixed reactions—some called it classless, while others celebrated the joy for a young star and a hurricane-hit community still rebuilding after storms Helene and Milton tore the Tropicana Field roof. Now the low-payroll Rays face the Milwaukee Brewers in the World Series starting Friday, both chasing their first title through smart scouting and development.", "body_zh": "卡米内罗全垒打助光芒队史第三次进世界大赛。\n\n小将卡米内罗打出两分炮打中杆，再花约 38.66 秒绕垒庆祝，胸部击打并指向旧队友阿罗萨雷纳。\n\n23 岁三垒手在美联冠军赛第六场七局从守护者终结者 Cade Smith 手上轰出季后赛首轰，光芒 7–3 取胜，拿下队史第三座联盟冠军。\n\n超长庆祝引来“缺乏风度”与“年轻人该尽兴”的两极评价；对饱受飓风损毁球场顶棚之苦的社区而言，晋级也被视为振奋。低薪光芒将对阵酿酒人，争夺双方首冠。", "url": "https://x.com/i/trending/2112780082767130940", "category": "Sports", "topics": ["Baseball"], "updated_at": "2026-10-21T13:12:22.000Z"}, {"id": "2112826877455053262", "domain": "娱乐", "title_en": "India Adds Three Sites to UNESCO World Heritage Tentative List", "title_zh": "印度三处遗址列入联合国教科文组织世界遗产预备名录", "hook_en": "From bubbling mud volcanoes in the Andamans to ancient temples along the Mahanadi River, three Indian treasures now stand closer to global recognition.", "hook_zh": "从安达曼泥火山到默哈讷迪河畔古庙，三处印度遗产向全球认可又近一步。", "summary_en": "India's Permanent Delegation to UNESCO announced on October 20, 2026, the addition of the Karst-mud-volcano Complex of Baratang and Andaman Subduction Volcanoes in the Andaman and Nicobar Islands, plus the Sirpur Cultural and Archaeological Landscape in Chhattisgarh. These sites highlight unique geology like active volcanoes and limestone caves, alongside historic temples reflecting Hindu, Buddhist, and Jain heritage with evidence of multi-faith harmony. Union Minister Gajendra Singh Shekhawat praised Sirpur for its traditions in art, architecture, spirituality, and learning, as India builds on its 45 inscribed World Heritage Sites.", "summary_zh": "印度常驻教科文组织代表团 2026 年 10 月 20 日宣布，将巴拉唐喀斯特—泥火山综合体与安达曼俯冲火山，以及恰蒂斯加尔邦西尔普尔文化考古景观列入预备名录。前者突出活火山与石灰岩洞穴等地质特色，后者涵盖印度教、佛教与耆那教古庙及多信仰共存证据。联邦部长 Gajendra Singh Shekhawat 称赞西尔普尔在艺术、建筑、精神与学问上的传统；印度已有 45 处列入世界遗产。", "body_en": "India Adds Three Sites to UNESCO World Heritage Tentative List.\n\nFrom bubbling mud volcanoes in the Andamans to ancient temples along the Mahanadi River, three Indian treasures now stand closer to global recognition.\n\nIndia's Permanent Delegation to UNESCO announced on October 20, 2026, the addition of the Karst-mud-volcano Complex of Baratang and Andaman Subduction Volcanoes in the Andaman and Nicobar Islands, plus the Sirpur Cultural and Archaeological Landscape in Chhattisgarh.\n\nThese sites highlight unique geology like active volcanoes and limestone caves, alongside historic temples reflecting Hindu, Buddhist, and Jain heritage with evidence of multi-faith harmony. Union Minister Gajendra Singh Shekhawat praised Sirpur for its traditions in art, architecture, spirituality, and learning, as India builds on its 45 inscribed World Heritage Sites.", "body_zh": "印度三处遗址列入联合国教科文组织世界遗产预备名录。\n\n从安达曼泥火山到默哈讷迪河畔古庙，三处印度遗产向全球认可又近一步。\n\n印度常驻教科文组织代表团 2026 年 10 月 20 日宣布，将巴拉唐喀斯特—泥火山综合体与安达曼俯冲火山，以及恰蒂斯加尔邦西尔普尔文化考古景观列入预备名录。\n\n前者突出活火山与石灰岩洞穴等地质特色，后者涵盖印度教、佛教与耆那教古庙及多信仰共存证据。联邦部长 Gajendra Singh Shekhawat 称赞西尔普尔在艺术、建筑、精神与学问上的传统；印度已有 45 处列入世界遗产。", "url": "https://x.com/i/trending/2112826877455053262", "category": "News", "topics": ["Travel"], "updated_at": "2026-10-21T11:43:52.000Z"}, {"id": "2112533925117460907", "domain": "娱乐", "title_en": "BBC to Close BBC Three, BBC Scotland and Radio 4 Extra in 2027", "title_zh": "BBC 计划 2027 年关闭 BBC Three、苏格兰台与 Radio 4 Extra 线性频道", "hook_en": "The BBC faces tough financial calls, shutting down three linear channels next spring to shift content online where audiences are heading.", "hook_zh": "面对财政压力，BBC 将关掉三个线性频道，把内容迁往观众已转向的线上平台。", "summary_en": "As part of a £500 million savings plan by 2028, the BBC will end BBC Three, BBC Scotland, and Radio 4 Extra as broadcast channels in spring 2027, moving much of their programming to iPlayer, BBC Sounds, and platforms like YouTube. BBC News will cut around 100 jobs to save £5.5 million, with overall workforce reductions targeting 1,800 to 2,000 roles amid declining TV licence payments and changing viewer habits. Director-General Matt Brittin told staff these steps make every pound work harder, while reactions range from Liberal Democrat MP Anna Sabine's concerns over the 'death by a thousand cuts' to others welcoming the changes.", "summary_zh": "作为到 2028 年节省约 5 亿英镑计划的一部分，BBC 将于 2027 年春结束 BBC Three、BBC Scotland 与 Radio 4 Extra 的广播频道形态，节目更多转至 iPlayer、BBC Sounds 与 YouTube 等。新闻部门拟裁约 100 人节省 550 万英镑，整体目标减员约 1800–2000，背景是收视许可费下降与习惯变迁。总监称要让每英镑更高效；也有议员担忧“千刀万剐”式萎缩。", "body_en": "BBC to Close BBC Three, BBC Scotland and Radio 4 Extra in 2027.\n\nThe BBC faces tough financial calls, shutting down three linear channels next spring to shift content online where audiences are heading.\n\nAs part of a £500 million savings plan by 2028, the BBC will end BBC Three, BBC Scotland, and Radio 4 Extra as broadcast channels in spring 2027, moving much of their programming to iPlayer, BBC Sounds, and platforms like YouTube.\n\nBBC News will cut around 100 jobs to save £5.5 million, with overall workforce reductions targeting 1,800 to 2,000 roles amid declining TV licence payments and changing viewer habits. Director-General Matt Brittin told staff these steps make every pound work harder, while reactions range from Liberal Democrat MP Anna Sabine's concerns over the 'death by a thousand cuts' to others welcoming the changes.", "body_zh": "BBC 计划 2027 年关闭 BBC Three、苏格兰台与 Radio 4 Extra 线性频道。\n\n面对财政压力，BBC 将关掉三个线性频道，把内容迁往观众已转向的线上平台。\n\n作为到 2028 年节省约 5 亿英镑计划的一部分，BBC 将于 2027 年春结束 BBC Three、BBC Scotland 与 Radio 4 Extra 的广播频道形态，节目更多转至 iPlayer、BBC Sounds 与 YouTube 等。\n\n新闻部门拟裁约 100 人节省 550 万英镑，整体目标减员约 1800–2000，背景是收视许可费下降与习惯变迁。总监称要让每英镑更高效；也有议员担忧“千刀万剐”式萎缩。", "url": "https://x.com/i/trending/2112533925117460907", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T13:12:48.000Z"}, {"id": "2112468483736834436", "domain": "娱乐", "title_en": "Tate McRae's 'Housewife' Battles Olivia Rodrigo Remix for Hot 100 No. 2", "title_zh": "Tate McRae《Housewife》与 Olivia Rodrigo 混音争夺 Hot 100 亚军", "hook_en": "Tate McRae's bold red performance at the Victoria’s Secret Fashion Show has fans streaming 'Housewife' nonstop, fueling its tight race for No. 2 on the Billboard Hot 100.", "hook_zh": "维多利亚的秘密秀上的火红舞台带动《Housewife》猛冲榜，与 Rodrigo 合作曲缠斗第二名。", "summary_en": "Early forecasts show Tate McRae’s “Housewife” neck-and-neck with Olivia Rodrigo’s “expectations” remix featuring Chappell Roan for the No. 2 spot on the October 31, 2026 Hot 100 chart, alongside challengers like Taylor Swift and Lana Del Rey with Zach Bryan. “Housewife” notched over 6.5 million Spotify streams in a day, topped U.S. and global charts on debut, and won Billboard’s fan poll for favorite new music after Tate’s standout Fashion Show performance now selling for 69 cents. The Rodrigo-Roan remix video, with its fun game-show vibe and cameos, adds fresh push as streams and sales decide the final order in this streaming-driven showdown.", "summary_zh": "早期预测显示，Tate McRae 的《Housewife》与 Olivia Rodrigo 联手 Chappell Roan 的《expectations》混音，在 2026 年 10 月 31 日 Hot 100 亚军位置胶着，泰勒·斯威夫特及 Lana Del Rey 与 Zach Bryan 等亦在挑战。维多利亚的秘密时装秀表演助推串流。《Housewife》成为流行榜焦点之一。", "body_en": "Tate McRae's 'Housewife' Battles Olivia Rodrigo Remix for Hot 100 No. 2.\n\nTate McRae's bold red performance at the Victoria’s Secret Fashion Show has fans streaming 'Housewife' nonstop, fueling its tight race for No. 2 on the Billboard Hot 100.\n\nEarly forecasts show Tate McRae’s “Housewife” neck-and-neck with Olivia Rodrigo’s “expectations” remix featuring Chappell Roan for the No. 2 spot on the October 31, 2026 Hot 100 chart, alongside challengers like Taylor Swift and Lana Del Rey with Zach Bryan.\n\n“Housewife” notched over 6.5 million Spotify streams in a day, topped U.S. and global charts on debut, and won Billboard’s fan poll for favorite new music after Tate’s standout Fashion Show performance now selling for 69 cents. The Rodrigo-Roan remix video, with its fun game-show vibe and cameos, adds fresh push as streams and sales decide the final order in this streaming-driven showdown.", "body_zh": "Tate McRae《Housewife》与 Olivia Rodrigo 混音争夺 Hot 100 亚军。\n\n维多利亚的秘密秀上的火红舞台带动《Housewife》猛冲榜，与 Rodrigo 合作曲缠斗第二名。\n\n早期预测显示，Tate McRae 的《Housewife》与 Olivia Rodrigo 联手 Chappell Roan 的《expectations》混音，在 2026 年 10 月 31 日 Hot 100 亚军位置胶着，泰勒·斯威夫特及 Lana Del Rey 与 Zach Bryan 等亦在挑战。\n\n维多利亚的秘密时装秀表演助推串流。《Housewife》成为流行榜焦点之一。", "url": "https://x.com/i/trending/2112468483736834436", "category": "Entertainment", "topics": ["Music"], "updated_at": "2026-10-21T10:32:22.000Z"}, {"id": "2111675291110088931", "domain": "娱乐", "title_en": "Taylor Swift Shines in Custom Dior at 2026 Academy Museum Gala", "title_zh": "泰勒·斯威夫特定制迪奥惊艳 2026 电影学院博物馆晚会", "hook_en": "Taylor Swift stepped onto the red carpet in a custom icy-blue Dior gown, its soft pleats and sparkling bow catching every eye under the lights.", "hook_zh": "泰勒·斯威夫特红毯亮相冰蓝色定制迪奥礼服，柔褶与闪亮蝴蝶结在灯光下抢尽目光。", "summary_en": "The 2026 Academy Museum Gala on October 17 in Los Angeles raised over $14 million, honoring Charlize Theron, Colman Domingo, and John Carpenter. Swift performed hits like “Blank Space” and “Love Story” in her first full-band show since the Eras Tour, while Sabrina Carpenter and Rosé wowed in ruffled corsets and fringed gowns. Hannah Waddingham shared a warm selfie with Swift, praising her talent, as British Vogue called her the evening's belle in Chopard diamonds topping 40 carats. The horror-themed décor tied into the museum's new exhibition, blending fashion, music, and tributes into a standout night.", "summary_zh": "2026 年 10 月 17 日洛杉矶电影学院博物馆晚会筹得逾 1400 万美元，表彰查理兹·塞隆、科尔曼·多明戈与约翰·卡朋特。斯威夫特自 Eras 巡演后首度全乐队演出《Blank Space》《Love Story》等；Sabrina Carpenter 与 Rosé 也以荷叶边胸衣、流苏礼服惊艳。汉娜·瓦丁厄姆晒与斯威夫特自拍并赞其才华；《英国 Vogue》称其当晚焦点，肖邦钻石超 40 克拉。恐怖主题装饰呼应馆内新展，时尚、音乐与致敬融于一夜。", "body_en": "Taylor Swift Shines in Custom Dior at 2026 Academy Museum Gala.\n\nTaylor Swift stepped onto the red carpet in a custom icy-blue Dior gown, its soft pleats and sparkling bow catching every eye under the lights.\n\nThe 2026 Academy Museum Gala on October 17 in Los Angeles raised over $14 million, honoring Charlize Theron, Colman Domingo, and John Carpenter. Swift performed hits like “Blank Space” and “Love Story” in her first full-band show since the Eras Tour, while Sabrina Carpenter and Rosé wowed in ruffled corsets and fringed gowns.\n\nHannah Waddingham shared a warm selfie with Swift, praising her talent, as British Vogue called her the evening's belle in Chopard diamonds topping 40 carats. The horror-themed décor tied into the museum's new exhibition, blending fashion, music, and tributes into a standout night.", "body_zh": "泰勒·斯威夫特定制迪奥惊艳 2026 电影学院博物馆晚会。\n\n泰勒·斯威夫特红毯亮相冰蓝色定制迪奥礼服，柔褶与闪亮蝴蝶结在灯光下抢尽目光。\n\n2026 年 10 月 17 日洛杉矶电影学院博物馆晚会筹得逾 1400 万美元，表彰查理兹·塞隆、科尔曼·多明戈与约翰·卡朋特。斯威夫特自 Eras 巡演后首度全乐队演出《Blank Space》《Love Story》等；Sabrina Carpenter 与 Rosé 也以荷叶边胸衣、流苏礼服惊艳。\n\n汉娜·瓦丁厄姆晒与斯威夫特自拍并赞其才华；《英国 Vogue》称其当晚焦点，肖邦钻石超 40 克拉。恐怖主题装饰呼应馆内新展，时尚、音乐与致敬融于一夜。", "url": "https://x.com/i/trending/2111675291110088931", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-20T03:07:04.000Z"}, {"id": "2111997785189093552", "domain": "娱乐", "title_en": "Netflix's Norm Macdonald Documentary Draws Laughs and Mixed Views", "title_zh": "网飞 Norm Macdonald 纪录片引笑声与两极评价", "hook_en": "Five years after Norm Macdonald's death at 61, fans are revisiting his deadpan genius through a new Netflix film that mixes laughs with heartfelt memories.", "hook_zh": "离世五年后，粉丝通过新片重温他的冷面幽默与深情回忆。", "summary_en": "Directed by Judd Apatow, 'Norm: The Tale of Norm Macdonald' premiered October 16 and runs two hours, using archival clips, home videos, photos, and his own audiobook narration instead of new interviews. Viewers praise it as a worthy tribute to his SNL Weekend Update days, O.J. jokes, and legendary timing, with some left laughing and crying over the man they miss. Others call it a clip show lacking fresh insight or his edgier routines, like certain 9/11 bits, though it highlights his private cancer battle and uncompromised style. The responses reflect his enduring, divisive impact on comedy.", "summary_zh": "由贾德·阿帕图执导的《Norm: The Tale of Norm Macdonald》10 月 16 日上线，时长约两小时，以档案片段、家庭影像、照片及其有声书旁白串联，未做新采访。观众称其为向 SNL《Weekend Update》、O.J. 玩笑与标志性节奏的致敬，有人边笑边哭；也有人觉得像精剪合集，缺少新洞察或其更锋利的段子。影片亦触及他私下与癌症抗争等面向，整体褒贬并存。", "body_en": "Netflix's Norm Macdonald Documentary Draws Laughs and Mixed Views.\n\nFive years after Norm Macdonald's death at 61, fans are revisiting his deadpan genius through a new Netflix film that mixes laughs with heartfelt memories.\n\nDirected by Judd Apatow, 'Norm: The Tale of Norm Macdonald' premiered October 16 and runs two hours, using archival clips, home videos, photos, and his own audiobook narration instead of new interviews. Viewers praise it as a worthy tribute to his SNL Weekend Update days, O.J.\n\njokes, and legendary timing, with some left laughing and crying over the man they miss. Others call it a clip show lacking fresh insight or his edgier routines, like certain 9/11 bits, though it highlights his private cancer battle and uncompromised style. The responses reflect his enduring, divisive impact on comedy.", "body_zh": "网飞 Norm Macdonald 纪录片引笑声与两极评价。\n\n离世五年后，粉丝通过新片重温他的冷面幽默与深情回忆。\n\n由贾德·阿帕图执导的《Norm: The Tale of Norm Macdonald》10 月 16 日上线，时长约两小时，以档案片段、家庭影像、照片及其有声书旁白串联，未做新采访。\n\n观众称其为向 SNL《Weekend Update》、O.J. 玩笑与标志性节奏的致敬，有人边笑边哭；也有人觉得像精剪合集，缺少新洞察或其更锋利的段子。影片亦触及他私下与癌症抗争等面向，整体褒贬并存。", "url": "https://x.com/i/trending/2111997785189093552", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-20T05:10:09.000Z"}, {"id": "2112653365356433717", "domain": "娱乐", "title_en": "Fans Defend Ariana Grande as Glinda Against Amanda Seyfried Casting Talk", "title_zh": "粉丝力挺格兰德饰演格琳达，回应赛弗里德「本可更好」论", "hook_en": "A post wondering if Amanda Seyfried would have topped Ariana Grande as Glinda in Wicked quickly met pushback from fans who love the film's magic just as it is.", "hook_zh": "有人猜测若由阿曼达·赛弗里德演《魔法坏女巫》格琳达会否更佳，粉丝迅速反驳：电影本身已够魔力。", "summary_en": "Ariana Grande shines as the bubbly Glinda opposite Cynthia Erivo's Elphaba in Jon M. Chu's hit musical films, which have pulled in hundreds of millions at the box office. Seyfried auditioned multiple times, even carving out time during The Dropout shoots, but later said Grande was meant for the role and called the movie fantastic. Fans highlight Grande's vocal range, her chemistry with Erivo, and director Chu's praise for her unique audition energy, shutting down the recurring what-if debate. The back-and-forth underscores fans' strong bond with Wicked's tale of friendship and ambition.", "summary_zh": "爱莉安娜·格兰德在朱浩伟执导的音乐电影中饰演活泼的格琳达，与辛西娅·埃里沃的艾尔法巴对手戏，票房累计数亿美元。赛弗里德曾多次试镜，后称角色本就属于格兰德并盛赞影片。粉丝强调其音域、与埃里沃的化学反应以及导演对其试镜能量的肯定，终结反复出现的「假如」争论。", "body_en": "Fans Defend Ariana Grande as Glinda Against Amanda Seyfried Casting Talk.\n\nA post wondering if Amanda Seyfried would have topped Ariana Grande as Glinda in Wicked quickly met pushback from fans who love the film's magic just as it is.\n\nAriana Grande shines as the bubbly Glinda opposite Cynthia Erivo's Elphaba in Jon M. Chu's hit musical films, which have pulled in hundreds of millions at the box office.\n\nSeyfried auditioned multiple times, even carving out time during The Dropout shoots, but later said Grande was meant for the role and called the movie fantastic. Fans highlight Grande's vocal range, her chemistry with Erivo, and director Chu's praise for her unique audition energy, shutting down the recurring what-if debate. The back-and-forth underscores fans' strong bond with Wicked's tale of friendship and ambition.", "body_zh": "粉丝力挺格兰德饰演格琳达，回应赛弗里德「本可更好」论。\n\n有人猜测若由阿曼达·赛弗里德演《魔法坏女巫》格琳达会否更佳，粉丝迅速反驳：电影本身已够魔力。\n\n爱莉安娜·格兰德在朱浩伟执导的音乐电影中饰演活泼的格琳达，与辛西娅·埃里沃的艾尔法巴对手戏，票房累计数亿美元。赛弗里德曾多次试镜，后称角色本就属于格兰德并盛赞影片。\n\n粉丝强调其音域、与埃里沃的化学反应以及导演对其试镜能量的肯定，终结反复出现的「假如」争论。", "url": "https://x.com/i/trending/2112653365356433717", "category": "Entertainment", "topics": ["Movies & TV", "Celebrity"], "updated_at": "2026-10-21T00:31:26.000Z"}, {"id": "2112605676610478278", "domain": "娱乐", "title_en": "Jaafar Jackson Wins Actor Award for Michael Jackson Role in 'Michael'", "title_zh": "贾法尔·杰克逊凭《Michael》迈克尔·杰克逊一角获演员奖", "hook_en": "Jaafar Jackson, nephew of the King of Pop, steps into the spotlight with a Critics Choice honor for his feature debut as Michael Jackson.", "hook_zh": "「流行之王」侄子贾法尔·杰克逊凭长片处女作饰演迈克尔·杰克逊，获评论选择荣誉，站上聚光灯。", "summary_en": "The Critics Choice Association named Jaafar Jackson the Actor Award – Film recipient at the 9th Annual Celebration of Black Cinema & Television for his portrayal in Lionsgate's 'Michael,' the first biopic to top $1 billion worldwide and Lionsgate's biggest release ever. Directed by Antoine Fuqua, the film traces Michael Jackson's rise and drew strong box-office success since opening in April. The ceremony happens November 16, 2026, at Fairmont Century Plaza in Los Angeles, with others like Debbie Allen receiving honors too. Fans celebrated the news, praising his acclaimed performance.", "summary_zh": "评论选择协会将第 9 届黑人电影与电视庆典「电影演员奖」授予贾法尔·杰克逊，表彰其在狮门《Michael》中的演绎——该片为全球票房破 10 亿美元的首部传记片，亦是狮门史上最大发行。安东尼·福奎阿执导，追溯杰克逊崛起，4 月上映后票房强劲。典礼 2026 年 11 月 16 日在洛杉矶 Fairmont Century Plaza 举行，黛比·艾伦等亦获表彰。粉丝庆祝并称赞其获好评的表演。", "body_en": "Jaafar Jackson Wins Actor Award for Michael Jackson Role in 'Michael'.\n\nJaafar Jackson, nephew of the King of Pop, steps into the spotlight with a Critics Choice honor for his feature debut as Michael Jackson.\n\nThe Critics Choice Association named Jaafar Jackson the Actor Award – Film recipient at the 9th Annual Celebration of Black Cinema & Television for his portrayal in Lionsgate's 'Michael,' the first biopic to top $1 billion worldwide and Lionsgate's biggest release ever. Directed by Antoine Fuqua, the film traces Michael Jackson's rise and drew strong box-office success since opening in April.\n\nThe ceremony happens November 16, 2026, at Fairmont Century Plaza in Los Angeles, with others like Debbie Allen receiving honors too. Fans celebrated the news, praising his acclaimed performance.", "body_zh": "贾法尔·杰克逊凭《Michael》迈克尔·杰克逊一角获演员奖。\n\n「流行之王」侄子贾法尔·杰克逊凭长片处女作饰演迈克尔·杰克逊，获评论选择荣誉，站上聚光灯。\n\n评论选择协会将第 9 届黑人电影与电视庆典「电影演员奖」授予贾法尔·杰克逊，表彰其在狮门《Michael》中的演绎——该片为全球票房破 10 亿美元的首部传记片，亦是狮门史上最大发行。安东尼·福奎阿执导，追溯杰克逊崛起，4 月上映后票房强劲。\n\n典礼 2026 年 11 月 16 日在洛杉矶 Fairmont Century Plaza 举行，黛比·艾伦等亦获表彰。粉丝庆祝并称赞其获好评的表演。", "url": "https://x.com/i/trending/2112605676610478278", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-20T18:15:13.000Z"}, {"id": "2112852935252259068", "domain": "娱乐", "title_en": "Lena's Debut Film 'Her in Frame' Hits Netflix October 29", "title_zh": "莉娜首部电影《Her in Frame》10 月 29 日登陆网飞", "hook_en": "Fans are buzzing with joy as Thai actress Lena's first movie finally streams worldwide, marking her long-awaited big-screen moment.", "hook_zh": "泰国女演员莉娜大银幕处女作全球上线，粉丝期待已久。", "summary_en": "The romantic drama follows a young photographer chasing dreams of a mysterious woman from an old photo, blending past lives with present-day Thailand. Directed by Ekkasit Trakulkaesemsuk, it stars Thanapob Leeratanakachorn and Lena, inspired by the love story of King Bhumibol Adulyadej and Queen Sirikit. Available in Thailand, Indonesia, Malaysia, Vietnam, South Korea, and Japan, the 1-hour-41-minute film has a 13+ rating and early praise for its emotional depth and the leads' chemistry. Supporters are resubscribing to Netflix and organizing watch parties to celebrate this milestone.", "summary_zh": "这部爱情剧讲述年轻摄影师追寻旧照中神秘女子的梦想，交织前世今生与当代泰国。由 Ekkasit Trakulkaesemsuk 执导，Thanapob Leeratanakachorn 与莉娜主演，灵感来自普密蓬国王与诗丽吉王后的爱情故事。影片约 1 小时 41 分，13+ 分级，先在泰国、印尼、马来西亚、越南、韩国与日本上线，早期评价称情感与对手戏有吸引力。", "body_en": "Lena's Debut Film 'Her in Frame' Hits Netflix October 29.\n\nFans are buzzing with joy as Thai actress Lena's first movie finally streams worldwide, marking her long-awaited big-screen moment.\n\nThe romantic drama follows a young photographer chasing dreams of a mysterious woman from an old photo, blending past lives with present-day Thailand. Directed by Ekkasit Trakulkaesemsuk, it stars Thanapob Leeratanakachorn and Lena, inspired by the love story of King Bhumibol Adulyadej and Queen Sirikit.\n\nAvailable in Thailand, Indonesia, Malaysia, Vietnam, South Korea, and Japan, the 1-hour-41-minute film has a 13+ rating and early praise for its emotional depth and the leads' chemistry. Supporters are resubscribing to Netflix and organizing watch parties to celebrate this milestone.", "body_zh": "莉娜首部电影《Her in Frame》10 月 29 日登陆网飞。\n\n泰国女演员莉娜大银幕处女作全球上线，粉丝期待已久。\n\n这部爱情剧讲述年轻摄影师追寻旧照中神秘女子的梦想，交织前世今生与当代泰国。\n\n由 Ekkasit Trakulkaesemsuk 执导，Thanapob Leeratanakachorn 与莉娜主演，灵感来自普密蓬国王与诗丽吉王后的爱情故事。影片约 1 小时 41 分，13+ 分级，先在泰国、印尼、马来西亚、越南、韩国与日本上线，早期评价称情感与对手戏有吸引力。", "url": "https://x.com/i/trending/2112852935252259068", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T10:32:17.000Z"}, {"id": "2112787028131914147", "domain": "娱乐", "title_en": "Zhao Lusi Stuns in Elie Saab Gown for Harper’s Bazaar Gala", "title_zh": "赵露思身着 Elie Saab 高定亮相时尚芭莎盛典", "hook_en": "Zhao Lusi reclined gracefully on a vivid red chaise lounge, her black Elie Saab gown blooming with red roses under dramatic lights.", "hook_zh": "赵露思斜倚鲜红躺椅，黑色 Elie Saab 礼服在灯光下绽放红玫瑰刺绣。", "summary_en": "At the Harper’s Bazaar “From China” 2026 Annual Gala on October 21, Chinese actress Zhao Lusi shone in an Elie Saab Fall/Winter 2026 Haute Couture gown from the “The Ball of Untamed Dreams” collection. The elaborate black design featured delicate lace, floral appliqués, a mermaid silhouette, and flowing train, paired with BVLGARI serpenti jewelry including necklaces, rings, and a watch. Fans loved the “Midnight Rose” and “Rosy Heritage Beauty” theme, sharing close-ups of her glowing presence and intimate portraits that highlighted the intricate details. Her standout look from the season’s most coveted pieces underscored her rising influence in entertainment and fashion.", "summary_zh": "10 月 21 日时尚芭莎“From China”2026 年度盛典上，赵露思身着 Elie Saab 2026 秋冬高定“不羁梦之舞会”系列黑色礼服，蕾丝与花卉贴花、鱼尾剪裁与拖尾搭配宝格丽蛇形珠宝。粉丝称赞“午夜玫瑰”造型与细节特写。该造型也被视为她在娱乐与时尚影响力上升的又一注脚。", "body_en": "Zhao Lusi Stuns in Elie Saab Gown for Harper’s Bazaar Gala.\n\nZhao Lusi reclined gracefully on a vivid red chaise lounge, her black Elie Saab gown blooming with red roses under dramatic lights.\n\nAt the Harper’s Bazaar “From China” 2026 Annual Gala on October 21, Chinese actress Zhao Lusi shone in an Elie Saab Fall/Winter 2026 Haute Couture gown from the “The Ball of Untamed Dreams” collection. The elaborate black design featured delicate lace, floral appliqués, a mermaid silhouette, and flowing train, paired with BVLGARI serpenti jewelry including necklaces, rings, and a watch.\n\nFans loved the “Midnight Rose” and “Rosy Heritage Beauty” theme, sharing close-ups of her glowing presence and intimate portraits that highlighted the intricate details. Her standout look from the season’s most coveted pieces underscored her rising influence in entertainment and fashion.", "body_zh": "赵露思身着 Elie Saab 高定亮相时尚芭莎盛典。\n\n赵露思斜倚鲜红躺椅，黑色 Elie Saab 礼服在灯光下绽放红玫瑰刺绣。\n\n10 月 21 日时尚芭莎“From China”2026 年度盛典上，赵露思身着 Elie Saab 2026 秋冬高定“不羁梦之舞会”系列黑色礼服，蕾丝与花卉贴花、鱼尾剪裁与拖尾搭配宝格丽蛇形珠宝。\n\n粉丝称赞“午夜玫瑰”造型与细节特写。该造型也被视为她在娱乐与时尚影响力上升的又一注脚。", "url": "https://x.com/i/trending/2112787028131914147", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-21T13:04:04.000Z"}, {"id": "2112801173090587112", "domain": "娱乐", "title_en": "Thai Star Lingling Kwong Shines at Cartier's Wild Singapore Event", "title_zh": "Lingling Kwong 亮相新加坡卡地亚活动", "hook_en": "Lingling Sirilak Kwong glided through lush gardens in shimmering gowns and bold Cartier jewels, captivating everyone at the Faune & Flore celebration.", "hook_zh": "Lingling Kwong 身着黑色亮片长裙、配戏剧性手套，走进卡地亚丛林主题场景，以经典优雅吸引目光。", "summary_en": "Cartier transformed Rochester Park's historic bungalows into a nature-inspired wonderland for its 'Into the Wild' event, spotlighting panther motifs and floral designs across jewelry and more. Thai actress Kwong arrived as a special guest, switching elegant looks like a sequined halter gown with opera gloves and statement necklaces amid dances and illuminated gardens. The free public exhibition at 17 Rochester Park continues through October 25, with artisan demos and a tea salon inviting all to explore Cartier's craft.", "summary_zh": "10 月 21 日在罗切斯特公园举行的「Into the Wild」沉浸式体验中，她佩戴卡地亚全新 Faune & Flore 系列，搭配缟玛瑙、蓝宝石与钻石，被粉丝称为「女王范」。活动展出品牌动物灵感设计，持续至 10 月 25 日。同日她还在曼谷大型粉丝活动上推广 Her Hyness 防晒产品，凸显其在奢侈品与美妆领域的上升势头。", "body_en": "Lingling Kwong Shines at Cartier Event in Singapore.\n\nLingling Kwong stepped into Cartier’s wild jungle-themed world in a sleek black sequined gown and dramatic gloves, turning heads with her timeless elegance.\n\nAt the 'Into the Wild' immersive experience in Rochester Park on October 21, Kwong wore pieces from Cartier’s new Faune & Flore collection, featuring onyx, sapphires, and diamonds that fans called striking and queenly.\n\nThe event celebrates the brand’s animal-inspired designs through October 25. That same day, she promoted Her Hyness sunscreen at a big fan event in Bangkok, highlighting her rising star in luxury and beauty.", "body_zh": "Lingling Kwong 亮相新加坡卡地亚活动。\n\nLingling Kwong 身着黑色亮片长裙、配戏剧性手套，走进卡地亚丛林主题场景，以经典优雅吸引目光。\n\n10 月 21 日在罗切斯特公园举行的「Into the Wild」沉浸式体验中，她佩戴卡地亚全新 Faune & Flore 系列，搭配缟玛瑙、蓝宝石与钻石，被粉丝称为「女王范」。\n\n活动展出品牌动物灵感设计，持续至 10 月 25 日。同日她还在曼谷大型粉丝活动上推广 Her Hyness 防晒产品，凸显其在奢侈品与美妆领域的上升势头。", "url": "https://x.com/i/trending/2112801173090587112", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-21T11:50:05.000Z"}, {"id": "2112244938171924792", "domain": "娱乐", "title_en": "Taylor Swift Delivers Surprise Band Performance at Academy Museum Gala", "title_zh": "泰勒·斯威夫特时隔近两年带全乐队亮相学院博物馆晚会", "hook_en": "Taylor Swift stepped back into the spotlight with her full band for the first time in nearly two years, turning a glamorous gala into a musical highlight.", "hook_zh": "泰勒带全乐队近两年来首次登台，把一场名流晚宴变成音乐高光。", "summary_en": "At the 2026 Academy Museum Gala honoring John Carpenter, Colman Domingo, and Charlize Theron, Swift performed four songs: 'Blank Space,' the live debut of 'The Fate of Ophelia' from her 2025 album The Life of a Showgirl, 'I Knew It, I Knew You' from Toy Story 5, and 'Love Story.' Introduced by Conan O’Brien, who called her 'John, Paul, George and Ringo all in one,' she dazzled in gown changes from Dior to Ralph Lauren and mingled with Toy Story 5 castmates. The event, themed around the museum’s 'The Horror Show' exhibition, raised over $14 million, with Swift paying her own ticket and performing for free, later calling it a 'VIBE' on Instagram.", "summary_zh": "在致敬约翰·卡朋特、科尔曼·多明戈与查理兹·塞隆的 2026 学院博物馆晚会上，她演唱《Blank Space》、2025 专辑中《The Fate of Ophelia》的现场首唱、为《玩具总动员 5》创作的《I Knew It, I Knew You》以及《Love Story》。柯南·奥布莱恩介绍时称她“约翰、保罗、乔治与林戈集于一身”。晚会呼应博物馆恐怖展主题，筹得逾 1400 万美元；她自费购票并义务演出，事后在 Instagram 称当晚很有感觉。", "body_en": "Taylor Swift Delivers Surprise Band Performance at Academy Museum Gala.\n\nTaylor Swift stepped back into the spotlight with her full band for the first time in nearly two years, turning a glamorous gala into a musical highlight.\n\nAt the 2026 Academy Museum Gala honoring John Carpenter, Colman Domingo, and Charlize Theron, Swift performed four songs: 'Blank Space,' the live debut of 'The Fate of Ophelia' from her 2025 album The Life of a Showgirl, 'I Knew It, I Knew You' from Toy Story 5, and 'Love Story.' Introduced by Conan O’Brien, who called her 'John, Paul, George and Ringo all in one,' she dazzled in gown changes from Dior to Ralph Lauren and mingled with Toy Story 5 castmates. The event, themed around the museum’s 'The Horror Show' exhibition, raised over $14 million, with Swift paying her own ticket and performing for free, later calling it a 'VIBE' on Instagram.", "body_zh": "泰勒·斯威夫特时隔近两年带全乐队亮相学院博物馆晚会。\n\n泰勒带全乐队近两年来首次登台，把一场名流晚宴变成音乐高光。\n\n在致敬约翰·卡朋特、科尔曼·多明戈与查理兹·塞隆的 2026 学院博物馆晚会上，她演唱《Blank Space》、2025 专辑中《The Fate of Ophelia》的现场首唱、为《玩具总动员 5》创作的《I Knew It, I Knew You》以及《Love Story》。\n\n柯南·奥布莱恩介绍时称她“约翰、保罗、乔治与林戈集于一身”。晚会呼应博物馆恐怖展主题，筹得逾 1400 万美元；她自费购票并义务演出，事后在 Instagram 称当晚很有感觉。", "url": "https://x.com/i/trending/2112244938171924792", "category": "Entertainment", "topics": ["Music", "Concerts"], "updated_at": "2026-10-21T11:03:21.000Z"}, {"id": "2112446063462297885", "domain": "娱乐", "title_en": "ElevenLabs Launches Chroma Awards Season 2 with $1M Trials and $450K Prizes", "title_zh": "ElevenLabs 启动第二季 Chroma 大奖：百万试用与逾 45 万美元奖池", "hook_en": "Creators lit up with excitement as ElevenLabs dropped Season 2 of the Chroma Awards, offering $1 million in free trials and over $450,000 in cash plus travel perks.", "hook_zh": "ElevenLabs 公布第二季 Chroma Awards，提供约 100 万美元免费试用与逾 45 万美元现金及差旅奖励，创作者热情高涨。", "summary_en": "Submissions are now open for the expanded competition, featuring new divisions for advertising, games, film and TV, music videos, behind-the-scenes content, sponsor awards, and student entries. AI community members shared plans like swapping temp tracks for original scores, building real games instead of trailers, and teaming up with family for voice work and level design. One team sees the prizes as their first chance to meet in person, while others are forming crews after years solo or finishing long-stalled projects. The early January deadline gives time to polish original AI-assisted work amid a wave of collaborations.", "summary_zh": "扩大后的赛事现已开放投稿，分设广告、游戏、影视、音乐视频、幕后、赞助商奖与学生组别等。AI 社区分享用原声替换临时音轨、打磨短片等参赛计划。主办方希望以奖金与算力试用推动语音与多媒体创作；截稿与评审时间表以官方页面为准。", "body_en": "ElevenLabs Launches Chroma Awards Season 2 with $1M Trials and $450K Prizes.\n\nCreators lit up with excitement as ElevenLabs dropped Season 2 of the Chroma Awards, offering $1 million in free trials and over $450,000 in cash plus travel perks.\n\nSubmissions are now open for the expanded competition, featuring new divisions for advertising, games, film and TV, music videos, behind-the-scenes content, sponsor awards, and student entries. AI community members shared plans like swapping temp tracks for original scores, building real games instead of trailers, and teaming up with family for voice work and level design.\n\nOne team sees the prizes as their first chance to meet in person, while others are forming crews after years solo or finishing long-stalled projects. The early January deadline gives time to polish original AI-assisted work amid a wave of collaborations.", "body_zh": "ElevenLabs 启动第二季 Chroma 大奖：百万试用与逾 45 万美元奖池。\n\nElevenLabs 公布第二季 Chroma Awards，提供约 100 万美元免费试用与逾 45 万美元现金及差旅奖励，创作者热情高涨。\n\n扩大后的赛事现已开放投稿，分设广告、游戏、影视、音乐视频、幕后、赞助商奖与学生组别等。\n\nAI 社区分享用原声替换临时音轨、打磨短片等参赛计划。主办方希望以奖金与算力试用推动语音与多媒体创作；截稿与评审时间表以官方页面为准。", "url": "https://x.com/i/trending/2112446063462297885", "category": "Entertainment", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T12:40:13.000Z"}, {"id": "2112426906595524740", "domain": "娱乐", "title_en": "JoongDunk Fan Meeting Sells Out in Hong Kong Amid Duo Split", "title_zh": "JoongDunk 香港粉丝见面会售罄，恰逢搭档拆伙消息", "hook_en": "Fans grabbed every ticket for JoongDunk's December 5 Hong Kong fan meeting, turning it into a sell-out just days after their agency announced the end of their on-screen pairing.", "hook_zh": "经纪公司刚宣布两人结束荧幕搭档，12 月 5 日香港见面会门票却被粉丝抢光。", "summary_en": "Thai actors Joong Archen Aydin and Dunk Natachai Boonprasert, beloved as JoongDunk, will appear together one last time with their character Jaidee at Nina Hotel Tsuen Wan West. GMMTV announced on October 19 that the pair mutually agreed to pursue separate careers, but this event and prior schedules remain on track. Supporters from multiple countries snapped up tickets and add-ons, sharing emotional tributes like sketches and messages of endless love, while warning against unofficial sellers. The rapid sell-out underscores their lasting bond with fans, who mix joy over the gathering with hopes for cherished memories.", "summary_zh": "泰国演员 Joong 与 Dunk（组合 JoongDunk）将携角色 Jaidee 在荃湾西如心酒店举行见面会。GMMTV 10 月 19 日称双方同意各自发展，但本场与既定行程照常。多国粉丝抢票并分享手绘与留言，也提醒提防黄牛。迅速售罄显示粉丝黏性仍在，喜悦与不舍交织。", "body_en": "JoongDunk Fan Meeting Sells Out in Hong Kong Amid Duo Split.\n\nFans grabbed every ticket for JoongDunk's December 5 Hong Kong fan meeting, turning it into a sell-out just days after their agency announced the end of their on-screen pairing.\n\nThai actors Joong Archen Aydin and Dunk Natachai Boonprasert, beloved as JoongDunk, will appear together one last time with their character Jaidee at Nina Hotel Tsuen Wan West. GMMTV announced on October 19 that the pair mutually agreed to pursue separate careers, but this event and prior schedules remain on track.\n\nSupporters from multiple countries snapped up tickets and add-ons, sharing emotional tributes like sketches and messages of endless love, while warning against unofficial sellers. The rapid sell-out underscores their lasting bond with fans, who mix joy over the gathering with hopes for cherished memories.", "body_zh": "JoongDunk 香港粉丝见面会售罄，恰逢搭档拆伙消息。\n\n经纪公司刚宣布两人结束荧幕搭档，12 月 5 日香港见面会门票却被粉丝抢光。\n\n泰国演员 Joong 与 Dunk（组合 JoongDunk）将携角色 Jaidee 在荃湾西如心酒店举行见面会。GMMTV 10 月 19 日称双方同意各自发展，但本场与既定行程照常。\n\n多国粉丝抢票并分享手绘与留言，也提醒提防黄牛。迅速售罄显示粉丝黏性仍在，喜悦与不舍交织。", "url": "https://x.com/i/trending/2112426906595524740", "category": "Entertainment", "topics": ["Concerts"], "updated_at": "2026-10-21T11:16:28.000Z"}, {"id": "2112433199888679267", "domain": "科学", "title_en": "AI Predicts Cancer Survival from Face Photos", "title_zh": "AI 凭面部照片预测癌症生存风险", "hook_en": "Doctors have always glanced at a patient's face to sense how sick they might be. Now AI makes that gut feel precise, spotting survival odds from a single snapshot.", "hook_zh": "医生一向会扫一眼患者面容判断病情轻重；如今 AI 把这种直觉量化，单张快照即可估计生存概率。", "summary_en": "Researchers from Mass General Brigham, Dana-Farber, Harvard, and Dutch partners unveiled FAHR-Face, two AI tools trained on millions of images that estimate biological age and forecast mortality risk for cancer patients. In tests with over 34,000 patients, the survival model showed those in the highest-risk group faced three times the death risk of the lowest, even after accounting for clinical factors, with strong results in an independent validation. While promising for low-cost checks using just a phone photo, the tools—mostly trained on white Boston patients—need more diverse testing and aren't ready for clinics yet. Lead researchers see it as a complement to doctor judgment, with the model now public on Hugging Face.", "summary_zh": "麻省总医院布莱根、丹娜法伯、哈佛与荷兰合作方发布 FAHR-Face：两款在海量图像上训练的 AI，可估计生物学年龄并预测癌症患者死亡风险。逾 3.4 万名患者测试显示，最高风险组死亡风险约为最低组三倍，即使校正临床因素后仍成立，独立验证表现稳健。工具有望用手机照片做低成本筛查，但主要在波士顿白人患者上训练，需更多元验证，尚不能进诊所。负责人视其为医生判断的补充，模型已在 Hugging Face 公开。", "body_en": "AI Predicts Cancer Survival from Face Photos.\n\nDoctors have always glanced at a patient's face to sense how sick they might be. Now AI makes that gut feel precise, spotting survival odds from a single snapshot.\n\nResearchers from Mass General Brigham, Dana-Farber, Harvard, and Dutch partners unveiled FAHR-Face, two AI tools trained on millions of images that estimate biological age and forecast mortality risk for cancer patients. In tests with over 34,000 patients, the survival model showed those in the highest-risk group faced three times the death risk of the lowest, even after accounting for clinical factors, with strong results in an independent validation.\n\nWhile promising for low-cost checks using just a phone photo, the tools—mostly trained on white Boston patients—need more diverse testing and aren't ready for clinics yet. Lead researchers see it as a complement to doctor judgment, with the model now public on Hugging Face.", "body_zh": "AI 凭面部照片预测癌症生存风险。\n\n医生一向会扫一眼患者面容判断病情轻重；如今 AI 把这种直觉量化，单张快照即可估计生存概率。\n\n麻省总医院布莱根、丹娜法伯、哈佛与荷兰合作方发布 FAHR-Face：两款在海量图像上训练的 AI，可估计生物学年龄并预测癌症患者死亡风险。逾 3.4 万名患者测试显示，最高风险组死亡风险约为最低组三倍，即使校正临床因素后仍成立，独立验证表现稳健。\n\n工具有望用手机照片做低成本筛查，但主要在波士顿白人患者上训练，需更多元验证，尚不能进诊所。负责人视其为医生判断的补充，模型已在 Hugging Face 公开。", "url": "https://x.com/i/trending/2112433199888679267", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T21:07:35.000Z"}, {"id": "2112771430316404992", "domain": "科学", "title_en": "Biosphere 2 Experiment Revives Debates on Self-Sustaining Living", "title_zh": "生物圈 2 号实验再引「自给生存」讨论", "hook_en": "Eight people stepped into a glass dome in the Arizona desert in 1991, aiming to create a sealed world with its own rainforest, ocean, and farm. Two years later, they emerged thinner but alive, sparking lessons that echo today.", "hook_zh": "1991 年八人走进亚利桑那沙漠玻璃穹顶，试图建造含雨林、海洋与农场的密封世界；两年后消瘦但存活走出，启示至今回响。", "summary_en": "The $150 million Biosphere 2 project tested if humans could thrive in a three-acre sealed ecosystem, growing 80 percent of their calories from crops like sweet potatoes and bananas, with goats providing key milk and a few pigs and chickens for scraps. Challenges hit hard: oxygen levels dropped to 14 percent from soil microbes outpacing plants, crew lost 10-20 percent body weight, and animals like pigs were slaughtered early amid calorie shortages. A popular thread recaps these struggles, with some calling it a warning against plant-heavy diets while others note fixes like added oxygen could work for space or Earth setups. The dome near Tucson now serves as a University of Arizona research site for ecology.", "summary_zh": "耗资约 1.5 亿美元的生物圈 2 号检验人类能否在三英亩密封生态中生存：约 80% 热量来自红薯、香蕉等作物，山羊供奶，少量猪鸡处理厨余。挑战严峻：土壤微生物耗氧快于植物，氧气降至 14%，成员减重 10–20%，猪等动物因热量不足提前宰杀。热门讨论有人视之为植物为主饮食的警示，也有人认为补氧等修正可用于太空或地球方案。图森附近穹顶现为亚利桑那大学生态研究站。", "body_en": "Biosphere 2 Experiment Revives Debates on Self-Sustaining Living.\n\nEight people stepped into a glass dome in the Arizona desert in 1991, aiming to create a sealed world with its own rainforest, ocean, and farm. Two years later, they emerged thinner but alive, sparking lessons that echo today.\n\nThe $150 million Biosphere 2 project tested if humans could thrive in a three-acre sealed ecosystem, growing 80 percent of their calories from crops like sweet potatoes and bananas, with goats providing key milk and a few pigs and chickens for scraps. Challenges hit hard: oxygen levels dropped to 14 percent from soil microbes outpacing plants, crew lost 10-20 percent body weight, and animals like pigs were slaughtered early amid calorie shortages.\n\nA popular thread recaps these struggles, with some calling it a warning against plant-heavy diets while others note fixes like added oxygen could work for space or Earth setups. The dome near Tucson now serves as a University of Arizona research site for ecology.", "body_zh": "生物圈 2 号实验再引「自给生存」讨论。\n\n1991 年八人走进亚利桑那沙漠玻璃穹顶，试图建造含雨林、海洋与农场的密封世界；两年后消瘦但存活走出，启示至今回响。\n\n耗资约 1.5 亿美元的生物圈 2 号检验人类能否在三英亩密封生态中生存：约 80% 热量来自红薯、香蕉等作物，山羊供奶，少量猪鸡处理厨余。挑战严峻：土壤微生物耗氧快于植物，氧气降至 14%，成员减重 10–20%，猪等动物因热量不足提前宰杀。\n\n热门讨论有人视之为植物为主饮食的警示，也有人认为补氧等修正可用于太空或地球方案。图森附近穹顶现为亚利桑那大学生态研究站。", "url": "https://x.com/i/trending/2112771430316404992", "category": "News", "topics": ["Science"], "updated_at": "2026-10-21T07:36:09.000Z"}, {"id": "2112514540671730138", "domain": "科学", "title_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight", "title_zh": "路透调查：热风暴已连续 18 年覆盖全球某处", "hook_en": "Imagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.", "hook_zh": "路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。", "summary_en": "Reuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade. People share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "summary_zh": "路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "body_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight.\n\nImagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.\n\nReuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade.\n\nPeople share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "body_zh": "路透调查：热风暴已连续 18 年覆盖全球某处。\n\n路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。\n\n路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。\n\n人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "url": "https://x.com/i/trending/2112514540671730138", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T17:06:35.000Z"}, {"id": "2112833225118625949", "domain": "科学", "title_en": "Nigeria Debunks Viral Claims on US Medical Aid Deal", "title_zh": "尼日利亚驳斥美医疗援助协议「禁检疫苗」谣言", "hook_en": "Panic spread online after posts claimed a US deal would block Nigeria's drug agency from testing free vaccines and medicines. Officials stepped in swiftly to set the record straight.", "hook_zh": "网传美援协议禁止药监局检测免费疫苗药品，官方迅速澄清主权与安检仍在。", "summary_en": "Viral messages alleged a $3 billion US aid package for malaria and other diseases barred NAFDAC from reviewing supplies, sparking fears of unsafe products and lost sovereignty—claims that Ghana supposedly rejected. NAFDAC's Director-General Prof. Mojisola Adeyeye clarified on October 20, 2026, that the agency keeps full authority: US FDA-approved products get expedited review due to existing reliance, but all undergo safety checks, especially non-US ones, with tracking via blockchain. The five-year MoU, signed December 2025, provides nearly $2 billion in declining US grants for HIV/AIDS and health programs, while Nigeria boosts its spending to $3 billion for self-reliance.", "summary_zh": "病毒式帖文称约 30 亿美元美援疟疾等项目禁止 NAFDAC 审查物资，引发不安全与主权丧失恐慌，并称加纳已拒绝。NAFDAC 局长 Mojisola Adeyeye 教授 2026 年 10 月 20 日澄清：机构保留完整权限；FDA 已批产品可加快审评，但皆须安全检查，非美产品尤然，并以区块链追踪。2025 年 12 月签署的五年谅解备忘录提供近 20 亿美元递减美方拨款用于艾滋病等卫生项目，尼日利亚同步将本国投入提至约 30 亿美元以增强自立。", "body_en": "Nigeria Debunks Viral Claims on US Medical Aid Deal.\n\nPanic spread online after posts claimed a US deal would block Nigeria's drug agency from testing free vaccines and medicines. Officials stepped in swiftly to set the record straight.\n\nViral messages alleged a $3 billion US aid package for malaria and other diseases barred NAFDAC from reviewing supplies, sparking fears of unsafe products and lost sovereignty—claims that Ghana supposedly rejected. NAFDAC's Director-General Prof.\n\nMojisola Adeyeye clarified on October 20, 2026, that the agency keeps full authority: US FDA-approved products get expedited review due to existing reliance, but all undergo safety checks, especially non-US ones, with tracking via blockchain. The five-year MoU, signed December 2025, provides nearly $2 billion in declining US grants for HIV/AIDS and health programs, while Nigeria boosts its spending to $3 billion for self-reliance.", "body_zh": "尼日利亚驳斥美医疗援助协议「禁检疫苗」谣言。\n\n网传美援协议禁止药监局检测免费疫苗药品，官方迅速澄清主权与安检仍在。\n\n病毒式帖文称约 30 亿美元美援疟疾等项目禁止 NAFDAC 审查物资，引发不安全与主权丧失恐慌，并称加纳已拒绝。\n\nNAFDAC 局长 Mojisola Adeyeye 教授 2026 年 10 月 20 日澄清：机构保留完整权限；FDA 已批产品可加快审评，但皆须安全检查，非美产品尤然，并以区块链追踪。2025 年 12 月签署的五年谅解备忘录提供近 20 亿美元递减美方拨款用于艾滋病等卫生项目，尼日利亚同步将本国投入提至约 30 亿美元以增强自立。", "url": "https://x.com/i/trending/2112833225118625949", "category": "News", "topics": ["News"], "updated_at": "2026-10-21T11:29:22.000Z"}, {"id": "2112684362596766177", "domain": "科学", "title_en": "Viggle JST-2 and Dream Labs Dream-1 Launch Fast AI Tools for 3D and Robots", "title_zh": "Viggle JST-2 与 Dream Labs Dream-1 推出快速 3D 与机器人 AI 工具", "hook_en": "Imagine generating a full 3D world in one second for under a penny, or powering robots you've never seen before at just $3 an hour. Two new AI models make these feats real this week.", "hook_zh": "一秒生成完整三维世界、成本不到一美分，或是用每小时约 3 美元驱动从未见过的机器人——两款新模型本周让这些场景成真。", "summary_en": "Viggle released JST-2, the first full-stack physics-native world foundation model that builds 3D scenes from scratch in about one second for less than a cent, allowing real-time expansion from any angle with characters and motion from text or video. Dream Labs debuted Dream-1 from stealth, a robot foundation model backed by a $90 million seed round, which controls unfamiliar bimanual robots on new tasks via a public API starting at $3 per hour. Early testers praised quick successes like playground tasks on rover arms, though finer precision needs work, pointing to lower barriers for creators in simulations, games, and robotics.", "summary_zh": "Viggle 发布 JST-2，号称首个全栈、物理原生的世界基础模型，可在约一秒内从零构建三维场景，成本不足一美分，并能从任意角度实时扩展，用文本或视频加入角色与动作。Dream Labs 则从隐身状态亮相 Dream-1，这是一款机器人基础模型，获 9000 万美元种子轮支持，可通过公开 API 以每小时约 3 美元起控制陌生双臂机器人完成新任务。早期测试者称在漫游车机械臂上能较快完成场地任务，但精细精度仍待提升，整体降低了仿真、游戏与机器人创作者的门槛。", "body_en": "Viggle JST-2 and Dream Labs Dream-1 Launch Fast AI Tools for 3D and Robots.\n\nImagine generating a full 3D world in one second for under a penny, or powering robots you've never seen before at just $3 an hour. Two new AI models make these feats real this week.\n\nViggle released JST-2, the first full-stack physics-native world foundation model that builds 3D scenes from scratch in about one second for less than a cent, allowing real-time expansion from any angle with characters and motion from text or video.\n\nDream Labs debuted Dream-1 from stealth, a robot foundation model backed by a $90 million seed round, which controls unfamiliar bimanual robots on new tasks via a public API starting at $3 per hour. Early testers praised quick successes like playground tasks on rover arms, though finer precision needs work, pointing to lower barriers for creators in simulations, games, and robotics.", "body_zh": "Viggle JST-2 与 Dream Labs Dream-1 推出快速 3D 与机器人 AI 工具。\n\n一秒生成完整三维世界、成本不到一美分，或是用每小时约 3 美元驱动从未见过的机器人——两款新模型本周让这些场景成真。\n\nViggle 发布 JST-2，号称首个全栈、物理原生的世界基础模型，可在约一秒内从零构建三维场景，成本不足一美分，并能从任意角度实时扩展，用文本或视频加入角色与动作。\n\nDream Labs 则从隐身状态亮相 Dream-1，这是一款机器人基础模型，获 9000 万美元种子轮支持，可通过公开 API 以每小时约 3 美元起控制陌生双臂机器人完成新任务。早期测试者称在漫游车机械臂上能较快完成场地任务，但精细精度仍待提升，整体降低了仿真、游戏与机器人创作者的门槛。", "url": "https://x.com/i/trending/2112684362596766177", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T23:23:26.000Z"}, {"id": "2112620323275485557", "domain": "科学", "title_en": "SophontAI Launches Holon-S1 to Predict Tumor Biology from Routine Slides", "title_zh": "SophontAI 发布 Holon-S1：从常规病理切片预测肿瘤生物学", "hook_en": "Cancer patients often share the same diagnosis but have wildly different tumor behaviors. SophontAI's new Holon-S1 changes that by unlocking molecular insights straight from everyday pathology slides.", "hook_zh": "同样诊断的癌症患者肿瘤行为可能迥异；Holon-S1 从日常病理片直接读出分子线索。", "summary_en": "Holon-S1 predicts genes, biomarkers, and biological pathways directly from standard H&E slides that most patients already get, skipping slow and costly molecular tests. In tests, it beat leading models across 16 organ types, spotted novel breast and colon cancer biomarkers, and even analyzed a rare osteosarcoma case—matching a patient's real treatment findings on fibroblast genes like FAP. Co-founder Paul Scotti and CEO Tanishq Mathew Abraham stressed its interpretable biology, with shoutouts from Google's Jeff Dean and investor José Maria Macedo highlighting its promise for broader access to personalized tumor insights.", "summary_zh": "Holon-S1 可从多数患者已有的标准 H&E 切片预测基因、生物标志物与通路，跳过缓慢昂贵的分子检测。测试中其在 16 种器官上优于领先模型，发现乳腺与结肠癌新标志物，并分析罕见骨肉瘤病例——在 FAP 等成纤维基因上与患者真实治疗发现吻合。联合创始人与 CEO 强调可解释生物学；谷歌 Jeff Dean 与投资人等点赞其扩大个性化肿瘤洞察可及性。", "body_en": "SophontAI Launches Holon-S1 to Predict Tumor Biology from Routine Slides.\n\nCancer patients often share the same diagnosis but have wildly different tumor behaviors. SophontAI's new Holon-S1 changes that by unlocking molecular insights straight from everyday pathology slides.\n\nHolon-S1 predicts genes, biomarkers, and biological pathways directly from standard H&E slides that most patients already get, skipping slow and costly molecular tests.\n\nIn tests, it beat leading models across 16 organ types, spotted novel breast and colon cancer biomarkers, and even analyzed a rare osteosarcoma case—matching a patient's real treatment findings on fibroblast genes like FAP. Co-founder Paul Scotti and CEO Tanishq Mathew Abraham stressed its interpretable biology, with shoutouts from Google's Jeff Dean and investor José Maria Macedo highlighting its promise for broader access to personalized tumor insights.", "body_zh": "SophontAI 发布 Holon-S1：从常规病理切片预测肿瘤生物学。\n\n同样诊断的癌症患者肿瘤行为可能迥异；Holon-S1 从日常病理片直接读出分子线索。\n\nHolon-S1 可从多数患者已有的标准 H&E 切片预测基因、生物标志物与通路，跳过缓慢昂贵的分子检测。测试中其在 16 种器官上优于领先模型，发现乳腺与结肠癌新标志物，并分析罕见骨肉瘤病例——在 FAP 等成纤维基因上与患者真实治疗发现吻合。\n\n联合创始人与 CEO 强调可解释生物学；谷歌 Jeff Dean 与投资人等点赞其扩大个性化肿瘤洞察可及性。", "url": "https://x.com/i/trending/2112620323275485557", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T01:29:19.000Z"}, {"id": "2112552619117891920", "domain": "科学", "title_en": "Review Identifies 37 Anticancer Mechanisms for Ivermectin and Mebendazole Combo", "title_zh": "综述：伊维菌素与甲苯咪唑联用现 37 种抗癌机制", "hook_en": "A detailed scientific review uncovers 37 ways ivermectin and mebendazole team up against cancer cells across 25 human types, drawing from over 100 lab and animal studies.", "hook_zh": "详细科学综述梳理逾 100 项实验室与动物研究，归纳两种药物在 25 种人类癌症中协同对抗癌细胞的 37 种方式。", "summary_en": "Researchers at the McCullough Foundation, including Nicolas Hulscher, Peter A. McCullough, and Harvey Risch, synthesized preclinical evidence showing the drugs disrupt cancer cell division, trigger cell death, block energy and blood vessel growth, and more. The 44-page paper notes their low cost, off-patent status, and long safety record in humans, with overlapping effects on key cancer processes. While calling for large clinical trials, it references limited human reports like a Polish woman's normalized markers after using the combo, though experts stress the need for randomized trials amid some study retractions.", "summary_zh": "McCullough 基金会 Nicolas Hulscher、Peter A. McCullough、Harvey Risch 等综合临床前证据，显示药物可干扰癌细胞分裂、诱导死亡、阻断能量与血管生成等。44 页论文强调其成本低、已过专利、人类长期用药安全记录，以及对关键癌症过程有重叠作用。作者呼吁大型临床试验，并提及波兰一病例用药后指标正常化等有限人体报告；专家仍强调需随机试验，且部分研究曾遭撤稿。", "body_en": "Review Identifies 37 Anticancer Mechanisms for Ivermectin and Mebendazole Combo.\n\nA detailed scientific review uncovers 37 ways ivermectin and mebendazole team up against cancer cells across 25 human types, drawing from over 100 lab and animal studies.\n\nResearchers at the McCullough Foundation, including Nicolas Hulscher, Peter A. McCullough, and Harvey Risch, synthesized preclinical evidence showing the drugs disrupt cancer cell division, trigger cell death, block energy and blood vessel growth, and more.\n\nThe 44-page paper notes their low cost, off-patent status, and long safety record in humans, with overlapping effects on key cancer processes. While calling for large clinical trials, it references limited human reports like a Polish woman's normalized markers after using the combo, though experts stress the need for randomized trials amid some study retractions.", "body_zh": "综述：伊维菌素与甲苯咪唑联用现 37 种抗癌机制。\n\n详细科学综述梳理逾 100 项实验室与动物研究，归纳两种药物在 25 种人类癌症中协同对抗癌细胞的 37 种方式。\n\nMcCullough 基金会 Nicolas Hulscher、Peter A. McCullough、Harvey Risch 等综合临床前证据，显示药物可干扰癌细胞分裂、诱导死亡、阻断能量与血管生成等。44 页论文强调其成本低、已过专利、人类长期用药安全记录，以及对关键癌症过程有重叠作用。\n\n作者呼吁大型临床试验，并提及波兰一病例用药后指标正常化等有限人体报告；专家仍强调需随机试验，且部分研究曾遭撤稿。", "url": "https://x.com/i/trending/2112552619117891920", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-20T20:43:03.000Z"}, {"id": "2112623559876952326", "domain": "科学", "title_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test", "title_zh": "Reflect Orbital 在加州沙漠模拟「轨道阳光」", "hook_en": "In a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.", "hook_zh": "惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。", "summary_en": "On October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams. The demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "summary_zh": "Reflect Orbital 用地面灯具照亮约三英里范围，测试搜救用途；并预告将发射带镜子的卫星星座，向目标区域投送定向阳光。", "body_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test.\n\nIn a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.\n\nOn October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams.\n\nThe demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "body_zh": "Reflect Orbital 在加州沙漠模拟「轨道阳光」。\n\n惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。\n\nReflect Orbital 用地面灯具照亮约三英里范围，测试搜救用途；并预告将发射带镜子的卫星星座，向目标区域投送定向阳光。\n\n综合以上信息，Reflect Orbital 在加州沙漠模拟「轨道阳光」一事持续引发关注。", "url": "https://x.com/i/trending/2112623559876952326", "category": "News", "topics": ["Technology", "Space"], "updated_at": "2026-10-21T00:18:52.000Z"}, {"id": "2112640445633499411", "domain": "科学", "title_en": "Electric Plant Launches Bombadil AI to Read Plant Electrical Signals", "title_zh": "Electric Plant 推出 Bombadil：解读植物电信号的 AI", "hook_en": "Imagine slipping a tiny sensor into a plant and getting a real-time readout of its health, just like monitoring brainwaves. Electric Plant's new AI, Bombadil, makes that possible by decoding subtle electrical signals from living plants.", "hook_zh": "像监测脑电一样，把微型传感器接入植物即可实时读健康——Bombadil 解码活体植物微弱电信号。", "summary_en": "The startup pairs low-cost Bud sensors with Bombadil, a foundation model trained on over seven million hours of data from 125 plant species, to track stress, water needs, photosynthesis efficiency, and more. Co-founder Justin Mast says it could cut water use by 20 percent or more for growers by enabling precise irrigation based on individual plant signals rather than soil alone. Backed by an $11.2 million seed round, the team—from neuroscientists to AI experts—built it after years of recording signals in labs, forests, and orchards, with early enthusiasm for its potential in farming and climate tech.", "summary_zh": "初创公司将低成本 Bud 传感器与在 125 种植物、逾 700 万小时数据上训练的基础模型 Bombadil 组合，追踪胁迫、需水、光合效率等。联合创始人 Justin Mast 称，按单株信号而非仅土壤精准灌溉，种植者用水或可降 20% 以上。种子轮 1120 万美元；团队含神经科学家与 AI 专家，经年在实验室、森林与果园记录信号，农业与气候科技前景获早期热捧。", "body_en": "Electric Plant Launches Bombadil AI to Read Plant Electrical Signals.\n\nImagine slipping a tiny sensor into a plant and getting a real-time readout of its health, just like monitoring brainwaves. Electric Plant's new AI, Bombadil, makes that possible by decoding subtle electrical signals from living plants.\n\nThe startup pairs low-cost Bud sensors with Bombadil, a foundation model trained on over seven million hours of data from 125 plant species, to track stress, water needs, photosynthesis efficiency, and more.\n\nCo-founder Justin Mast says it could cut water use by 20 percent or more for growers by enabling precise irrigation based on individual plant signals rather than soil alone. Backed by an $11.2 million seed round, the team—from neuroscientists to AI experts—built it after years of recording signals in labs, forests, and orchards, with early enthusiasm for its potential in farming and climate tech.", "body_zh": "Electric Plant 推出 Bombadil：解读植物电信号的 AI。\n\n像监测脑电一样，把微型传感器接入植物即可实时读健康——Bombadil 解码活体植物微弱电信号。\n\n初创公司将低成本 Bud 传感器与在 125 种植物、逾 700 万小时数据上训练的基础模型 Bombadil 组合，追踪胁迫、需水、光合效率等。联合创始人 Justin Mast 称，按单株信号而非仅土壤精准灌溉，种植者用水或可降 20% 以上。\n\n种子轮 1120 万美元；团队含神经科学家与 AI 专家，经年在实验室、森林与果园记录信号，农业与气候科技前景获早期热捧。", "url": "https://x.com/i/trending/2112640445633499411", "category": "News", "topics": ["Technology", "Biotech"], "updated_at": "2026-10-20T20:33:11.000Z"}, {"id": "2112802744491000212", "domain": "科学", "title_en": "UN Report: 1.5°C Warming Limit Now Requires Temporary Overshoot", "title_zh": "联合国报告：暂时超越 1.5°C 已不可避免，但仍可逆转", "hook_en": "The UN's latest report delivers a sobering update: holding global warming to 1.5°C means briefly exceeding it before pulling back. UNEP chief Inger Andersen insists it's still possible to limit the damage.", "hook_zh": "联合国传来沉重消息：数十年气候行动迟缓意味着将暂时突破 1.5°C 升温上限；但领导层称紧急行动仍可在本世纪末把温度拉回。", "summary_en": "The annual UN Emissions Gap Report, released ahead of COP31 in Turkey, states that the Paris Agreement's 1.5°C goal can no longer be met without overshooting to about 1.7-1.8°C mid-century, then returning by 2100. This demands global emissions cuts of 18% by 2030, 45% by 2035, and 69% by 2040 from 2025 levels, plus massive carbon removal—far beyond current pledges that lead to 2.6°C warming. Current policies without change point to 2.8°C, amid record-high emissions and reliance on coal. Andersen calls for urgent action across energy, industry, and methane to shorten any overshoot.", "summary_zh": "联合国环境规划署《2026 排放差距报告》警告，现行政策指向升温约 2.8°C，国家承诺可压至约 2.6°C。即便乐观路径，本世纪中叶仍见 1.7–1.8°C，之后才可能于 2100 年回到 1.5°C，需相对 2025 年水平在 2030 年减排 18%、2035 年 45%、2040 年 69%，并大规模碳移除。UNEP 负责人 Inger Andersen 与古特雷斯强调，要将「超标」幅度压到最小，必须立即全力以赴，在煤油气排放仍升之际依托可再生扩张。", "body_en": "UN Report: 1.5°C Limit Overshoot Now Inevitable.\n\nYears of slow action have closed the door on staying below 1.5°C warming without a temporary breach. The focus shifts to limiting how high and how long temperatures climb before dropping back.\n\nThe UN Environment Programme’s 2026 Emissions Gap Report states that global warming will exceed the Paris Agreement’s 1.5°C target in coming years, with the best-case peak at 1.7–1.8°C mid-century and a 50% chance of returning below 1.5°C by 2100. This requires emissions cuts of 18% by 2030, 45% by 2035, and 69% by 2040 from 2025 levels, plus large-scale carbon removal.\n\nCurrent pledges only achieve 5–8% cuts by 2030, heading toward 2.6°C or more warming. UNEP’s Inger Andersen calls for urgent action to minimize risks like floods and heatwaves ahead of COP31 talks.", "body_zh": "联合国报告：暂时超越 1.5°C 已不可避免，但仍可逆转。\n\n联合国传来沉重消息：数十年气候行动迟缓意味着将暂时突破 1.5°C 升温上限；但领导层称紧急行动仍可在本世纪末把温度拉回。\n\n联合国环境规划署《2026 排放差距报告》警告，现行政策指向升温约 2.8°C，国家承诺可压至约 2.6°C。即便乐观路径，本世纪中叶仍见 1.7–1.8°C，之后才可能于 2100 年回到 1.5°C，需相对 2025 年水平在 2030 年减排 18%、2035 年 45%、2040 年 69%，并大规模碳移除。\n\nUNEP 负责人 Inger Andersen 与古特雷斯强调，要将「超标」幅度压到最小，必须立即全力以赴，在煤油气排放仍升之际依托可再生扩张。", "url": "https://x.com/i/trending/2112802744491000212", "category": "News", "topics": ["Science"], "updated_at": "2026-10-21T12:07:55.000Z"}, {"id": "2112852934581162367", "domain": "科学", "title_en": "Pakistan's First Comprehensive Stroke Centre Opens in Karachi", "title_zh": "巴基斯坦首家综合卒中中心在卡拉奇启用", "hook_en": "In Karachi, a new centre is saving precious time for stroke patients with round-the-clock scans and treatments—all completely free.", "hook_zh": "卡拉奇新中心为卒中患者提供全天候影像与治疗，且完全免费，争分夺秒。", "summary_en": "The Department of Neurology and Stroke Unit at Jinnah Postgraduate Medical Centre (JPMC) has launched Pakistan’s first Comprehensive Stroke Centre, offering advanced care for ischemic and hemorrhagic strokes, aneurysms, and more through minimally invasive techniques. Equipped with biplane angiography systems, a dedicated 24/7 CT scanner, a 15-bed Neuro-ICU, and step-down beds, it provides rapid diagnosis and intensive support at no cost. Developed via a partnership between the Pakistan Stroke Initiative, Patients’ Aid Foundation, and JPMC with Sindh government backing, the facility addresses past gaps in affordable neurointerventional services and has already performed life-saving procedures like mechanical clot removal.", "summary_zh": "真纳研究生医学中心神经科与卒中单元启用全国首家综合卒中中心，以微创技术覆盖缺血性、出血性卒中与动脉瘤等。配置双平面血管造影、24 小时专用 CT、15 张神经重症床及过渡床位，诊断与重症支持不收费。由巴基斯坦卒中倡议、Patients’ Aid Foundation 与医院在信德省政府支持下建设，已开展机械取栓等救治，填补可负担神经介入空白。", "body_en": "Pakistan's First Comprehensive Stroke Centre Opens in Karachi.\n\nIn Karachi, a new centre is saving precious time for stroke patients with round-the-clock scans and treatments—all completely free.\n\nThe Department of Neurology and Stroke Unit at Jinnah Postgraduate Medical Centre (JPMC) has launched Pakistan’s first Comprehensive Stroke Centre, offering advanced care for ischemic and hemorrhagic strokes, aneurysms, and more through minimally invasive techniques.\n\nEquipped with biplane angiography systems, a dedicated 24/7 CT scanner, a 15-bed Neuro-ICU, and step-down beds, it provides rapid diagnosis and intensive support at no cost. Developed via a partnership between the Pakistan Stroke Initiative, Patients’ Aid Foundation, and JPMC with Sindh government backing, the facility addresses past gaps in affordable neurointerventional services and has already performed life-saving procedures like mechanical clot removal.", "body_zh": "巴基斯坦首家综合卒中中心在卡拉奇启用。\n\n卡拉奇新中心为卒中患者提供全天候影像与治疗，且完全免费，争分夺秒。\n\n真纳研究生医学中心神经科与卒中单元启用全国首家综合卒中中心，以微创技术覆盖缺血性、出血性卒中与动脉瘤等。\n\n配置双平面血管造影、24 小时专用 CT、15 张神经重症床及过渡床位，诊断与重症支持不收费。由巴基斯坦卒中倡议、Patients’ Aid Foundation 与医院在信德省政府支持下建设，已开展机械取栓等救治，填补可负担神经介入空白。", "url": "https://x.com/i/trending/2112852934581162367", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-21T12:59:54.000Z"}, {"id": "2111892089000915435", "domain": "科学", "title_en": "President Ruto Launches Key Projects in Kapsabet Amid Huge Crowds", "title_zh": "鲁托总统在卡普萨贝特启动多项民生工程，万人夹道", "hook_en": "Thousands of residents in yellow caps lined Kapsabet's streets on October 18, cheering as President William Ruto arrived to unveil projects boosting healthcare, roads, and more.", "hook_zh": "10 月 18 日数千戴黄帽居民列队卡普萨贝特街头，欢呼威廉·鲁托总统到访揭幕医疗、道路等项目。", "summary_en": "Ruto opened the new Mother and Child Health Complex at Kapsabet County Referral Hospital, equipped with KSh392 million in modern tools and new intensive care units. He inspected the half-complete 10,000-seater stadium, laid a foundation for another hospital, commissioned the county headquarters, and committed to 12 km of local roads plus a four-lane highway upgrade. The visits also included flagging off a Sh351 million electricity project for thousands of homes and issuing Women Enterprise Fund cheques, with Governor Stephen Sang noting direct benefits to daily lives.", "summary_zh": "鲁托为卡普萨贝特县转诊医院新建母婴健康综合楼剪彩，配备价值约 3.92 亿肯先令的现代设备与新重症监护室。他视察半完工的万人体育场、为另一医院奠基、启用县总部，并承诺 12 公里地方道路与四车道公路升级。行程还包括启动约 3.51 亿肯先令电力项目惠及数千户，以及发放妇女企业基金支票；州长 Stephen Sang 称举措直接惠及日常生活。", "body_en": "President Ruto Launches Key Projects in Kapsabet Amid Huge Crowds.\n\nThousands of residents in yellow caps lined Kapsabet's streets on October 18, cheering as President William Ruto arrived to unveil projects boosting healthcare, roads, and more.\n\nRuto opened the new Mother and Child Health Complex at Kapsabet County Referral Hospital, equipped with KSh392 million in modern tools and new intensive care units.\n\nHe inspected the half-complete 10,000-seater stadium, laid a foundation for another hospital, commissioned the county headquarters, and committed to 12 km of local roads plus a four-lane highway upgrade. The visits also included flagging off a Sh351 million electricity project for thousands of homes and issuing Women Enterprise Fund cheques, with Governor Stephen Sang noting direct benefits to daily lives.", "body_zh": "鲁托总统在卡普萨贝特启动多项民生工程，万人夹道。\n\n10 月 18 日数千戴黄帽居民列队卡普萨贝特街头，欢呼威廉·鲁托总统到访揭幕医疗、道路等项目。\n\n鲁托为卡普萨贝特县转诊医院新建母婴健康综合楼剪彩，配备价值约 3.92 亿肯先令的现代设备与新重症监护室。他视察半完工的万人体育场、为另一医院奠基、启用县总部，并承诺 12 公里地方道路与四车道公路升级。\n\n行程还包括启动约 3.51 亿肯先令电力项目惠及数千户，以及发放妇女企业基金支票；州长 Stephen Sang 称举措直接惠及日常生活。", "url": "https://x.com/i/trending/2111892089000915435", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-20T06:36:12.000Z"}, {"id": "2112414671194009776", "domain": "科学", "title_en": "Rocket Lab Videos Automated Machine Building Neutron Rocket Dome", "title_zh": "火箭实验室晒自动铺丝机制作 Neutron 整流罩穹顶", "hook_en": "Thousands of hair-thin carbon fibers whip into place at blistering speeds, forming the massive forward dome for Neutron's Stage 1 tank. It's a glimpse into the precision powering Rocket Lab's next big leap.", "hook_zh": "成千上万根发丝般碳纤维高速铺就 Neutron 一级贮箱巨大前穹顶。", "summary_en": "Rocket Lab released footage of its automated fiber placement machine at the Maryland facility laying down carbon strands up to 100 meters per minute on custom molds for the Neutron rocket's large composite forward dome. This step follows last week's news of a 2027 first-launch target after fixing voids in a prior manual dome, with CEO Peter Beck confirming refined processes and a successful aft dome. Investors and fans praised the update for building excitement around production progress toward a reusable rocket carrying 13,000 kg to orbit, with upcoming tests ahead.", "summary_zh": "火箭实验室公布马里兰工厂自动铺丝机画面：以最高约每分钟 100 米在定制模具上铺碳丝，制作 Neutron 大型复合材料前穹顶。此前手工穹顶空隙问题已修复，CEO 彼得·贝克确认工艺改进与后穹顶成功，首飞目标 2027 年。投资者与粉丝为可复用、运力约 1.3 万公斤入轨的火箭量产进展叫好，后续测试将至。", "body_en": "Rocket Lab Videos Automated Machine Building Neutron Rocket Dome.\n\nThousands of hair-thin carbon fibers whip into place at blistering speeds, forming the massive forward dome for Neutron's Stage 1 tank. It's a glimpse into the precision powering Rocket Lab's next big leap.\n\nRocket Lab released footage of its automated fiber placement machine at the Maryland facility laying down carbon strands up to 100 meters per minute on custom molds for the Neutron rocket's large composite forward dome.\n\nThis step follows last week's news of a 2027 first-launch target after fixing voids in a prior manual dome, with CEO Peter Beck confirming refined processes and a successful aft dome. Investors and fans praised the update for building excitement around production progress toward a reusable rocket carrying 13,000 kg to orbit, with upcoming tests ahead.", "body_zh": "火箭实验室晒自动铺丝机制作 Neutron 整流罩穹顶。\n\n成千上万根发丝般碳纤维高速铺就 Neutron 一级贮箱巨大前穹顶。\n\n火箭实验室公布马里兰工厂自动铺丝机画面：以最高约每分钟 100 米在定制模具上铺碳丝，制作 Neutron 大型复合材料前穹顶。此前手工穹顶空隙问题已修复，CEO 彼得·贝克确认工艺改进与后穹顶成功，首飞目标 2027 年。\n\n投资者与粉丝为可复用、运力约 1.3 万公斤入轨的火箭量产进展叫好，后续测试将至。", "url": "https://x.com/i/trending/2112414671194009776", "category": "News", "topics": ["Technology", "Space"], "updated_at": "2026-10-20T05:28:17.000Z"}]};
